const lessons = [
    {num:2,time:"00:00:30,000 --> 00:00:31,000",arabic:"رَحِمَكَ اللَّهُ",segs:null,full_uz:"Alloh seni rahmatiga olsin.",note:null},
{num:3,time:"00:00:35,000 --> 00:00:39,000",arabic:"لَقَدْ كُنْتَ حِصْنًا مِنْ حُصُونِ هَذِهِ الْأُمَّةِ",segs:["لَقَدْ كُنْتَ حِصْنًا","مِنْ حُصُونِ هَذِهِ الْأُمَّةِ"],full_uz:"Sen bu ummatning qal’alaridan biri eding.",note:"حِصْنٌ — «qal’a»; حُصُونٌ — uning ko‘pligi."},
{num:4,time:"00:00:41,000 --> 00:00:44,000",arabic:"أَخْيَرُ مُعَلِّمٍ إِنِ اسْتَقَيْنَا مِنْهُ الْعِلْمَ",segs:["أَخْيَرُ مُعَلِّمٍ","إِنِ اسْتَقَيْنَا مِنْهُ الْعِلْمَ"],full_uz:"Undan ilm olganimiz eng yaxshi ustozlardan biri edi.",note:"اِسْتَقَى مِنْهُ الْعِلْمَ — «undan ilm olmoq, ilmni undan o‘zlashtirmoq»."},
{num:5,time:"00:00:45,000 --> 00:00:47,000",arabic:"رَحِمَكَ اللَّهُ",segs:null,full_uz:"Alloh seni rahmatiga olsin.",note:null},
{num:6,time:"00:00:57,000 --> 00:00:59,000",arabic:"تَفَضَّلِي يَا أُمَّ خَالِدٍ تَفَضَّلِي",segs:["تَفَضَّلِي يَا أُمَّ خَالِدٍ","تَفَضَّلِي"],full_uz:"Marhamat, ey Ummu Xolid, marhamat.",note:null},
{num:7,time:"00:01:00,000 --> 00:01:09,400",arabic:"أَتَذْكُرِينَ يَا أُمَّ أَحْمَدَ يَوْمَ جِئْتُكِ وَمَعِيَ نِسْوَةٌ مِنَ الْحَيِّ لِيَقْرَأَ أَحْمَدُ رَسَائِلَ أَزْوَاجِهِنَّ؟",segs:["أَتَذْكُرِينَ يَا أُمَّ أَحْمَدَ","يَوْمَ جِئْتُكِ وَمَعِيَ نِسْوَةٌ مِنَ الْحَيِّ","لِيَقْرَأَ أَحْمَدُ رَسَائِلَ أَزْوَاجِهِنَّ؟"],full_uz:"Ey Ummu Ahmad, mahalladagi ayollar bilan kelib, Ahmad ularning erlaridan kelgan maktublarni o‘qib bergan kunni eslaysizmi?",note:"نِسْوَةٌ — «ayollar»; الْحَيُّ — «mahalla, yashash hududi»."},
{num:8,time:"00:01:09,400 --> 00:01:11,599",arabic:"أَجَلْ أَذْكُرُ يَا أُمَّ خَيْرٍ أَذْكُرُ",segs:["أَجَلْ أَذْكُرُ","يَا أُمَّ خَيْرٍ","أَذْكُرُ"],full_uz:"Ha, eslayman, ey Ummu Xayr, eslayman.",note:null},
{num:9,time:"00:01:11,599 --> 00:01:16,200",arabic:"كَانَتْ مِنْ بَيْنِ أُولَئِكَ النِّسْوَةِ أُمُّ عُمَرَ الدِّمَشْقِيَّةُ",segs:["كَانَتْ مِنْ بَيْنِ أُولَئِكَ النِّسْوَةِ","أُمُّ عُمَرَ الدِّمَشْقِيَّةُ"],full_uz:"O‘sha ayollar orasida Ummu Umar ad-Dimashqiyya ham bor edi.",note:"الدِّمَشْقِيَّةُ — «Damashqlik ayol»."},
{num:10,time:"00:01:16,200 --> 00:01:20,819",arabic:"زَوْجُهَا يَعْمَلُ حَائِكًا لِلسَّجَّادِ وَالْحَصِيرِ",segs:["زَوْجُهَا يَعْمَلُ حَائِكًا","لِلسَّجَّادِ وَالْحَصِيرِ"],full_uz:"Uning eri gilam va bo‘yra to‘quvchisi bo‘lib ishlaydi.",note:"حَائِكٌ — «to‘quvchi»; حَصِيرٌ — «bo‘yra, qamishdan to‘qilgan gilam»."},
{num:11,time:"00:01:20,819 --> 00:01:24,120",arabic:"أَجَلْ تَذَكَّرْتُهَا مَا بِهَا؟",segs:["أَجَلْ تَذَكَّرْتُهَا","مَا بِهَا؟"],full_uz:"Ha, uni esladim. Nima bo‘ldi unga?",note:"مَا بِهَا؟ — «unga nima bo‘ldi?, nima gap?»."},
{num:12,time:"00:01:24,120 --> 00:01:26,719",arabic:"لَقَدْ طَلَبَتْ مِنِّي أَنْ تَحِيكِيَ لَهَا سَجَّادَةً",segs:["لَقَدْ طَلَبَتْ مِنِّي","أَنْ تَحِيكِيَ لَهَا سَجَّادَةً"],full_uz:"U mendan unga bir gilam to‘qib berishingizni so‘radi.",note:"حَاكَ — «to‘qimoq»; سَجَّادَةٌ — «gilam»."},
{num:13,time:"00:01:26,719 --> 00:01:30,480",arabic:"وَقَدْ أَرْسَلَتْ هَذَا الصُّوفَ لِتُبَاشِرِي عَمَلَكِ",segs:["وَقَدْ أَرْسَلَتْ هَذَا الصُّوفَ","لِتُبَاشِرِي عَمَلَكِ"],full_uz:"U ishni boshlashingiz uchun mana shu junni yubordi.",note:"بَاشَرَ الْعَمَلَ — «ishni boshlamoq, ishga kirishmoq»."},
{num:14,time:"00:01:30,480 --> 00:01:40,060",arabic:"تَأْخُذُ أُمُّ عُمَرَ الدِّمَشْقِيَّةُ مَا تَحِيكِينَهُ لِزَوْجِهَا لِيَبِيعَهُ فِي السُّوقِ",segs:["تَأْخُذُ أُمُّ عُمَرَ الدِّمَشْقِيَّةُ مَا تَحِيكِينَهُ لِزَوْجِهَا","لِيَبِيعَهُ فِي السُّوقِ"],full_uz:"Ummu Umar ad-Dimashqiyya siz to‘qigan narsalarni eriga beradi, u esa bozorda sotadi.",note:null},
{num:15,time:"00:01:40,060 --> 00:01:44,520",arabic:"ثُمَّ تُعْطِيكِ أَجْرًا بَعْدَ أَنْ تَقْطَعَ ثَمَنَ الصُّوفِ",segs:["ثُمَّ تُعْطِيكِ أَجْرًا","بَعْدَ أَنْ تَقْطَعَ ثَمَنَ الصُّوفِ"],full_uz:"Keyin jun narxini chegirgach, sizga haqingizni beradi.",note:"أَجْرٌ — «haq, mehnat haqi»; قَطَعَ ثَمَنَ الشَّيْءِ — «narxini ayirib tashlamoq»."},
{num:16,time:"00:01:44,520 --> 00:01:46,120",arabic:"مَا رَأْيُكِ؟",segs:null,full_uz:"Nima deb o‘ylaysiz?",note:null},
{num:17,time:"00:01:46,700 --> 00:01:48,820",arabic:"جَزَاكِ اللَّهُ خَيْرًا يَا أُمَّ خَالِدٍ",segs:["جَزَاكِ اللَّهُ خَيْرًا","يَا أُمَّ خَالِدٍ"],full_uz:"Alloh sizni yaxshilik bilan mukofotlasin, ey Ummu Xolid.",note:null},
{num:18,time:"00:01:48,820 --> 00:01:51,120",arabic:"وَجَزَى أُمَّ عُمَرَ مِثْلَهُ",segs:["وَجَزَى أُمَّ عُمَرَ","مِثْلَهُ"],full_uz:"Ummu Umarni ham shunday mukofotlasin.",note:null},
{num:19,time:"00:01:51,120 --> 00:01:52,600",arabic:"وَلَكِنْ",segs:null,full_uz:"Lekin...",note:null},
{num:20,time:"00:01:52,599 --> 00:01:55,599",arabic:"وَلَكِنْ مَاذَا يَا أُمَّ أَحْمَدَ؟",segs:["وَلَكِنْ مَاذَا","يَا أُمَّ أَحْمَدَ؟"],full_uz:"Lekin nima, ey Ummu Ahmad?",note:null},
{num:21,time:"00:01:57,679 --> 00:02:02,819",arabic:"وَلَدِي يَا أُمَّ خَالِدٍ أَخْشَى أَنْ يَبْتَئِسَ وَيَمْتَعِضَ",segs:["وَلَدِي يَا أُمَّ خَالِدٍ","أَخْشَى أَنْ يَبْتَئِسَ وَيَمْتَعِضَ"],full_uz:"Bolamdan, ey Ummu Xolid, ranjib qolishidan va ko‘ngli og‘rishidan qo‘rqaman.",note:"يَبْتَئِسُ — «g‘amga botmoq, ranjimoq»; يَمْتَعِضُ — «ko‘ngli og‘rimoq, norozi bo‘lmoq»."},
{num:22,time:"00:02:02,819 --> 00:02:07,599",arabic:"وَلِمَ؟ أَيُزْعِجُهُ أَنْ تَكْسِبَ أُمُّهُ مَالًا حَلَالًا فِي وَقْتِ فَرَاغِهَا؟",segs:["وَلِمَ؟","أَيُزْعِجُهُ أَنْ تَكْسِبَ أُمُّهُ مَالًا حَلَالًا","فِي وَقْتِ فَرَاغِهَا؟"],full_uz:"Nega? Onasi bo‘sh vaqtida halol pul topsa, bu uni bezovta qiladimi?",note:"أَزْعَجَ — «bezovta qilmoq»; مَالٌ حَلَالٌ — «halol daromad»."},
{num:23,time:"00:02:08,519 --> 00:02:14,280",arabic:"وَلَدِي يَا أُمَّ خَالِدٍ يَشْعُرُ أَنَّهُ الْقَيِّمُ عَلَى الْبَيْتِ وَالْمَسْؤُولُ عَنْ أَمْرِ أُمِّهِ",segs:["وَلَدِي يَا أُمَّ خَالِدٍ يَشْعُرُ أَنَّهُ الْقَيِّمُ عَلَى الْبَيْتِ","وَالْمَسْؤُولُ عَنْ أَمْرِ أُمِّهِ"],full_uz:"Bolam o‘zini, ey Ummu Xolid, uyga mas’ul va onasining ishlariga javobgar deb his qiladi.",note:"الْقَيِّمُ عَلَى الْبَيْتِ — «uyga qarovchi, uyga mas’ul kishi»."},
{num:24,time:"00:02:14,280 --> 00:02:16,840",arabic:"وَهَذَا مَا دَفَعَهُ لِلْعَمَلِ مِنْ قَبْلُ",segs:["وَهَذَا مَا دَفَعَهُ لِلْعَمَلِ","مِنْ قَبْلُ"],full_uz:"Uni ilgari ishlashga undagan narsa ham shu edi.",note:"دَفَعَهُ لِـ — «uni biror ishga undamoq»."},
{num:25,time:"00:02:16,840 --> 00:02:21,639",arabic:"وَلَوْلَا أَنَّنِي أَقْنَعْتُهُ بِأَنَّنَا لَسْنَا بِحَاجَةٍ لِمَزِيدٍ مِنَ الْمَالِ",segs:["وَلَوْلَا أَنَّنِي أَقْنَعْتُهُ","بِأَنَّنَا لَسْنَا بِحَاجَةٍ لِمَزِيدٍ مِنَ الْمَالِ"],full_uz:"Agar men uni bizga bundan ortiq pul kerak emasligiga ishontirmaganimda,",note:"لَسْنَا بِحَاجَةٍ إِلَى — «biz ...ga muhtoj emasmiz»."},
{num:26,time:"00:02:21,639 --> 00:02:25,239",arabic:"لَمَا تَرَكَ عَمَلَهُ وَتَفَرَّغَ لِطَلَبِ الْعِلْمِ",segs:["لَمَا تَرَكَ عَمَلَهُ","وَتَفَرَّغَ لِطَلَبِ الْعِلْمِ"],full_uz:"u ishini tashlab, ilm talab qilishga to‘liq berilmagan bo‘lardi.",note:"تَفَرَّغَ لِـ — «butun vaqtini biror ishga bag‘ishlamoq»."},
{num:27,time:"00:02:25,239 --> 00:02:27,899",arabic:"حَاوِلِي إِقْنَاعَهُ يَا أُمَّ أَحْمَدَ",segs:["حَاوِلِي إِقْنَاعَهُ","يَا أُمَّ أَحْمَدَ"],full_uz:"Uni ishontirishga harakat qiling, ey Ummu Ahmad.",note:"حَاوَلَ إِقْنَاعَ — «ishontirishga harakat qilmoq»."},
{num:28,time:"00:02:27,899 --> 00:02:30,619",arabic:"سَأُحَاوِلُ",segs:null,full_uz:"Harakat qilaman.",note:null},
{num:29,time:"00:02:30,619 --> 00:02:33,959",arabic:"سَأُحَاوِلُ",segs:null,full_uz:"Harakat qilaman.",note:null},
{num:30,time:"00:02:33,959 --> 00:02:37,059",arabic:"حَدَّثَنَا يَحْيَى بْنُ سَعِيدٍ قَالَ",segs:["حَدَّثَنَا يَحْيَى بْنُ سَعِيدٍ","قَالَ"],full_uz:"Bizga Yahyo ibn Sa’id rivoyat qildi, u dedi:",note:"حَدَّثَنَا — hadis rivoyatida «bizga rivoyat qildi» ma’nosidagi sanad lafzi."},
{num:31,time:"00:02:37,059 --> 00:02:39,579",arabic:"حَدَّثَنَا سُلَيْمَانُ بْنُ يَسَارٍ",segs:null,full_uz:"Bizga Sulaymon ibn Yasar rivoyat qildi.",note:"حَدَّثَنَا — «bizga rivoyat qildi»."},
{num:32,time:"00:02:39,579 --> 00:02:41,799",arabic:"بَلْ عَنْ سُلَيْمَانَ بْنِ يَسَارٍ",segs:null,full_uz:"Yo‘q, «Sulaymon ibn Yasardan» deyiladi.",note:"عَنْ سُلَيْمَانَ — sanad lafzida «Sulaymondan» ma’nosida."},
{num:33,time:"00:02:41,799 --> 00:02:46,560",arabic:"عَنْ أُمِّ سَلَمَةَ زَوْجِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ",segs:["عَنْ أُمِّ سَلَمَةَ","زَوْجِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ"],full_uz:"Payg‘ambarning ﷺ zavjalari Ummu Salmadan.",note:"زَوْجُ النَّبِيِّ — «Payg‘ambarning zavjasi, xotini»."},
{num:34,time:"00:02:46,560 --> 00:02:48,339",arabic:"صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ",segs:null,full_uz:"Alloh u zotga salavot va salomlar yo‘llasin.",note:null},
{num:35,time:"00:02:48,340 --> 00:02:54,900",arabic:"أَنَّ سُبَيْعَةَ بِنْتَ الْحَارِثِ وَضَعَتْ بَعْدَ وَفَاةِ زَوْجِهَا بِعِشْرِينَ لَيْلَةً أَوْ نَحْوَ ذَلِكَ",segs:["أَنَّ سُبَيْعَةَ بِنْتَ الْحَارِثِ وَضَعَتْ بَعْدَ وَفَاةِ زَوْجِهَا","بِعِشْرِينَ لَيْلَةً أَوْ نَحْوَ ذَلِكَ"],full_uz:"Subay’a bint al-Horis eri vafotidan yigirma kecha yoki shunga yaqin vaqt o‘tib farzand ko‘rdi.",note:"وَضَعَتْ — ayolga nisbatan «tug‘moq, farzand ko‘rmoq»."},
{num:36,time:"00:02:54,900 --> 00:02:57,099",arabic:"وَأَرَادَتِ التَّزَوُّجَ",segs:null,full_uz:"U turmush qurishni istadi.",note:null},
{num:37,time:"00:02:57,099 --> 00:03:00,819",arabic:"فَقَالَ لَهَا أَبُو السَّنَابِلِ لَيْسَ لَكِ ذَلِكَ",segs:["فَقَالَ لَهَا أَبُو السَّنَابِلِ","لَيْسَ لَكِ ذَلِكَ"],full_uz:"Shunda Abu as-Sanobil unga: «Senga buning haqqi yo‘q», dedi.",note:"لَيْسَ لَكِ ذَلِكَ — «bunga haqqing yo‘q» ma’nosida."},
{num:38,time:"00:03:00,819 --> 00:03:04,039",arabic:"حَتَّى يَأْتِيَ عَلَيْكِ آخِرُ الْأَجَلَيْنِ",segs:["حَتَّى يَأْتِيَ عَلَيْكِ","آخِرُ الْأَجَلَيْنِ"],full_uz:"Toki ikki muddatning uzuni tugamaguncha.",note:"آخِرُ الْأَجَلَيْنِ — «ikki muddatning oxirgisi/uzuni»."},
{num:39,time:"00:03:04,039 --> 00:03:08,199",arabic:"فَذُكِرَ ذَلِكَ لِلنَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ",segs:["فَذُكِرَ ذَلِكَ لِلنَّبِيِّ","صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ"],full_uz:"Bu voqea Payg‘ambarga ﷺ aytib berildi.",note:"ذُكِرَ ذَلِكَ لِـ — «bu narsa ...ga aytib berildi»."},
{num:40,time:"00:03:08,199 --> 00:03:12,120",arabic:"فَقَالَ تَزَوَّجْ إِذَا شَاءَتْ",segs:["فَقَالَ","تَزَوَّجْ إِذَا شَاءَتْ"],full_uz:"Shunda u zot: «U istasa, turmush qursin», dedilar.",note:null},
{num:41,time:"00:03:12,120 --> 00:03:20,120",arabic:"مَا الْفَرْقُ بَيْنَ حَدَّثَنَا فُلَانٌ وَعَنْ فُلَانٍ؟",segs:["مَا الْفَرْقُ بَيْنَ حَدَّثَنَا فُلَانٌ","وَعَنْ فُلَانٍ؟"],full_uz:"«Bizga falonchi rivoyat qildi» bilan «falonchidan»ning farqi nima?",note:"فُلَانٌ — ismni aniq aytmasdan «falonchi» deyish uchun ishlatiladi."},
{num:42,time:"00:03:24,840 --> 00:03:27,120",arabic:"مَا لَكُمْ قَدْ سُقِطَ فِي أَيْدِيكُمْ؟",segs:["مَا لَكُمْ","قَدْ سُقِطَ فِي أَيْدِيكُمْ؟"],full_uz:"Sizlarga nima bo‘ldi, qo‘l-oyog‘ingiz tushib qoldimi?",note:"سُقِطَ فِي الْأَيْدِي — «ojiz qolmoq, nima qilishni bilmay qolmoq» mazmunidagi ibora."},
{num:43,time:"00:03:28,020 --> 00:03:29,659",arabic:"فَكَأَنَّ عَلَى رُؤُوسِكُمُ الطَّيْرَ",segs:null,full_uz:"Go‘yo boshingizda qush turgandek.",note:"كَأَنَّ عَلَى رُؤُوسِكُمُ الطَّيْرَ — jim, qimirlamay qolgan kishiga nisbatan ishlatiladigan ibora."},
{num:44,time:"00:03:29,659 --> 00:03:37,120",arabic:"لَا تَسْتَطِيعُونَ حِيلَةً وَلَا تَجِدُونَ جَوَابًا؟",segs:["لَا تَسْتَطِيعُونَ حِيلَةً","وَلَا تَجِدُونَ جَوَابًا؟"],full_uz:"Na biror chora topa olasizlar, na javob bera olasizlar?",note:"حِيلَةٌ — «chora, tadbir, yo‘l»."},
{num:45,time:"00:03:39,120 --> 00:03:41,080",arabic:"حَسَنًا أَيُّهَا الْفَتَى الشَّيْبَانِيُّ",segs:["حَسَنًا","أَيُّهَا الْفَتَى الشَّيْبَانِيُّ"],full_uz:"Xo‘sh, ey Shayboniy yigit.",note:null},
{num:46,time:"00:03:41,080 --> 00:03:43,920",arabic:"يَبْدُو أَنَّهُ لَيْسَ لَهَا إِلَّا أَنْتَ يَا أَحْمَدُ",segs:["يَبْدُو أَنَّهُ لَيْسَ لَهَا إِلَّا أَنْتَ","يَا أَحْمَدُ"],full_uz:"Ko‘rinib turibdiki, unga sendan boshqa hech kim yordam bera olmaydi, ey Ahmad.",note:"لَيْسَ لَهَا إِلَّا أَنْتَ — «uning uchun sendan boshqa hech kim yo‘q»."},
{num:47,time:"00:03:43,920 --> 00:03:45,820",arabic:"هَاتِ مَا عِنْدَكَ",segs:null,full_uz:"Qani, bor gapni ayt.",note:"هَاتِ مَا عِنْدَكَ — «bor narsangni ayt, bilganingni bayon qil»."},
{num:48,time:"00:03:45,820 --> 00:03:52,520",arabic:"الْفَرْقُ يَا شَيْخَنَا أَنَّ صِيغَةَ حَدَّثَنَا صَرِيحَةٌ فِي أَنَّ الشَّيْخَ قَدْ سَمِعَ مُبَاشَرَةً",segs:["الْفَرْقُ يَا شَيْخَنَا","أَنَّ صِيغَةَ حَدَّثَنَا صَرِيحَةٌ","فِي أَنَّ الشَّيْخَ قَدْ سَمِعَ مُبَاشَرَةً"],full_uz:"Farqi shuki, ey shayximiz, «haddasana» shakli shayx hadisni bevosita eshitganini aniq bildiradi.",note:"صِيغَةٌ — «shakl, ibora ko‘rinishi»; صَرِيحٌ — «ochiq, aniq»; مُبَاشَرَةً — «bevosita»."},
{num:49,time:"00:03:52,520 --> 00:03:54,420",arabic:"مِمَّنْ يَرْوِي الْحَدِيثَ عَنْهُ",segs:null,full_uz:"Hadisni o‘zidan rivoyat qilayotgan kishidan.",note:"رَوَى الْحَدِيثَ عَنْ — «hadisni ...dan rivoyat qilmoq»."},
{num:50,time:"00:03:54,420 --> 00:03:56,880",arabic:"بِخِلَافِ صِيغَةِ فُلَانٍ عَنْ فُلَانٍ",segs:null,full_uz:"«Falonchidan falonchi» shaklidan farqli ravishda.",note:"بِخِلَافِ — «...dan farqli ravishda»."},
{num:51,time:"00:03:56,880 --> 00:03:59,520",arabic:"فَلَيْسَ فِيهَا تَصْرِيحٌ وَاضِحٌ بِالسَّمَاعِ",segs:["فَلَيْسَ فِيهَا تَصْرِيحٌ وَاضِحٌ","بِالسَّمَاعِ"],full_uz:"Unda esa eshitganlik haqida aniq bayon yo‘q.",note:"تَصْرِيحٌ بِـ — «biror narsani ochiq-oydin bayon qilish»."},
{num:52,time:"00:03:59,520 --> 00:04:02,020",arabic:"بَارَكَ اللَّهُ بِكَ يَا أَحْمَدُ",segs:["بَارَكَ اللَّهُ بِكَ","يَا أَحْمَدُ"],full_uz:"Alloh seni barakali qilsin, ey Ahmad.",note:null},
{num:53,time:"00:04:02,020 --> 00:04:06,000",arabic:"السَّلَامُ عَلَيْكُمْ وَرَحْمَةُ اللَّهِ وَبَرَكَاتُهُ",segs:null,full_uz:"Assalomu alaykum va Allohning rahmati va barakotlari bo‘lsin.",note:null},
{num:54,time:"00:04:06,000 --> 00:04:08,960",arabic:"وَعَلَيْكُمُ السَّلَامُ وَرَحْمَةُ اللَّهِ وَبَرَكَاتُهُ",segs:null,full_uz:"Va alaykum assalom va Allohning rahmati va barakotlari bo‘lsin.",note:null},
{num:55,time:"00:04:11,080 --> 00:04:15,620",arabic:"لَا حَوْلَ وَلَا قُوَّةَ إِلَّا بِاللَّهِ",segs:null,full_uz:"Allohdan o‘zga hech qanday kuch va quvvat yo‘q.",note:"Bu zikr ojizlikni tan olish va ishni Allohga topshirishni bildiradi."},
{num:56,time:"00:04:15,620 --> 00:04:18,840",arabic:"إِنَّا لِلَّهِ وَإِنَّا إِلَيْهِ رَاجِعُونَ",segs:null,full_uz:"Albatta, biz Allohnikimiz va Unga qaytuvchilarmiz.",note:"Bu ibora odatda musibat yoki vafot xabarida aytiladi."},
{num:57,time:"00:04:18,840 --> 00:04:24,660",arabic:"أَحْسَنَ اللَّهُ عَزَاءَكُمْ فِي وَفَاةِ مَالِكِ بْنِ أَنَسٍ إِمَامِ دَارِ الْهِجْرَةِ",segs:["أَحْسَنَ اللَّهُ عَزَاءَكُمْ فِي وَفَاةِ مَالِكِ بْنِ أَنَسٍ","إِمَامِ دَارِ الْهِجْرَةِ"],full_uz:"Alloh Molik ibn Anas — Dorul-Hijra imomi vafoti sababli sizga sabr va ajr ato etsin.",note:"أَحْسَنَ اللَّهُ عَزَاءَكُمْ — «Alloh sizga tasalli va sabr bersin» ma’nosidagi ta’ziya iborasi; إِمَامُ دَارِ الْهِجْرَةِ — «Hijrat diyori imomi», ya’ni Imom Molikning mashhur laqabi."},
{num:58,time:"00:04:24,660 --> 00:04:32,180",arabic:"إِنَّا لِلَّهِ وَإِنَّا إِلَيْهِ رَاجِعُونَ",segs:null,full_uz:"Albatta, biz Allohnikimiz va Unga qaytuvchilarmiz.",note:null},
{num:59,time:"00:04:41,079 --> 00:04:43,079",arabic:"مُوسِيقَى",segs:null,full_uz:null,note:null},
{num:60,time:"00:05:11,079 --> 00:05:26,939",arabic:"أَعْظَمَ اللَّهُ أَجْرَكُمْ",segs:null,full_uz:"Alloh sizning ajringizni ulug‘ qilsin.",note:"أَعْظَمَ اللَّهُ أَجْرَكُمْ — ta’ziya paytida aytiladigan duo; «Alloh sizga katta ajr bersin» ma’nosida."},
{num:61,time:"00:05:26,939 --> 00:05:27,759",arabic:"وَأَجْرَكُمْ",segs:null,full_uz:"Sizga ham.",note:null},
{num:62,time:"00:05:27,759 --> 00:05:31,799",arabic:"أَحْسَنَ اللَّهُ عَزَاءَ أَمِيرِ الْمُؤْمِنِينَ",segs:["أَحْسَنَ اللَّهُ عَزَاءَ أَمِيرِ الْمُؤْمِنِينَ"],full_uz:"Alloh mo‘minlar amiriga tasalli va sabr bersin.",note:"أَحْسَنَ اللَّهُ عَزَاءَ — ta’ziya iborasi: «Alloh sabr va ajr bersin»."},
{num:63,time:"00:05:31,799 --> 00:05:34,439",arabic:"فِي وَفَاةِ الْإِمَامِ مَالِكِ بْنِ أَنَسٍ",segs:null,full_uz:"Imom Molik ibn Anasning vafoti munosabati bilan.",note:null},
{num:64,time:"00:05:34,439 --> 00:05:35,939",arabic:"إِمَامِ دَارِ الْهِجْرَةِ",segs:null,full_uz:"Hijrat diyorining imomi.",note:"إِمَامُ دَارِ الْهِجْرَةِ — Imom Molikning mashhur unvoni."},
{num:65,time:"00:05:35,939 --> 00:05:38,240",arabic:"إِنَّ الْمُصَابَ لَجَلَلٌ",segs:null,full_uz:"Bu judolik juda og‘ir musibatdir.",note:"الْمُصَابُ — «musibat, judolik»; لَجَلَلٌ — «juda katta, og‘ir»."},
{num:66,time:"00:05:38,240 --> 00:05:41,060",arabic:"وَإِنَّ الْفَاجِعَةَ بِأَبِي عَبْدِ اللَّهِ لَعَظِيمَةٌ",segs:["وَإِنَّ الْفَاجِعَةَ بِأَبِي عَبْدِ اللَّهِ","لَعَظِيمَةٌ"],full_uz:"Abu Abdullohning vafoti sababli kelgan musibat ham nihoyatda ulkandir.",note:"الْفَاجِعَةُ — «og‘ir musibat, dahshatli judolik»."},
{num:67,time:"00:05:41,060 --> 00:05:44,060",arabic:"غَفَرَ اللَّهُ لَنَا وَلَهُ",segs:null,full_uz:"Alloh bizni ham, uni ham mag‘firat qilsin.",note:null},
{num:68,time:"00:05:44,060 --> 00:05:46,220",arabic:"وَجَزَى الْإِمَامَ عَنَّا كُلَّ خَيْرٍ",segs:["وَجَزَى الْإِمَامَ عَنَّا","كُلَّ خَيْرٍ"],full_uz:"Alloh imomni biz nomimizdan barcha yaxshilik bilan mukofotlasin.",note:"جَزَاهُ اللَّهُ خَيْرًا — «Alloh uni yaxshilik bilan mukofotlasin»."},
{num:69,time:"00:05:46,220 --> 00:05:52,780",arabic:"إِنَّ لِلَّهِ مَا أَخَذَ وَلَهُ مَا أَبْقَى",segs:["إِنَّ لِلَّهِ مَا أَخَذَ","وَلَهُ مَا أَبْقَى"],full_uz:"Alloh olgan narsa ham Unikidir, qoldirgani ham Unikidir.",note:"Bu ta’ziya paytida aytiladigan mashhur hadis iborasining mazmunidir."},
{num:70,time:"00:05:52,780 --> 00:05:54,960",arabic:"وَلَا نَقُولُ إِلَّا مَا يُرْضِي رَبَّنَا",segs:["وَلَا نَقُولُ إِلَّا","مَا يُرْضِي رَبَّنَا"],full_uz:"Robbimizni rozi qiladigan so‘zdan boshqasini aytmaymiz.",note:"مَا يُرْضِي — «rozi qiladigan narsa»."},
{num:71,time:"00:05:54,960 --> 00:05:57,879",arabic:"إِنَّا لِلَّهِ وَإِنَّا إِلَيْهِ رَاجِعُونَ",segs:null,full_uz:"Albatta, biz Allohnikimiz va Unga qaytuvchilarmiz.",note:null},
{num:72,time:"00:05:57,879 --> 00:06:01,220",arabic:"إِنَّا لِلَّهِ وَإِنَّا إِلَيْهِ رَاجِعُونَ",segs:null,full_uz:"Albatta, biz Allohnikimiz va Unga qaytuvchilarmiz.",note:null},
{num:73,time:"00:06:08,240 --> 00:06:21,860",arabic:"إِنَّ لِلَّهِ مَا أَخَذَ وَلَهُ مَا أَبْقَى",segs:["إِنَّ لِلَّهِ مَا أَخَذَ","وَلَهُ مَا أَبْقَى"],full_uz:"Alloh olgan narsa ham Unikidir, qoldirgani ham Unikidir.",note:null},
{num:74,time:"00:06:21,860 --> 00:06:24,040",arabic:"وَلَا نَقُولُ إِلَّا مَا يُرْضِي رَبَّنَا",segs:["وَلَا نَقُولُ إِلَّا","مَا يُرْضِي رَبَّنَا"],full_uz:"Robbimizni rozi qiladigan so‘zdan boshqasini aytmaymiz.",note:null},
{num:75,time:"00:06:24,040 --> 00:06:26,920",arabic:"إِنَّا لِلَّهِ وَإِنَّا إِلَيْهِ رَاجِعُونَ",segs:null,full_uz:"Albatta, biz Allohnikimiz va Unga qaytuvchilarmiz.",note:null},
{num:76,time:"00:06:26,920 --> 00:06:34,040",arabic:"أَيَّ خَسَارَةٍ حَلَّتْ بِأُمَّةِ الْإِسْلَامِ بَعْدَ رَحِيلِ الْإِمَامِ مَالِكِ بْنِ أَنَسٍ؟",segs:["أَيَّ خَسَارَةٍ حَلَّتْ بِأُمَّةِ الْإِسْلَامِ","بَعْدَ رَحِيلِ الْإِمَامِ مَالِكِ بْنِ أَنَسٍ؟"],full_uz:"Imom Molik ibn Anas vafotidan keyin Islom ummatiga naqadar katta yo‘qotish keldi!",note:"حَلَّتْ بِـ — «boshiga tushmoq, yuz bermoq»; رَحِيلٌ — «ketish, vafot»."},
{num:77,time:"00:06:34,040 --> 00:06:39,000",arabic:"كَمْ كُنْتُ أَرْجُو أَنْ أَكُونَ يَوْمًا أَحَدَ طُلَّابِهِ",segs:["كَمْ كُنْتُ أَرْجُو","أَنْ أَكُونَ يَوْمًا أَحَدَ طُلَّابِهِ"],full_uz:"Qaniydi, bir kun uning shogirdlaridan biri bo‘lishni nasib etganida.",note:"كَمْ كُنْتُ أَرْجُو — «naqadar umid qilardim, qanchalik orzu qilardim»."},
{num:78,time:"00:06:39,000 --> 00:06:46,320",arabic:"رَحِمَكَ اللَّهُ وَأَسْكَنَكَ فَسِيحَ جِنَانِهِ",segs:["رَحِمَكَ اللَّهُ","وَأَسْكَنَكَ فَسِيحَ جِنَانِهِ"],full_uz:"Alloh seni rahmatiga olsin va keng jannatlariga joylashtirsin.",note:"فَسِيحُ الْجِنَانِ — «keng jannatlar»."},
{num:79,time:"00:06:52,800 --> 00:06:56,180",arabic:"حَمْدًا لِلَّهِ عَلَى سَلَامَتِكَ يَا وَلَدِي",segs:["حَمْدًا لِلَّهِ عَلَى سَلَامَتِكَ","يَا وَلَدِي"],full_uz:"Salomat qaytganing uchun Allohga hamd bo‘lsin, bolam.",note:"حَمْدًا لِلَّهِ عَلَى سَلَامَتِكَ — «salomatliging uchun Allohga hamd»; yaqin inson sog‘-omon qaytganda aytiladi."},
{num:80,time:"00:06:56,180 --> 00:06:59,480",arabic:"حَمْدًا لِلَّهِ عَلَى سَلَامَتِكَ",segs:null,full_uz:"Salomat qaytganing uchun Allohga hamd bo‘lsin.",note:null},
{num:81,time:"00:06:59,480 --> 00:07:02,820",arabic:"سَلَّمَكَ اللَّهُ يَا أُمَّاهُ سَلَّمَكَ اللَّهُ",segs:["سَلَّمَكَ اللَّهُ يَا أُمَّاهُ","سَلَّمَكَ اللَّهُ"],full_uz:"Alloh sizni salomat qilsin, onajon. Alloh sizni salomat qilsin.",note:"سَلَّمَكَ اللَّهُ — «Alloh seni salomat qilsin»."},
{num:82,time:"00:07:02,819 --> 00:07:12,560",arabic:"آهْ يَا وَلَدِي حَسِبْتُ أَنَّ الْمَوْتَ سَيُعَاجِلُنِي قَبْلَ أَنْ تَكْتَحِلَ عَيْنَايَ بِمَرْآكَ يَا وَلَدِي",segs:["آهْ يَا وَلَدِي","حَسِبْتُ أَنَّ الْمَوْتَ سَيُعَاجِلُنِي","قَبْلَ أَنْ تَكْتَحِلَ عَيْنَايَ بِمَرْآكَ","يَا وَلَدِي"],full_uz:"Oh, bolam! Seni ko‘rishdan oldin o‘lim meni olib ketadi, deb o‘ylagandim, bolam.",note:"تَكْتَحِلُ عَيْنَايَ بِمَرْآكَ — so‘zma-so‘z «ko‘zlarim seni ko‘rib surma tortadi»; ya’ni «seni ko‘rish nasib etadi»."},
{num:83,time:"00:07:12,560 --> 00:07:18,439",arabic:"أَطَالَ اللَّهُ فِي عُمْرِكِ يَا أُمَّاهُ وَحَفِظَكِ مِنْ كُلِّ شَرٍّ وَمَكْرُوهٍ",segs:["أَطَالَ اللَّهُ فِي عُمْرِكِ يَا أُمَّاهُ","وَحَفِظَكِ مِنْ كُلِّ شَرٍّ وَمَكْرُوهٍ"],full_uz:"Alloh umringizni uzoq qilsin, onajon, sizni har qanday yomonlik va noxushlikdan asrasin.",note:"أَطَالَ اللَّهُ فِي عُمْرِكِ — «Alloh umringni uzoq qilsin»."},
{num:84,time:"00:07:18,439 --> 00:07:23,819",arabic:"الْحَمْدُ لِلَّهِ وَكَيْفَ حَالُكَ أَنْتَ يَا وَلَدِي؟",segs:["الْحَمْدُ لِلَّهِ","وَكَيْفَ حَالُكَ أَنْتَ يَا وَلَدِي؟"],full_uz:"Alhamdulillah. O‘zing qalaysan, bolam?",note:null},
{num:85,time:"00:07:23,819 --> 00:07:28,579",arabic:"الْحَمْدُ لِلَّهِ أَنَا بِخَيْرٍ مَا دُمْتِ قَدْ وَجَدْتُكِ بِخَيْرٍ",segs:["الْحَمْدُ لِلَّهِ أَنَا بِخَيْرٍ","مَا دُمْتِ قَدْ وَجَدْتُكِ بِخَيْرٍ"],full_uz:"Alhamdulillah, sizni yaxshi holda topgan ekanman, men ham yaxshiman.",note:"مَا دُمْتِ — «modomiki, ... ekan»."},
{num:86,time:"00:07:28,579 --> 00:07:30,399",arabic:"الْحَمْدُ لِلَّهِ",segs:null,full_uz:"Alhamdulillah.",note:null},
{num:87,time:"00:07:30,399 --> 00:07:32,859",arabic:"وَكَيْفَ حَالُ الْإِمَامِ مَالِكٍ؟",segs:null,full_uz:"Imom Molikning ahvollari qalay?",note:null},
{num:88,time:"00:07:32,859 --> 00:07:40,620",arabic:"أَحْسَنَ اللَّهُ عَزَاءَكِ فِي الْإِمَامِ مَالِكٍ",segs:["أَحْسَنَ اللَّهُ عَزَاءَكِ","فِي الْإِمَامِ مَالِكٍ"],full_uz:"Imom Molikning vafoti munosabati bilan Alloh sizga sabr va ajr bersin.",note:"أَحْسَنَ اللَّهُ عَزَاءَكِ — «Alloh sizga sabr va tasalli bersin»."},
{num:89,time:"00:07:40,620 --> 00:07:45,979",arabic:"إِنَّا لِلَّهِ وَإِنَّا إِلَيْهِ رَاجِعُونَ",segs:null,full_uz:"Albatta, biz Allohnikimiz va Unga qaytuvchilarmiz.",note:null},
{num:90,time:"00:07:45,979 --> 00:07:49,839",arabic:"أَوَقَدْ مَاتَ إِمَامُ دَارِ الْهِجْرَةِ؟",segs:["أَوَقَدْ مَاتَ","إِمَامُ دَارِ الْهِجْرَةِ؟"],full_uz:"Hijrat diyorining imomi ham vafot etibdilarmi?",note:"أَوَقَدْ — «nahotki ...? rostdan ham ...?» hayrat ifodasi."},
{num:91,time:"00:07:49,839 --> 00:07:57,019",arabic:"أَجَلْ يَوْمٌ قَدْ سَبَقَنَا إِلَى رَبِّهِ",segs:["أَجَلْ","يَوْمٌ قَدْ سَبَقَنَا إِلَى رَبِّهِ"],full_uz:"Ha. U bugun Robbisining huzuriga bizdan oldin ketdi.",note:"سَبَقَنَا إِلَى رَبِّهِ — «Robbisi huzuriga bizdan oldin ketdi», ya’ni vafot etdi."},
{num:92,time:"00:07:58,579 --> 00:08:01,139",arabic:"اللَّهُمَّ ارْحَمْنَا",segs:null,full_uz:"Ey Alloh, bizga rahm qil.",note:null},
{num:93,time:"00:08:01,139 --> 00:08:03,019",arabic:"اللَّهُمَّ اغْفِرْ لَنَا",segs:null,full_uz:"Ey Alloh, bizni mag‘firat qil.",note:null},
{num:94,time:"00:08:03,019 --> 00:08:15,199",arabic:"رَحِمَ اللَّهُ الْإِمَامَ مَالِكًا",segs:null,full_uz:"Alloh Imom Molikka rahmat qilsin.",note:null},
{num:95,time:"00:08:15,199 --> 00:08:18,299",arabic:"وَأَلْحَقَنَا بِهِ عَلَى الْإِمَامِ",segs:null,full_uz:"Va bizni ham u zotga yetkazsin.",note:null},
{num:96,time:"00:08:18,299 --> 00:08:21,500",arabic:"اللَّهُمَّ آمِينَ يَا رَبَّ الْعَالَمِينَ",segs:["اللَّهُمَّ آمِينَ","يَا رَبَّ الْعَالَمِينَ"],full_uz:"Omin, ey olamlar Robbi.",note:null},
{num:97,time:"00:08:23,459 --> 00:08:25,759",arabic:"هَوِّنْ عَلَيْكَ يَا وَلَدِي",segs:["هَوِّنْ عَلَيْكَ","يَا وَلَدِي"],full_uz:"O‘zingni bos, bolam.",note:"هَوِّنْ عَلَيْكَ — «o‘zingni tut, o‘zingni bos» ma’nosidagi tasalli iborasi."},
{num:98,time:"00:08:25,759 --> 00:08:27,500",arabic:"هَوِّنْ عَلَيْكَ",segs:null,full_uz:"O‘zingni bos.",note:null},
{num:99,time:"00:08:27,500 --> 00:08:31,920",arabic:"الْحَمْدُ لِلَّهِ",segs:null,full_uz:"Alhamdulillah.",note:null},
{num:100,time:"00:08:31,920 --> 00:08:34,379",arabic:"إِنَّهُ قَضَاءُ اللَّهِ",segs:null,full_uz:"Bu Allohning taqdiridir.",note:"قَضَاءُ اللَّهِ — «Allohning taqdiri, hukmi»."},
{num:101,time:"00:08:34,379 --> 00:08:37,379",arabic:"وَلَا رَدَّ لِقَضَائِهِ",segs:null,full_uz:"Uning taqdirini qaytarib bo‘lmaydi.",note:"لَا رَدَّ لِـ — «qaytarib bo‘lmaydi»."},
{num:102,time:"00:08:51,379 --> 00:08:54,120",arabic:"لَقَدْ أَخَذْتُ بِطَلَبِ أَمِيرِ الْمُؤْمِنِينَ",segs:["لَقَدْ أَخَذْتُ بِطَلَبِ أَمِيرِ الْمُؤْمِنِينَ"],full_uz:"Mo‘minlar amirining topshirig‘ini bajardim.",note:"أَخَذَ بِـ — «biror ishni zimmasiga olmoq, unga amal qilmoq»."},
{num:103,time:"00:08:54,120 --> 00:08:58,539",arabic:"فَلَمْ أَجِدْ السَّاعَةَ مَنْ يَقُومُ بِهَذِهِ الْمَهَمَّةِ الْكَبِيرَةِ يَا مَوْلَايَ",segs:["فَلَمْ أَجِدْ السَّاعَةَ مَنْ يَقُومُ بِهَذِهِ الْمَهَمَّةِ الْكَبِيرَةِ","يَا مَوْلَايَ"],full_uz:"Lekin hozircha bu katta vazifani bajaradigan kishini topa olmadim, hazratim.",note:"السَّاعَةَ — bu yerda «hozircha, ayni paytda» ma’nosida."},
{num:104,time:"00:08:58,539 --> 00:09:03,899",arabic:"فَمَهَمَّةُ الْوَصَايَةِ عَلَى الْأَمِيرِ الْمَأْمُونِ كَمَا أَسْتَفْتِكِ يَا أَمِيرَ الْمُؤْمِنِينَ",segs:["فَمَهَمَّةُ الْوَصَايَةِ عَلَى الْأَمِيرِ الْمَأْمُونِ","كَمَا أَسْتَفْتِكِ يَا أَمِيرَ الْمُؤْمِنِينَ"],full_uz:"Mo‘minlar amiri, sizdan so‘rab bilganimdek, Amir Ma’munga vasiylik qilish vazifasi...",note:"الْوَصَايَةُ عَلَى — «biror kishiga vasiylik qilish»."},
{num:105,time:"00:09:03,899 --> 00:09:08,019",arabic:"مَهَمَّةٌ كَبِيرَةٌ وَيَجِبُ أَنْ نُحْسِنَ لَهَا الِاخْتِيَارَ",segs:["مَهَمَّةٌ كَبِيرَةٌ","وَيَجِبُ أَنْ نُحْسِنَ لَهَا الِاخْتِيَارَ"],full_uz:"katta vazifa, shuning uchun unga mos kishini juda yaxshi tanlashimiz kerak.",note:"أَحْسَنَ الِاخْتِيَارَ — «yaxshi tanlamoq, to‘g‘ri tanlov qilmoq»."},
{num:106,time:"00:09:08,019 --> 00:09:11,179",arabic:"وَأَنْتَ يَا أَبَا الْفَضْلِ",segs:null,full_uz:"Siz-chi, ey Abul-Fadl?",note:null},
{num:107,time:"00:09:11,179 --> 00:09:17,179",arabic:"هَلْ غَابَ عَنْ ذِهْنِي كَمَا غَابَ عَنْ ذِهْنِي حَاجِبِي أَمِيرِ الْمُؤْمِنِينَ الْفَضْلُ بْنُ الرَّبِيعِ؟",segs:["هَلْ غَابَ عَنْ ذِهْنِي","كَمَا غَابَ عَنْ ذِهْنِي حَاجِبِي أَمِيرِ الْمُؤْمِنِينَ الْفَضْلُ بْنُ الرَّبِيعِ؟"],full_uz:"Mo‘minlar amirining hojibi Fadl ibn Robi’ xayolimdan chiqib qolganidek, bu ham xayolimdan chiqib qolganmi?",note:"حَاجِبُ أَمِيرِ الْمُؤْمِنِينَ — «mo‘minlar amirining hojibi», saroydagi yuqori mansabdor."},
{num:108,time:"00:09:17,179 --> 00:09:24,259",arabic:"أَظُنُّنِي أَعْرِفُ رَجُلًا جَدِيرًا بِهَذِهِ الْمَهَمَّةِ الشَّرِيفَةِ يَا مَوْلَايَ",segs:["أَظُنُّنِي أَعْرِفُ رَجُلًا","جَدِيرًا بِهَذِهِ الْمَهَمَّةِ الشَّرِيفَةِ","يَا مَوْلَايَ"],full_uz:"Menimcha, bu sharafli vazifaga munosib bir kishini bilaman, hazratim.",note:"جَدِيرٌ بِـ — «munosib, loyiq»."},
{num:109,time:"00:09:24,259 --> 00:09:29,439",arabic:"لَا حَرَمَنِي اللَّهُ مِنْ حُضُورِ بَدَاهَتِكَ",segs:["لَا حَرَمَنِي اللَّهُ مِنْ حُضُورِ بَدَاهَتِكَ"],full_uz:"Alloh meni sening topqirligingdan mahrum qilmasin.",note:"بَدَاهَةٌ — «hozirjavoblik, topqirlik, tez fahmlash»."},
{num:110,time:"00:09:29,439 --> 00:09:31,899",arabic:"قُلْ لِي مَنْ هُوَ؟",segs:null,full_uz:"Aytaqol, u kim?",note:null},
{num:111,time:"00:09:31,899 --> 00:09:33,939",arabic:"كُنْتُ قَدْ حَدَّثْتُكَ عَنْهُ يَا مَوْلَايَ",segs:["كُنْتُ قَدْ حَدَّثْتُكَ عَنْهُ","يَا مَوْلَايَ"],full_uz:"Men u haqda sizga avval aytgan edim, hazratim.",note:"حَدَّثَهُ عَنْ — «biror kishi haqida gapirib bermoq»."},
{num:112,time:"00:09:33,939 --> 00:09:40,219",arabic:"فَتًى شَدِيدُ الذَّكَاءِ وَاسِعُ الثَّقَافَةِ شَدِيدُ النَّبَاهَةِ",segs:["فَتًى شَدِيدُ الذَّكَاءِ","وَاسِعُ الثَّقَافَةِ","شَدِيدُ النَّبَاهَةِ"],full_uz:"Juda aqlli, bilimi keng va nihoyatda ziyrak bir yigit.",note:"النَّبَاهَةُ — «ziyraklik, fahm-farosat»."},
{num:113,time:"00:09:40,219 --> 00:09:44,399",arabic:"وَأَظُنُّهُ أَنْسَبُ مَنْ نُكِلُ إِلَيْهِ تِلْكَ الْمَهَمَّةَ",segs:["وَأَظُنُّهُ أَنْسَبُ","مَنْ نُكِلُ إِلَيْهِ تِلْكَ الْمَهَمَّةَ"],full_uz:"Menimcha, o‘sha vazifani topshirish uchun eng munosib kishi shu.",note:"نُكِلَ إِلَيْهِ الْأَمْرُ — «ish unga topshirildi»."},
{num:115,time:"00:09:47,179 --> 00:09:49,859",arabic:"الْفَضْلُ بْنُ سَهْلٍ السَّرْخَسِيُّ",segs:null,full_uz:"Fadl ibn Sahl as-Saraxsiy.",note:null},
{num:116,time:"00:09:49,859 --> 00:09:53,659",arabic:"الْفَضْلُ بْنُ سَهْلٍ",segs:null,full_uz:"Fadl ibn Sahl.",note:null},
{num:117,time:"00:09:53,659 --> 00:09:56,899",arabic:"الْفَضْلُ بْنُ سَهْلٍ",segs:null,full_uz:"Fadl ibn Sahl.",note:null},
{num:118,time:"00:09:56,899 --> 00:10:05,699",arabic:"أَلَيْسَ هُوَ ذَلِكَ الشَّابَّ الَّذِي طَلَبْتَ إِلَيْهِ نَقْلَ كِتَابٍ مِنَ الْفَارِسِيَّةِ إِلَى الْعَرَبِيَّةِ وَأَعْجَبَكَ صَنِيعُهُ؟",segs:["أَلَيْسَ هُوَ ذَلِكَ الشَّابَّ","الَّذِي طَلَبْتَ إِلَيْهِ نَقْلَ كِتَابٍ مِنَ الْفَارِسِيَّةِ إِلَى الْعَرَبِيَّةِ","وَأَعْجَبَكَ صَنِيعُهُ؟"],full_uz:"U siz fors tilidan arab tiliga bir kitobni tarjima qilishni buyurgan va qilgan ishidan mamnun bo‘lgan o‘sha yigit emasmi?",note:"نَقْلُ كِتَابٍ مِنْ لُغَةٍ إِلَى أُخْرَى — «kitobni bir tildan boshqa tilga tarjima qilish»; صَنِيعٌ — «qilingan ish, xizmat»."},
{num:119,time:"00:10:05,699 --> 00:10:07,139",arabic:"هُوَ بِعَيْنِهِ يَا مَوْلَايَ",segs:["هُوَ بِعَيْنِهِ","يَا مَوْلَايَ"],full_uz:"Aynan o‘sha, hazratim.",note:"بِعَيْنِهِ — «aynan o‘zi, xuddi o‘sha» ma’nosida."},
{num:120,time:"00:10:07,139 --> 00:10:12,339",arabic:"تَرَاهُ مُنَاسِبًا يَا أَبَا الْفَضْلِ؟",segs:["تَرَاهُ مُنَاسِبًا","يَا أَبَا الْفَضْلِ؟"],full_uz:"Uni munosib deb bilasizmi, ey Abul-Fadl?",note:"رَآهُ مُنَاسِبًا — «uni mos/munosib deb bilmoq»."},
{num:121,time:"00:10:12,339 --> 00:10:14,159",arabic:"لَوْلَا ذَلِكَ مَا حَدَّثْتُكَ عَنْهُ",segs:["لَوْلَا ذَلِكَ","مَا حَدَّثْتُكَ عَنْهُ"],full_uz:"Shunday bo‘lmaganida, u haqda sizga aytmagan bo‘lardim.",note:"لَوْلَا ذَلِكَ — «agar shunday bo‘lmaganida»."},
{num:122,time:"00:10:14,159 --> 00:10:17,219",arabic:"وَالرَّأْيُ رَأْيُ أَمِيرِ الْمُؤْمِنِينَ",segs:null,full_uz:"Qaror esa mo‘minlar amirining qaroridir.",note:null},
{num:123,time:"00:10:17,219 --> 00:10:20,559",arabic:"فَإِنْ رَأَيْتَ أَتَيْتُكَ بِهِ",segs:["فَإِنْ رَأَيْتَ","أَتَيْتُكَ بِهِ"],full_uz:"Ma’qul ko‘rsangiz, uni huzuringizga olib kelaman.",note:"أَتَيْتُكَ بِهِ — «uni huzuringizga olib kelaman»."},
{num:124,time:"00:10:20,559 --> 00:10:24,579",arabic:"فَإِنْ شَرَّفَ بِإِعْجَابِكَ كَانَ لَنَا ذَلِكَ",segs:["فَإِنْ شَرَّفَ بِإِعْجَابِكَ","كَانَ لَنَا ذَلِكَ"],full_uz:"Agar u sizga ma’qul kelib, sizning e’tiboringizga sazovor bo‘lsa, bu biz uchun katta sharaf.",note:"شَرَّفَ بِـ — «sharaf keltirmoq, sharaflantirmoq»."},
{num:125,time:"00:10:24,579 --> 00:10:26,899",arabic:"وَإِلَّا بَحَثْنَا عَنْ غَيْرِهِ",segs:null,full_uz:"Aks holda, boshqasini izlaymiz.",note:null},
{num:126,time:"00:10:26,899 --> 00:10:30,600",arabic:"نِعْمَ الرَّأْيُ يَا يَحْيَى",segs:["نِعْمَ الرَّأْيُ","يَا يَحْيَى"],full_uz:"Qanday yaxshi fikr, ey Yahyo!",note:"نِعْمَ الرَّأْيُ — «qanday yaxshi fikr!»."},
{num:127,time:"00:10:30,600 --> 00:10:32,600",arabic:"نِعْمَ الرَّأْيُ",segs:null,full_uz:"Qanday yaxshi fikr!",note:null},
{num:128,time:"00:10:44,159 --> 00:10:53,039",arabic:"السَّلَامُ عَلَيْكُمْ",segs:null,full_uz:"Assalomu alaykum.",note:null},
{num:129,time:"00:10:53,039 --> 00:10:55,419",arabic:"وَعَلَيْكُمُ السَّلَامُ وَرَحْمَةُ اللَّهِ وَبَرَكَاتُهُ",segs:null,full_uz:"Va alaykum assalom va Allohning rahmati va barakotlari bo‘lsin.",note:null},
{num:130,time:"00:10:55,419 --> 00:10:56,980",arabic:"أُرِيدُكَ فِي حَاجَةٍ يَا أَحْمَدُ",segs:["أُرِيدُكَ فِي حَاجَةٍ","يَا أَحْمَدُ"],full_uz:"Sendan bir ish borasida yordam so‘ramoqchiman, ey Ahmad.",note:"أُرِيدُكَ فِي حَاجَةٍ — «sendan bir masalada yordam/iltimos qilmoqchiman»."},
{num:131,time:"00:10:56,980 --> 00:10:57,719",arabic:"مُرْنِي يَا عَامِرُ",segs:["مُرْنِي","يَا عَامِرُ"],full_uz:"Buyuring, ey Omir.",note:"مُرْنِي — «menga buyuring, topshiriq bering»."},
{num:132,time:"00:10:57,719 --> 00:11:01,259",arabic:"لَا أَمَرَّ اللَّهُ عَلَيْكَ ظَالِمًا عِنْدَمَا قَصَدْتُكَ فِي حَاجَةٍ",segs:["لَا أَمَرَّ اللَّهُ عَلَيْكَ ظَالِمًا","عِنْدَمَا قَصَدْتُكَ فِي حَاجَةٍ"],full_uz:"Sizdan bir iltimos bilan kelganimda, Alloh sizga biror zolimni duchor qilmasin.",note:null},
{num:133,time:"00:11:01,259 --> 00:11:03,519",arabic:"إِنْ كُنْتُ أَقْدِرُ عَلَيْهَا فَحُبًّا وَإِكْرَامًا",segs:["إِنْ كُنْتُ أَقْدِرُ عَلَيْهَا","فَحُبًّا وَإِكْرَامًا"],full_uz:"Agar qo‘limdan kelsa, bajonidil va hurmat yuzasidan qilaman.",note:"حُبًّا وَإِكْرَامًا — «mehr bilan va hurmat yuzasidan»."},
{num:134,time:"00:11:03,519 --> 00:11:05,219",arabic:"لَيْسَ لَهَا إِلَّا أَنْتَ إِنْ شَاءَ اللَّهُ",segs:["لَيْسَ لَهَا إِلَّا أَنْتَ","إِنْ شَاءَ اللَّهُ"],full_uz:"Inshaalloh, bu ishni sendan boshqa hech kim qilolmaydi.",note:"لَيْسَ لَهَا إِلَّا أَنْتَ — «bu ish uchun uning sendan boshqa kishisi yo‘q»."},
{num:135,time:"00:11:05,219 --> 00:11:07,559",arabic:"إِنَّهَا لَيْسَتْ صَعْبَةً كَثِيرًا",segs:null,full_uz:"Bu juda qiyin ish emas.",note:null},
{num:136,time:"00:11:07,559 --> 00:11:09,339",arabic:"أَوْ لِنَقُلْ لَيْسَتْ مُسْتَحِيلَةً",segs:null,full_uz:"Yoki boshqacha aytganda, imkonsiz emas.",note:"لِنَقُلْ — «aytaylik, boshqacha ifodalasak»."},
{num:137,time:"00:11:09,339 --> 00:11:12,500",arabic:"إِنَّمَا هِيَ... يَعْنِي مَاذَا أَقُولُ لَكَ؟",segs:["إِنَّمَا هِيَ","يَعْنِي مَاذَا أَقُولُ لَكَ؟"],full_uz:"Gap shundaki... ya’ni, senga nima deyishni ham bilmayapman.",note:"إِنَّمَا هِيَ — «gap shundaki, aslida masala shuki»."},
{num:138,time:"00:11:12,500 --> 00:11:16,299",arabic:"عَامِرُ، إِنْ كَانَتْ سَهْلَةً فَاذْكُرْهَا لِغَيْرِي، أَوِ اذْكُرْهَا لِي فِي الْحَالِ",segs:["عَامِرُ، إِنْ كَانَتْ سَهْلَةً","فَاذْكُرْهَا لِغَيْرِي","أَوِ اذْكُرْهَا لِي فِي الْحَالِ"],full_uz:"Omir, agar oson ish bo‘lsa, uni boshqasiga ayt yoki hoziroq menga ayt.",note:"فِي الْحَالِ — «darhol, shu zahoti»."},
{num:139,time:"00:11:16,299 --> 00:11:19,299",arabic:"تَفَضَّلْ، تَفَضَّلْ، تَفَضَّلْ، تَفَضَّلْ",segs:null,full_uz:"Marhamat, aytaver.",note:null},
{num:140,time:"00:11:19,299 --> 00:11:22,899",arabic:"تَفَضَّلْ، تَفَضَّلْ",segs:null,full_uz:"Marhamat, aytaver.",note:null},
{num:141,time:"00:11:25,100 --> 00:11:28,100",arabic:"رُبَّمَا كَانَتْ أُمِّي تُرَاقِبُنِي مِنْ أَحَدِ الْأَزِقَّةِ",segs:["رُبَّمَا كَانَتْ أُمِّي تُرَاقِبُنِي","مِنْ أَحَدِ الْأَزِقَّةِ"],full_uz:"Ehtimol, onam meni ko‘chalardan biridan kuzatayotgandir.",note:"الْأَزِقَّةُ — «tor ko‘chalar, guzarlar»; رُبَّمَا — «ehtimol, balki»."},
{num:142,time:"00:11:28,700 --> 00:11:32,500",arabic:"إِنَّمَا قَصَدْتُكَ فِي أَمْرٍ تُبَلِّغُهُ إِلَى خَالَتِي أُمِّ أَحْمَدَ",segs:["إِنَّمَا قَصَدْتُكَ فِي أَمْرٍ","تُبَلِّغُهُ إِلَى خَالَتِي أُمِّ أَحْمَدَ"],full_uz:"Men sizning oldingizga xolam Ummu Ahmadga yetkazishingiz kerak bo‘lgan bir masala bilan keldim.",note:"بَلَّغَهُ إِلَى — «biror kishiga yetkazmoq»."},
{num:143,time:"00:11:32,500 --> 00:11:33,500",arabic:"خَيْرًا؟",segs:null,full_uz:"Yaxshilikmi?",note:null},
{num:144,time:"00:11:33,500 --> 00:11:37,100",arabic:"عَرُوسٌ، أُرِيدُهَا أَنْ تَجِدَ لِي عَرُوسًا",segs:["عَرُوسٌ","أُرِيدُهَا أَنْ تَجِدَ لِي عَرُوسًا"],full_uz:"Kelin. Men undan menga kelin topib berishini istayman.",note:"عَرُوسٌ — «kelin; turmush qurayotgan qiz»."},
{num:145,time:"00:11:37,100 --> 00:11:42,299",arabic:"عَامِرُ، مِنَ الْعَادَةِ أَنْ تَبْحَثَ لَكَ أُمُّكَ عَنْ عَرُوسِكَ",segs:["عَامِرُ، مِنَ الْعَادَةِ","أَنْ تَبْحَثَ لَكَ أُمُّكَ عَنْ عَرُوسِكَ"],full_uz:"Omir, odatda kelinni sen uchun onang izlaydi.",note:"مِنَ الْعَادَةِ أَنْ — «odatda shunday bo‘ladiki»."},
{num:146,time:"00:11:42,299 --> 00:11:43,299",arabic:"لِأَنَّ أُمِّي بَحَثَتْ لَكَ",segs:null,full_uz:"Axir onam sen uchun izlagan edi.",note:null},
{num:147,time:"00:11:43,299 --> 00:11:45,919",arabic:"أُمِّي يَا أَحْمَدُ بَحَثَتْ وَلَمْ تَجِدْ",segs:["أُمِّي يَا أَحْمَدُ","بَحَثَتْ وَلَمْ تَجِدْ"],full_uz:"Onam, ey Ahmad, izlab ko‘rdi, lekin topmadi.",note:null},
{num:148,time:"00:11:45,919 --> 00:11:50,319",arabic:"لَعَلَّ حَظِّيَ الْعَاثِرَ حَالَ بَيْنَهَا وَبَيْنَ وِجْدَانِ فَتَاةٍ مُنَاسِبَةٍ",segs:["لَعَلَّ حَظِّيَ الْعَاثِرَ حَالَ بَيْنَهَا وَبَيْنَ","وِجْدَانِ فَتَاةٍ مُنَاسِبَةٍ"],full_uz:"Balki omadsizligim uning munosib qiz topishiga to‘sqinlik qilgandir.",note:"حَالَ بَيْنَهُ وَبَيْنَ — «uning bilan ... o‘rtasiga to‘siq bo‘lmoq»; حَظٌّ عَاثِرٌ — «omadsiz taqdir, omadsizlik»."},
{num:149,time:"00:11:50,319 --> 00:11:54,099",arabic:"وَأُرِيدُ مِنْ خَالَةِ أُمِّ أَحْمَدَ أَنْ تَجِدَ لِي تِلْكَ الْفَتَاةَ",segs:["وَأُرِيدُ مِنْ خَالَةِ أُمِّ أَحْمَدَ","أَنْ تَجِدَ لِي تِلْكَ الْفَتَاةَ"],full_uz:"Men esa xola Ummu Ahmadning menga o‘sha qizni topib berishini istayman.",note:null},
{num:150,time:"00:11:54,099 --> 00:11:57,319",arabic:"فَأَنْتُمْ يَا أَحْمَدُ بَيْتُ عِلْمٍ وَتَقْوَى",segs:["فَأَنْتُمْ يَا أَحْمَدُ","بَيْتُ عِلْمٍ وَتَقْوَى"],full_uz:"Axir sizlar, ey Ahmad, ilm va taqvo xonadonisizlar.",note:"بَيْتُ عِلْمٍ وَتَقْوَى — «ilm va taqvo ahli bo‘lgan xonadon»."},
{num:151,time:"00:11:57,319 --> 00:12:00,199",arabic:"لَعَلَّ اللَّهَ يَفْتَحُ الْخَيْرَ عَلَى أَيْدِيكُمْ",segs:["لَعَلَّ اللَّهَ يَفْتَحُ الْخَيْرَ","عَلَى أَيْدِيكُمْ"],full_uz:"Balki Alloh yaxshilikni sizlarning qo‘llaringiz bilan nasib qilar.",note:"يَفْتَحُ الْخَيْرَ عَلَى يَدَيْهِ — «yaxshilikni uning vositasi bilan nasib qilmoq»."},
{num:152,time:"00:12:00,199 --> 00:12:02,319",arabic:"لَا أَدْرِي مَا أَقُولُ لَكَ يَا عَامِرُ",segs:["لَا أَدْرِي مَا أَقُولُ لَكَ","يَا عَامِرُ"],full_uz:"Senga nima deyishni bilmayman, ey Omir.",note:null},
{num:153,time:"00:12:02,319 --> 00:12:04,019",arabic:"وَلَكِنْ سَنَرَى مَا يَكُونُ",segs:["وَلَكِنْ","سَنَرَى مَا يَكُونُ"],full_uz:"Lekin nima bo‘lishini ko‘ramiz.",note:null},
{num:154,time:"00:12:04,019 --> 00:12:07,299",arabic:"تَقْصِدُ أَنَّكَ سَتُخْبِرُ خَالَةَ أُمِّ أَحْمَدَ؟",segs:["تَقْصِدُ أَنَّكَ سَتُخْبِرُ","خَالَةَ أُمِّ أَحْمَدَ؟"],full_uz:"Xola Ummu Ahmadga aytmoqchisan, demoqchisanmi?",note:"تَقْصِدُ أَنَّ — «... demoqchisan, nazarda tutyapsan»."},
{num:155,time:"00:12:07,299 --> 00:12:08,539",arabic:"لَا أَدْرِي كَيْفَ سَأُخْبِرُهَا",segs:null,full_uz:"Uni qanday xabardor qilishni bilmayman.",note:null},
{num:156,time:"00:12:08,539 --> 00:12:10,699",arabic:"أَظُنُّهَا سَتَحْسَبُنِي أُمَازِحُ",segs:["أَظُنُّهَا سَتَحْسَبُنِي","أُمَازِحُ"],full_uz:"Menimcha, u meni hazillashyapti deb o‘ylaydi.",note:"حَسِبَهُ — «deb o‘ylamoq, deb hisoblamoq»."},
{num:157,time:"00:12:10,700 --> 00:12:14,340",arabic:"وَلَكِنْ سَأُخْبِرُهَا فِي كُلِّ الْأَحْوَالِ وَأَمْرِي إِلَى اللَّهِ",segs:["وَلَكِنْ سَأُخْبِرُهَا فِي كُلِّ الْأَحْوَالِ","وَأَمْرِي إِلَى اللَّهِ"],full_uz:"Lekin har holda unga aytaman. Ishimni Allohga topshirdim.",note:"فِي كُلِّ الْأَحْوَالِ — «har qanday holatda ham»; أَمْرِي إِلَى اللَّهِ — «ishimni Allohga topshirdim»."},
{num:158,time:"00:12:14,340 --> 00:12:16,500",arabic:"السَّلَامُ عَلَيْكُمْ",segs:null,full_uz:"Assalomu alaykum.",note:null},
{num:159,time:"00:12:16,500 --> 00:12:19,920",arabic:"وَعَلَيْكُمُ السَّلَامُ وَرَحْمَةُ اللَّهِ وَبَرَكَاتُهُ",segs:null,full_uz:"Va alaykum assalom va Allohning rahmati va barakotlari bo‘lsin.",note:null},
{num:160,time:"00:12:19,920 --> 00:12:23,120",arabic:"بَرَكَةٌ فِيكَ يَا أَحْمَدُ بَرَكَةٌ فِيكَ",segs:["بَرَكَةٌ فِيكَ يَا أَحْمَدُ","بَرَكَةٌ فِيكَ"],full_uz:"Alloh seni barakali qilsin, ey Ahmad, barakali qilsin.",note:"بَرَكَةٌ فِيكَ — duo va minnatdorlik ifodasi."},
{num:161,time:"00:12:23,120 --> 00:12:25,820",arabic:"أَسْأَلُ اللَّهَ أَنْ يَجْعَلَ الْخَيْرَ عَلَى أَيْدِيكُمْ",segs:["أَسْأَلُ اللَّهَ","أَنْ يَجْعَلَ الْخَيْرَ عَلَى أَيْدِيكُمْ"],full_uz:"Allohdan yaxshilikni sizlarning qo‘llaringiz bilan nasib etishini so‘rayman.",note:null},
{num:162,time:"00:12:25,820 --> 00:12:29,680",arabic:"قُلْتُ لَكُمْ لَيْسَ لِي إِلَّا خَالَتِي أُمُّ أَحْمَدَ",segs:["قُلْتُ لَكُمْ","لَيْسَ لِي إِلَّا خَالَتِي أُمُّ أَحْمَدَ"],full_uz:"Sizlarga aytdim-ku, menda xolam Ummu Ahmaddan boshqa ilojim yo‘q.",note:"لَيْسَ لِي إِلَّا — «menda ...dan boshqa chora/kimsa yo‘q»."},
{num:163,time:"00:12:29,680 --> 00:12:32,280",arabic:"لَيْسَ لِي إِلَّا خَالَتِي أُمُّ أَحْمَدَ",segs:null,full_uz:"Menda xolam Ummu Ahmaddan boshqa ilojim yo‘q.",note:null},
{num:164,time:"00:12:32,280 --> 00:12:34,120",arabic:"بَرَكَةٌ فِيكَ يَا أَحْمَدُ",segs:null,full_uz:"Alloh seni barakali qilsin, ey Ahmad.",note:null},
{num:165,time:"00:12:34,120 --> 00:12:37,080",arabic:"مَا الدَّاعِي إِلَى هَذَا كُلِّهِ يَا مَوْلَايَ",segs:["مَا الدَّاعِي إِلَى هَذَا كُلِّهِ","يَا مَوْلَايَ"],full_uz:"Bularning barchasiga nima sabab bo‘ldi, hazratim?",note:"مَا الدَّاعِي إِلَى — «...ga nima sabab bo‘ldi?»."},
{num:166,time:"00:12:37,080 --> 00:12:39,540",arabic:"إِنَّكَ تُخَاطِرُ بِنَفْسِكَ",segs:null,full_uz:"Siz o‘z hayotingizni xavf ostiga qo‘yyapsiz.",note:"خَاطَرَ بِنَفْسِهِ — «o‘z jonini xavfga qo‘ymoq»."},
{num:167,time:"00:12:39,540 --> 00:12:41,899",arabic:"أَمْنِي فِي أَمَانِ الرَّعِيَّةِ يَا زُبَيْدَةُ",segs:["أَمْنِي فِي أَمَانِ الرَّعِيَّةِ","يَا زُبَيْدَةُ"],full_uz:"Mening xavfsizligim raiyatning xavfsizligidadir, ey Zubayda.",note:"أَمَانٌ — «xavfsizlik, osoyishtalik»; الرَّعِيَّةُ — «raiyat, davlat fuqarolari»."},
{num:168,time:"00:12:41,899 --> 00:12:45,459",arabic:"لَكَ فِي الْعَسَسِ كِفَايَةٌ وَغِنًى يَا هَارُونُ",segs:["لَكَ فِي الْعَسَسِ كِفَايَةٌ وَغِنًى","يَا هَارُونُ"],full_uz:"Sizning qo‘riqchilaringiz yetarli-ku, ey Horun.",note:"الْعَسَسُ — «tungi qo‘riqlovchilar, patrul»; كِفَايَةٌ وَغِنًى — «yetarli va behojat darajada»."},
{num:169,time:"00:12:45,459 --> 00:12:48,459",arabic:"يَا زُبَيْدَةُ",segs:null,full_uz:"Ey Zubayda.",note:null},
{num:170,time:"00:12:48,459 --> 00:12:52,539",arabic:"إِذَا كَانَ الْعَسَسُ يُرَاقِبُونَ سَيْرَ أُمُورِ الدَّوْلَةِ",segs:["إِذَا كَانَ الْعَسَسُ يُرَاقِبُونَ","سَيْرَ أُمُورِ الدَّوْلَةِ"],full_uz:"Agar qo‘riqchilar davlat ishlarining borishini kuzatib tursalar,",note:"سَيْرُ أُمُورِ الدَّوْلَةِ — «davlat ishlarining borishi, kechishi»."},
{num:171,time:"00:12:53,360 --> 00:12:56,000",arabic:"فَمَنْ يُرَاقِبُ الْعَسَسَ؟",segs:null,full_uz:"Unda qo‘riqchilarni kim kuzatadi?",note:null},
{num:172,time:"00:12:56,000 --> 00:12:58,539",arabic:"أَلَيْسَ الْعَسَسُ بَشَرًا؟",segs:null,full_uz:"Qo‘riqchilar ham inson emasmi?",note:null},
{num:173,time:"00:12:59,639 --> 00:13:00,539",arabic:"أَلَا يُخْطِئُونَ؟",segs:null,full_uz:"Ular xato qilmaydilarmi?",note:null},
{num:174,time:"00:13:01,539 --> 00:13:02,539",arabic:"أَلَا يُصِيبُونَ؟",segs:null,full_uz:"To‘g‘ri ish qilmaydilarmi?",note:"أَصَابَ — bu yerda «to‘g‘ri qilmoq» ma’nosida."},
{num:175,time:"00:13:03,899 --> 00:13:05,480",arabic:"الْعَسَسُ مِنَ الرَّعِيَّةِ",segs:null,full_uz:"Qo‘riqchilar ham raiyatdan.",note:null},
{num:176,time:"00:13:05,480 --> 00:13:08,159",arabic:"هُنَاكَ الطَّيِّبُ وَهُنَاكَ الْخَبِيثُ",segs:["هُنَاكَ الطَّيِّبُ","وَهُنَاكَ الْخَبِيثُ"],full_uz:"Oralarida yaxshisi ham, yomoni ham bor.",note:"الطَّيِّبُ — «yaxshi, solih»; الْخَبِيثُ — «yomon, buzuq»."},
{num:177,time:"00:13:09,539 --> 00:13:12,860",arabic:"وَاللَّهِ مَا قُلْتُ ذَلِكَ إِلَّا خَشْيَةً عَلَى حَيَاتِكَ",segs:["وَاللَّهِ مَا قُلْتُ ذَلِكَ إِلَّا","خَشْيَةً عَلَى حَيَاتِكَ"],full_uz:"Allohga qasam, men buni faqat hayotingiz uchun qo‘rqib aytdim.",note:"خَشْيَةً عَلَى — «... uchun qo‘rqib»."},
{num:178,time:"00:13:12,860 --> 00:13:14,659",arabic:"فَأَنْتَ أَمِيرُ الْمُؤْمِنِينَ",segs:null,full_uz:"Axir siz mo‘minlar amirisiz.",note:null},
{num:179,time:"00:13:14,659 --> 00:13:16,519",arabic:"وَإِنْ حَدَثَ لَكَ مَكْرُوهٌ",segs:null,full_uz:"Agar sizga biror ko‘ngilsizlik yuz bersa,",note:"حَدَثَ لَهُ مَكْرُوهٌ — «unga biror ko‘ngilsiz hodisa yuz bermoq»."},
{num:180,time:"00:13:16,519 --> 00:13:18,039",arabic:"لَا قَدَّرَ اللَّهُ",segs:null,full_uz:"Alloh saqlasin.",note:"لَا قَدَّرَ اللَّهُ — «Alloh saqlasin, Xudo ko‘rsatmasin»."},
{num:181,time:"00:13:18,039 --> 00:13:22,019",arabic:"لَكَانَ وَبَالُهُ عَلَى الرَّعِيَّةِ مِنْ زَلَّةِ أَحَدِ عُمَّالِكَ",segs:["لَكَانَ وَبَالُهُ عَلَى الرَّعِيَّةِ","مِنْ زَلَّةِ أَحَدِ عُمَّالِكَ"],full_uz:"Buning kulfati raiyat boshiga sizning amaldorlaringizdan birining xatosi tufayli tushadi.",note:"وَبَالٌ — «og‘ir oqibat, kulfat»; زَلَّةٌ — «xato, sirpanish»."},
{num:182,time:"00:13:22,019 --> 00:13:24,500",arabic:"الطَّامَّةُ الْكُبْرَى عِنْدِي يَا زُبَيْدَةُ",segs:["الطَّامَّةُ الْكُبْرَى عِنْدِي","يَا زُبَيْدَةُ"],full_uz:"Men uchun eng katta musibat shuki, ey Zubayda,",note:"الطَّامَّةُ الْكُبْرَى — «eng katta kulfat, ulkan falokat»."},
{num:183,time:"00:13:24,500 --> 00:13:28,599",arabic:"أَنْ يَظْلِمَ أَحَدُ عُمَّالِي رَجُلًا",segs:["أَنْ يَظْلِمَ أَحَدُ عُمَّالِي","رَجُلًا"],full_uz:"amaldorlarimdan biri bir kishiga zulm qilishi.",note:null},
{num:184,time:"00:13:28,599 --> 00:13:33,980",arabic:"يُحَاجِجُنِيَ اللَّهُ بِهِ يَوْمَ الْقِيَامَةِ بِظُلْمٍ أَصَابَهُ",segs:["يُحَاجِجُنِيَ اللَّهُ بِهِ يَوْمَ الْقِيَامَةِ","بِظُلْمٍ أَصَابَهُ"],full_uz:"Qiyomat kuni Alloh meni shu odamga yetgan zulm sababli hisob-kitobga tortishi.",note:"حَاجَجَهُ اللهُ — «Alloh uni hujjat qilib, hisob talab qilishi» mazmunida."},
{num:185,time:"00:13:33,980 --> 00:13:36,399",arabic:"فِي دَوْلَةٍ أَنَا مَنْ يَقُومُ عَلَيْهَا",segs:null,full_uz:"Men boshqarayotgan davlatda.",note:"قَامَ عَلَى الدَّوْلَةِ — «davlatni boshqarmoq»."},
{num:186,time:"00:13:36,399 --> 00:13:39,000",arabic:"فَكُلُّكُمْ رَاعٍ",segs:null,full_uz:"Zero, barchangiz rahbarsiz.",note:"رَاعٍ — «mas’ul, boshqaruvchi, homiy» ma’nosida."},
{num:187,time:"00:13:39,000 --> 00:13:42,379",arabic:"وَكُلُّكُمْ مَسْؤُولٌ عَنْ رَعِيَّتِهِ",segs:["وَكُلُّكُمْ مَسْؤُولٌ","عَنْ رَعِيَّتِهِ"],full_uz:"Va barchangiz o‘z qo‘l ostingizdagilar uchun mas’ulsiz.",note:"مَسْؤُولٌ عَنْ رَعِيَّتِهِ — «o‘z qaramog‘idagilar uchun mas’ul»."},
{num:188,time:"00:13:42,379 --> 00:13:45,000",arabic:"صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ",segs:null,full_uz:"Alloh u zotga salavot va salomlar yo‘llasin.",note:null},
{num:189,time:"00:13:45,000 --> 00:13:47,220",arabic:"صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ",segs:null,full_uz:"Alloh u zotga salavot va salomlar yo‘llasin.",note:null},
{num:190,time:"00:13:47,220 --> 00:14:00,539",arabic:"حَمَاكَ اللَّهُ يَا مَوْلَايَ",segs:["حَمَاكَ اللَّهُ","يَا مَوْلَايَ"],full_uz:"Alloh sizni asrasin, hazratim.",note:"حَمَاهُ اللَّهُ — «Alloh uni asrasin, himoya qilsin»."},
{num:197,time:"00:15:53,059 --> 00:15:55,120",arabic:"مَرْوَانُ خَيْرًا يَا وَلَدِي",segs:["مَرْوَانُ","خَيْرًا يَا وَلَدِي"],full_uz:"Marvon, yaxshilikmi, bolam?",note:null},
{num:198,time:"00:15:55,120 --> 00:15:58,259",arabic:"مَا خَطْبُكَ؟ أَرَاكَ عُدْتَ فِي غَيْرِ وَقْتِكَ",segs:["مَا خَطْبُكَ؟","أَرَاكَ عُدْتَ فِي غَيْرِ وَقْتِكَ"],full_uz:"Senga nima bo‘ldi? Seni odatdagidan boshqa vaqtda qaytganingni ko‘ryapman.",note:"مَا خَطْبُكَ؟ — «Nima bo‘ldi senga?, nima gaping bor?»."},
{num:199,time:"00:15:58,259 --> 00:16:03,740",arabic:"الْحَقَّ أَنَّنِي جِئْتُ كَيْ أُحَدِّثَكِ فِي أَمْرٍ مُهِمٍّ",segs:["الْحَقَّ أَنَّنِي جِئْتُ","كَيْ أُحَدِّثَكِ فِي أَمْرٍ مُهِمٍّ"],full_uz:"To‘g‘risi, siz bilan muhim bir masala haqida gaplashgani keldim.",note:"الْحَقَّ أَنَّ — «to‘g‘risi, haqiqat shuki»."},
{num:200,time:"00:16:03,740 --> 00:16:07,720",arabic:"أَمْرٌ مُهِمٌّ؟ خَيْرًا يَا وَلَدِي",segs:["أَمْرٌ مُهِمٌّ؟","خَيْرًا يَا وَلَدِي"],full_uz:"Muhim masalami? Yaxshilikmi, bolam?",note:null},
{num:201,time:"00:16:07,720 --> 00:16:12,580",arabic:"إِنَّهُ شَهْنَازُ",segs:null,full_uz:"Gap Shahnoz haqida.",note:null},
{num:202,time:"00:16:12,580 --> 00:16:16,139",arabic:"شَهْنَازُ؟",segs:null,full_uz:"Shahnozmi?",note:null},
{num:203,time:"00:16:16,139 --> 00:16:19,720",arabic:"نَعَمْ أُرِيدُ أَنْ أَتَّخِذَهَا زَوْجَةً لِي",segs:["نَعَمْ","أُرِيدُ أَنْ أَتَّخِذَهَا زَوْجَةً لِي"],full_uz:"Ha, men uni o‘zimga xotin qilmoqchiman.",note:"اِتَّخَذَهَا زَوْجَةً — «uni o‘ziga xotin qilib olmoq»."},
{num:204,time:"00:16:19,720 --> 00:16:26,940",arabic:"هَذَا هُوَ الْأَمْرُ الَّذِي يَشْغَلُ بَالَكَ وَيَعْقِدُ لِسَانَكَ يَا بُنَيَّ؟",segs:["هَذَا هُوَ الْأَمْرُ الَّذِي يَشْغَلُ بَالَكَ","وَيَعْقِدُ لِسَانَكَ يَا بُنَيَّ؟"],full_uz:"Demak, seni o‘ylantirib, tilingni bog‘lab qo‘ygan masala shu ekan-da, bolam?",note:"يَشْغَلُ بَالَهُ — «xayolini band qilmoq»; يَعْقِدُ لِسَانَهُ — «gapira olmay qolishiga sabab bo‘lmoq»."},
{num:205,time:"00:16:26,940 --> 00:16:30,060",arabic:"الْحَقَّ أَنِّي أَخْشَى أَنْ لَا تُوَافِقِيَ عَلَيْهَا",segs:["الْحَقَّ أَنِّي أَخْشَى","أَنْ لَا تُوَافِقِيَ عَلَيْهَا"],full_uz:"To‘g‘risi, siz bunga rozi bo‘lmasligingizdan qo‘rqyapman.",note:"وَافَقَ عَلَى — «biror narsaga rozi bo‘lmoq»."},
{num:206,time:"00:16:30,060 --> 00:16:32,779",arabic:"خَشْيَتُكَ فِي مَكَانِهَا إِذَنْ",segs:["خَشْيَتُكَ فِي مَكَانِهَا","إِذَنْ"],full_uz:"Unda xavotiringiz o‘rinli ekan.",note:"فِي مَكَانِهَا — «o‘rinli, asoslidir»."},
{num:207,time:"00:16:32,779 --> 00:16:36,620",arabic:"وَلِمَاذَا يَا أُمِّي؟ شَهْنَازُ فَتَاةٌ طَيِّبَةٌ وَجَمِيلَةٌ",segs:["وَلِمَاذَا يَا أُمِّي؟","شَهْنَازُ فَتَاةٌ طَيِّبَةٌ وَجَمِيلَةٌ"],full_uz:"Nega, onajon? Shahnoz yaxshi va go‘zal qiz-ku.",note:null},
{num:208,time:"00:16:36,620 --> 00:16:40,980",arabic:"وَأَنَا أَرَى أَنَّهَا مُنَاسِبَةٌ كَيْ تُصْبِحَ زَوْجَةً لِي",segs:["وَأَنَا أَرَى أَنَّهَا مُنَاسِبَةٌ","كَيْ تُصْبِحَ زَوْجَةً لِي"],full_uz:"Menimcha, u menga munosib xotin bo‘la oladi.",note:"مُنَاسِبَةٌ — «mos, munosib»."},
{num:209,time:"00:16:40,980 --> 00:16:43,759",arabic:"مَا دُمْتَ تَعْرِفُ ذَلِكَ كُلَّهُ",segs:null,full_uz:"Bularning barchasini bilgan ekansan,",note:null},
{num:210,time:"00:16:43,759 --> 00:16:45,620",arabic:"فَلِمَ الْخَشْيَةُ إِذَنْ؟",segs:null,full_uz:"Unda nimadan qo‘rqyapsan?",note:"لِمَ — «nima uchun, nega»."},
{num:211,time:"00:16:46,620 --> 00:16:48,580",arabic:"تَقْصِدِينَ أَنَّ...",segs:null,full_uz:"Demak, siz shuni nazarda tutyapsizki...",note:null},
{num:212,time:"00:16:48,580 --> 00:16:50,340",arabic:"أَجَلْ أَجَلْ يَا مَرْوَانُ",segs:["أَجَلْ أَجَلْ","يَا مَرْوَانُ"],full_uz:"Ha, ha, Marvon.",note:null},
{num:213,time:"00:16:50,340 --> 00:16:53,060",arabic:"وَأَنَا كُنْتُ أُفَكِّرُ فِي أَمْرِ زَوَاجِكَ مِنْهَا",segs:["وَأَنَا كُنْتُ أُفَكِّرُ فِي أَمْرِ زَوَاجِكَ مِنْهَا"],full_uz:"Men ham sening unga uylanish masalang haqida o‘ylab yurgandim.",note:"أَمْرُ زَوَاجِهِ مِنْهَا — «uning unga uylanish masalasi»."},
{num:214,time:"00:16:53,060 --> 00:16:55,019",arabic:"مُنْذُ وَقَعَتْ عَلَيْهَا عَيْنِي",segs:null,full_uz:"Uni birinchi ko‘rganimdan beri.",note:"وَقَعَتْ عَيْنُهُ عَلَيْهَا — «ko‘zi unga tushdi, uni ko‘rdi»."},
{num:215,time:"00:16:55,019 --> 00:16:57,240",arabic:"فَنِعْمَ الْفَتَاةُ هِيَ يَا مَرْوَانُ",segs:["فَنِعْمَ الْفَتَاةُ هِيَ","يَا مَرْوَانُ"],full_uz:"U juda yaxshi qiz, ey Marvon.",note:"نِعْمَ الْفَتَاةُ — «naqadar yaxshi qiz!»."},
{num:216,time:"00:16:57,240 --> 00:17:00,039",arabic:"شُكْرًا يَا أُمَّاهُ",segs:["شُكْرًا","يَا أُمَّاهُ"],full_uz:"Rahmat, onajon.",note:null},
{num:217,time:"00:17:00,039 --> 00:17:09,319",arabic:"إِلَى مَتَى سَتَظَلُّ كَالشَّجَا فِي حَلْقِي يَا ابْنَ حَنْبَلٍ",segs:["إِلَى مَتَى سَتَظَلُّ كَالشَّجَا فِي حَلْقِي","يَا ابْنَ حَنْبَلٍ"],full_uz:"Qachongacha tomog‘imga tiqilgan tikan kabi bo‘lib qolasan, ey Ibn Hanbal?",note:"الشَّجَا فِي الْحَلْقِ — «tomoqqa tiqilgan narsa»; ko‘chma ma’noda «doimiy bezovtalik, g‘ashlik»."},
{num:218,time:"00:17:09,319 --> 00:17:13,700",arabic:"أَكَانَ مُقَدَّرًا لِي أَنْ أَجِدَكَ أَمَامِي فِي كُلِّ خُطْوَةٍ",segs:["أَكَانَ مُقَدَّرًا لِي","أَنْ أَجِدَكَ أَمَامِي فِي كُلِّ خُطْوَةٍ"],full_uz:"Har bir qadamimda seni qarshimda uchratishim taqdir qilingan ekanmi?",note:"مُقَدَّرًا لِي — «men uchun taqdir qilingan»."},
{num:219,time:"00:17:13,700 --> 00:17:16,259",arabic:"حَتَّى تُنَغِّصَ عَلَيَّ حَيَاتِي",segs:null,full_uz:"Hatto hayotimni zaharlab yuborishinggacha.",note:"نَغَّصَ عَلَيْهِ حَيَاتَهُ — «uning hayotini zaharlamoq, xotirjamligini buzmoq»."},
{num:220,time:"00:17:16,259 --> 00:17:20,399",arabic:"أُقْسِمُ إِنَّنِي لَنْ أَسْمَحَ لَكَ بِالتَّفَوُّقِ عَلَيَّ",segs:["أُقْسِمُ","إِنَّنِي لَنْ أَسْمَحَ لَكَ بِالتَّفَوُّقِ عَلَيَّ"],full_uz:"Qasam ichaman, seni mendan ustun kelishingga yo‘l qo‘ymayman.",note:"التَّفَوُّقُ عَلَى — «biror kishidan ustun kelmoq»."},
{num:221,time:"00:17:20,399 --> 00:17:25,240",arabic:"لَمْ يَبْقَ إِلَّا أَمْثَالُكَ يَا ابْنَ حَنْبَلٍ يَتَفَوَّقُونَ عَلَى صُهَيْبٍ",segs:["لَمْ يَبْقَ إِلَّا أَمْثَالُكَ","يَا ابْنَ حَنْبَلٍ","يَتَفَوَّقُونَ عَلَى صُهَيْبٍ"],full_uz:"Endi faqat sening kabi odamlar Suhaybdan ustun kelmay qolgan edi-da!",note:null},
{num:222,time:"00:17:25,240 --> 00:17:28,099",arabic:"فَلْتَقْتُلْنِي أُمِّي إِنْ كَانَ ذَلِكَ",segs:null,full_uz:"Agar shunday bo‘lsa, onam meni o‘ldirsin.",note:null},
{num:223,time:"00:17:28,099 --> 00:17:57,099",arabic:"مُوسِيقَى",segs:null,full_uz:null,note:null},
{num:224,time:"00:17:58,099 --> 00:18:02,099",arabic:"أُمِّي؟",segs:null,full_uz:"Onajon?",note:null},
{num:225,time:"00:18:02,099 --> 00:18:05,179",arabic:"أَنَا هُنَا يَا وَلَدِي، تَعَالَ",segs:["أَنَا هُنَا يَا وَلَدِي","تَعَالَ"],full_uz:"Men shu yerdaman, bolam, kel.",note:null},
{num:226,time:"00:18:05,179 --> 00:18:11,579",arabic:"السَّلَامُ عَلَيْكُمْ",segs:null,full_uz:"Assalomu alaykum.",note:null},
{num:227,time:"00:18:11,579 --> 00:18:13,659",arabic:"وَعَلَيْكُمُ السَّلَامُ وَرَحْمَةُ اللَّهِ",segs:null,full_uz:"Va alaykum assalom va Allohning rahmati bo‘lsin.",note:null},
{num:228,time:"00:18:13,659 --> 00:18:18,359",arabic:"ظَنَنْتُ أَنَّكَ سَتَمْكُثُ فِي الْمَسْجِدِ وَقْتًا أَطْوَلَ مِنْ ذَلِكَ يَا بُنَيَّ",segs:["ظَنَنْتُ أَنَّكَ سَتَمْكُثُ فِي الْمَسْجِدِ وَقْتًا أَطْوَلَ مِنْ ذَلِكَ","يَا بُنَيَّ"],full_uz:"Men masjidda bundan ham uzoqroq qolasan deb o‘ylagandim, bolam.",note:"مَكَثَ — «qolmoq, turmoq»."},
{num:229,time:"00:18:18,359 --> 00:18:21,579",arabic:"مَا هَذَا؟",segs:null,full_uz:"Bu nima?",note:null},
{num:230,time:"00:18:21,579 --> 00:18:27,539",arabic:"كَمَا تَرَى، أُحَاوِلُ أَنْ أَشْغَلَ نَفْسِي بِأَمْرٍ يَدْفَعُ عَنِّي السَّأَمَ وَالْمَلَلَ",segs:["كَمَا تَرَى","أُحَاوِلُ أَنْ أَشْغَلَ نَفْسِي بِأَمْرٍ","يَدْفَعُ عَنِّي السَّأَمَ وَالْمَلَلَ"],full_uz:"Ko‘rib turganingdek, o‘zimni zerikish va malollikdan xalos qiladigan bir ish bilan band qilishga harakat qilyapman.",note:"شَغَلَ نَفْسَهُ بِـ — «o‘zini biror ish bilan band qilmoq»; السَّأَمُ وَالْمَلَلُ — «zerikish, malollik»."},
{num:231,time:"00:18:27,539 --> 00:18:34,119",arabic:"وَلِمَنْ هَذَا؟",segs:null,full_uz:"Bu kim uchun?",note:null},
{num:232,time:"00:18:34,119 --> 00:18:36,319",arabic:"لِأُمِّ عُمَرَ الدِّمَشْقِيَّةِ",segs:null,full_uz:"Ummu Umar ad-Dimashqiyya uchun.",note:null},
{num:233,time:"00:18:36,319 --> 00:18:41,579",arabic:"أُمُّ عُمَرَ، إِذَنْ أَنْتِ تَعْمَلِينَ بِأُجْرِهَا",segs:["أُمُّ عُمَرَ","إِذَنْ أَنْتِ تَعْمَلِينَ بِأُجْرِهَا"],full_uz:"Ummu Umar... Demak, siz uning haqiga ishlab beryapsiz.",note:"بِأُجْرِهَا — «uning mehnat haqi evaziga» ma’nosida."},
{num:234,time:"00:18:41,579 --> 00:18:51,299",arabic:"وَمَا الضَّيْرُ فِي أَنْ أَكْسِبَ بَعْضَ الْمَالِ مِنْ شُغْلِ يَدِي",segs:["وَمَا الضَّيْرُ فِي أَنْ أَكْسِبَ بَعْضَ الْمَالِ","مِنْ شُغْلِ يَدِي"],full_uz:"Qo‘l mehnatim bilan ozgina pul topishimning nimasi yomon?",note:"مَا الضَّيْرُ فِي — «buning nimasi yomon?, bundan nima zarar bor?»."},
{num:235,time:"00:18:51,299 --> 00:18:53,779",arabic:"وَأَنْ أَشْغَلَ وَقْتِي بِشَيْءٍ مُفِيدٍ",segs:null,full_uz:"Va vaqtimni foydali narsa bilan o‘tkazishimning ham.",note:null},
{num:236,time:"00:18:53,779 --> 00:18:56,299",arabic:"لَقَدْ مَلِلْتُ يَا وَلَدِي مَلِلْتُ",segs:["لَقَدْ مَلِلْتُ يَا وَلَدِي","مَلِلْتُ"],full_uz:"Juda zerikdim, bolam, juda zerikdim.",note:"مَلَّ — «zerikmoq, charchamoq»."},
{num:237,time:"00:18:56,299 --> 00:19:02,680",arabic:"أَلَمْ تَقُلْ لِي أَنَّنَا لَسْنَا بِحَاجَةٍ إِلَى الْمَالِ وَمَا يَأْتِينَا مِنْ كِرَاءِ الدُّكَّانِ يَكْفِينَا؟",segs:["أَلَمْ تَقُلْ لِي أَنَّنَا لَسْنَا بِحَاجَةٍ إِلَى الْمَالِ","وَمَا يَأْتِينَا مِنْ كِرَاءِ الدُّكَّانِ يَكْفِينَا؟"],full_uz:"Menga bizga pul kerak emasligini, do‘kon ijarasidan keladigan daromad bizga yetishini aytmaganmiding?",note:"كِرَاءُ الدُّكَّانِ — «do‘kon ijarasi»; يَكْفِينَا — «bizga yetadi»."},
{num:238,time:"00:19:02,680 --> 00:19:05,579",arabic:"أَجَلْ، وَقَدْ صَدَّقْتُكِ فِي ذَلِكَ",segs:["أَجَلْ","وَقَدْ صَدَّقْتُكِ فِي ذَلِكَ"],full_uz:"Ha, bu borada sizning gapingizga ishongandim.",note:"صَدَّقَهُ — «uning gapini rost deb bilmoq, ishonmoq»."},
{num:239,time:"00:19:05,579 --> 00:19:11,879",arabic:"وَلَكِنْ يَا بُنَيَّ، أَنْتَ تُمْضِي أَكْثَرَ وَقْتِكَ فِي الْمَسْجِدِ",segs:["وَلَكِنْ يَا بُنَيَّ","أَنْتَ تُمْضِي أَكْثَرَ وَقْتِكَ فِي الْمَسْجِدِ"],full_uz:"Lekin, bolam, sen vaqtingning ko‘p qismini masjidda o‘tkazasan.",note:"أَمْضَى وَقْتَهُ — «vaqtini o‘tkazmoq»."},
{num:240,time:"00:19:11,879 --> 00:19:17,000",arabic:"وَأَبْقَى أَنَا هُنَا وَحْدِي، حَبِيسَةَ الْبَيْتِ، رَهِينَةَ جُدْرَانِهِ",segs:["وَأَبْقَى أَنَا هُنَا وَحْدِي","حَبِيسَةَ الْبَيْتِ","رَهِينَةَ جُدْرَانِهِ"],full_uz:"Men esa bu yerda yolg‘iz, uyga qamalgan, uning devorlariga go‘yo asir bo‘lib qolaman.",note:"حَبِيسَةُ الْبَيْتِ — «uyga qamalgan»; رَهِينَةُ جُدْرَانِهِ — «uning devorlariga asir»."},
{num:241,time:"00:19:17,000 --> 00:19:19,680",arabic:"يَمْضِي عَلَيَّ الْوَقْتُ بِبُطْءٍ وَمَلَلٍ",segs:null,full_uz:"Vaqt men uchun sekin va zerikarli o‘tadi.",note:"يَمْضِي عَلَيْهِ الْوَقْتُ — «uning vaqti o‘tadi»."},
{num:242,time:"00:19:19,680 --> 00:19:23,859",arabic:"وَالْبَقَاءُ فِي الْبَيْتِ دُونَ عَمَلٍ يُمْرِضُ النَّفْسَ وَالْبَدَنَ",segs:["وَالْبَقَاءُ فِي الْبَيْتِ دُونَ عَمَلٍ","يُمْرِضُ النَّفْسَ وَالْبَدَنَ"],full_uz:"Uyda ishsiz o‘tirish ruhni ham, badanni ham kasallantiradi.",note:"يُمْرِضُ — «kasal qilmoq, dardga solmoq»."},
{num:243,time:"00:19:23,859 --> 00:19:27,619",arabic:"وَأَنَا لِيَ أَنْ أَقْبَلَ بِعَمَلِكَ هَذَا بَيْنَمَا أَنَا أَبْقَى بِالْعَمَلِ",segs:["وَأَنَا لِيَ أَنْ أَقْبَلَ بِعَمَلِكَ هَذَا","بَيْنَمَا أَنَا أَبْقَى بِالْعَمَلِ"],full_uz:"Men ishlab yurishim mumkin bo‘lsa, sening bu ishingni qanday qabul qilmay?",note:null},
{num:244,time:"00:19:27,619 --> 00:19:28,799",arabic:"اِسْمَعْ يَا وَلَدِي",segs:["اِسْمَعْ","يَا وَلَدِي"],full_uz:"Eshit, bolam.",note:null},
{num:245,time:"00:19:28,799 --> 00:19:33,859",arabic:"لِكُلِّ وَاحِدٍ مِنَّا فِي هَذِهِ الْحَيَاةِ عَمَلٌ مَقْسُومٌ وَدَوْرٌ مَعْلُومٌ",segs:["لِكُلِّ وَاحِدٍ مِنَّا فِي هَذِهِ الْحَيَاةِ","عَمَلٌ مَقْسُومٌ وَدَوْرٌ مَعْلُومٌ"],full_uz:"Bu hayotda har birimizning o‘ziga belgilangan ishi va ma’lum vazifasi bor.",note:"عَمَلٌ مَقْسُومٌ — «taqsimlangan, belgilangan ish»; دَوْرٌ مَعْلُومٌ — «ma’lum vazifa, rol»."},
{num:246,time:"00:19:33,859 --> 00:19:39,479",arabic:"وَأَنَا عَمَلِي الْآنَ أَنْ أُؤَمِّنَ لَكَ مَا تُرِيدُ مِنْ أَجْلِ أَنْ تُكْمِلَ دِرَاسَتَكَ",segs:["وَأَنَا عَمَلِي الْآنَ","أَنْ أُؤَمِّنَ لَكَ مَا تُرِيدُ","مِنْ أَجْلِ أَنْ تُكْمِلَ دِرَاسَتَكَ"],full_uz:"Mening hozirgi vazifam esa o‘qishingni tugatishing uchun istagan narsangni ta’minlash.",note:"أَمَّنَ لَهُ — «ta’minlab bermoq»."},
{num:247,time:"00:19:39,479 --> 00:19:43,740",arabic:"وَأَنْتَ دَوْرُكَ أَنْ تَمْتَازَ فِي عِلْمِكَ كَيْ تُحَقِّقَ مَا تَصْبُو إِلَيْهِ",segs:["وَأَنْتَ دَوْرُكَ","أَنْ تَمْتَازَ فِي عِلْمِكَ","كَيْ تُحَقِّقَ مَا تَصْبُو إِلَيْهِ"],full_uz:"Sening vazifang esa ilmingda yuqori natijalarga erishib, intilayotgan narsangga yetishish.",note:"اِمْتَازَ فِي عِلْمِهِ — «ilmida ajralib turmoq, yuqori natijaga erishmoq»; تَصْبُو إِلَيْهِ — «unga intilayotgan narsa»."},
{num:248,time:"00:19:43,740 --> 00:19:48,619",arabic:"لِذَلِكَ لَا أُرِيدُ كَلَامًا فِي هَذَا الْأَمْرِ مَرَّةً أُخْرَى",segs:["لِذَلِكَ","لَا أُرِيدُ كَلَامًا فِي هَذَا الْأَمْرِ مَرَّةً أُخْرَى"],full_uz:"Shuning uchun bu masala haqida boshqa gap bo‘lishini istamayman.",note:null},
{num:249,time:"00:19:53,859 --> 00:20:18,740",arabic:"كُنْتُ أُرِيدُ أَنْ أُحَدِّثَكَ فِي أَمْرٍ يَا وَلَدِي",segs:["كُنْتُ أُرِيدُ أَنْ أُحَدِّثَكَ فِي أَمْرٍ","يَا وَلَدِي"],full_uz:"Men sen bilan bir masala haqida gaplashmoqchi edim, bolam.",note:null},
{num:250,time:"00:20:18,740 --> 00:20:21,459",arabic:"وَأَنَا طَوْعُ أَمْرِكَ يَا أُمَّاهُ",segs:["وَأَنَا طَوْعُ أَمْرِكِ","يَا أُمَّاهُ"],full_uz:"Men sizning ixtiyoringizdaman, onajon.",note:"طَوْعُ أَمْرِهِ — «uning buyrug‘iga bo‘ysunuvchi, ixtiyorida»."},
{num:251,time:"00:20:21,459 --> 00:20:23,839",arabic:"وَإِنْ كُنْتُ أَتَوَقَّعُ مِنْكَ",segs:null,full_uz:"Garchi sendan shuni kutayotgan bo‘lsam-da...",note:"أَتَوَقَّعُ مِنْكَ — «sendan kutmoq, sendan shuni kutayotgan bo‘lmoq»."},
{num:252,time:"00:20:23,839 --> 00:20:25,839",arabic:"وَمَا سَتَقُولِينَ؟",segs:null,full_uz:"Nima demoqchisiz?",note:null},
{num:253,time:"00:20:27,839 --> 00:20:29,839",arabic:"وَمَا هُوَ يَا قُرَّةَ عَيْنِي؟",segs:["وَمَا هُوَ","يَا قُرَّةَ عَيْنِي؟"],full_uz:"U nima ekan, ko‘z quvonchim?",note:"قُرَّةُ عَيْنِي — «ko‘z quvonchi, juda aziz insonim» ma’nosidagi mehr ifodasi."},
{num:254,time:"00:20:30,839 --> 00:20:32,839",arabic:"أَلَيْسَ شَأْنًا خَاصًّا بِالنِّسَاءِ؟",segs:["أَلَيْسَ شَأْنًا خَاصًّا","بِالنِّسَاءِ؟"],full_uz:"Bu ayollarga xos masala emasmi?",note:"شَأْنٌ خَاصٌّ بِـ — «...ga xos masala»."},
{num:255,time:"00:20:34,839 --> 00:20:37,839",arabic:"لَا تَنْقُصُكَ الْفِتْنَةُ يَا وَلَدِي",segs:["لَا تَنْقُصُكَ الْفِتْنَةُ","يَا وَلَدِي"],full_uz:"Jozibangdan hech narsa kam emas, bolam.",note:"فِتْنَةٌ — bu yerda «joziba, husn» ma’nosida."},
{num:256,time:"00:20:39,839 --> 00:20:41,839",arabic:"وَأَنَا أَطْوَعُ أَمْرِكِ مَتَى شِئْتِ",segs:["وَأَنَا أَطْوَعُ أَمْرِكِ","مَتَى شِئْتِ"],full_uz:"Men ham qachon istasangiz, amringizga bo‘ysunaman.",note:"طَوْعُ أَمْرِكِ — «amringizga bo‘ysunuvchi, ixtiyoringizda»."},
{num:257,time:"00:20:45,839 --> 00:20:47,839",arabic:"اِسْمَعْ يَا مُحَمَّدُ",segs:["اِسْمَعْ","يَا مُحَمَّدُ"],full_uz:"Eshit, ey Muhammad.",note:null},
{num:258,time:"00:20:47,839 --> 00:20:52,839",arabic:"لَقَدِ اخْتَرْتُ لَكَ فَتَاةً مِنْ خِيَرَةِ بُيُوتَاتِ قُرَيْشٍ",segs:["لَقَدِ اخْتَرْتُ لَكَ فَتَاةً","مِنْ خِيَرَةِ بُيُوتَاتِ قُرَيْشٍ"],full_uz:"Men sen uchun Qurayshning eng yaxshi xonadonlaridan bir qizni tanladim.",note:"خِيَرَةُ الْبُيُوتَاتِ — «eng yaxshi, asl xonadonlar»."},
{num:259,time:"00:20:53,839 --> 00:21:00,839",arabic:"فَتَاةٌ جَمِيلَةٌ، صَائِمَةٌ، قَائِمَةٌ، تَعْرِفُ رَبَّهَا حَقَّ مَعْرِفَةٍ",segs:["فَتَاةٌ جَمِيلَةٌ","صَائِمَةٌ قَائِمَةٌ","تَعْرِفُ رَبَّهَا حَقَّ مَعْرِفَةٍ"],full_uz:"Go‘zal qiz, ro‘za tutadi, ibodat qiladi va Robbisini haqiqiy ma’noda taniydi.",note:"قَائِمَةٌ — bu yerda «tunda namoz o‘qiydigan, ibodat qiladigan» ma’nosida; حَقَّ مَعْرِفَةٍ — «chinakam, to‘la bilish»."},
{num:260,time:"00:21:01,839 --> 00:21:03,839",arabic:"ابْنَةُ مَنْ هِيَ يَا أُمَّهُ؟",segs:["ابْنَةُ مَنْ هِيَ","يَا أُمَّهُ؟"],full_uz:"U kimning qizi, onajon?",note:null},
{num:261,time:"00:21:03,839 --> 00:21:08,839",arabic:"ابْنَةُ نَافِعٍ، حَفِيدَةُ عُثْمَانَ بْنِ عَفَّانَ رَضِيَ اللَّهُ عَنْهُ",segs:["ابْنَةُ نَافِعٍ","حَفِيدَةُ عُثْمَانَ بْنِ عَفَّانَ رَضِيَ اللَّهُ عَنْهُ"],full_uz:"Nofi’ning qizi, Usmon ibn Affonning nabirasi.",note:"حَفِيدَةٌ — «nabira qiz»."},
{num:262,time:"00:21:09,839 --> 00:21:15,839",arabic:"رَضِيَ اللَّهُ عَنْ جَدِّهَا وَأَرْضَاهَا، مَا أَحْسَنَ اخْتِيَارَكِ يَا أُمَّهُ",segs:["رَضِيَ اللَّهُ عَنْ جَدِّهَا وَأَرْضَاهَا","مَا أَحْسَنَ اخْتِيَارَكِ يَا أُمَّهُ"],full_uz:"Alloh uning bobosidan rozi bo‘lsin va undan ham rozi bo‘lsin. Tanlovingiz naqadar yaxshi, onajon!",note:"مَا أَحْسَنَ اخْتِيَارَكِ — «tanlovingiz naqadar yaxshi!»."},
{num:263,time:"00:21:15,839 --> 00:21:19,839",arabic:"إِذَنْ أَفْهَمُ مِنْ هَذَا أَنَّكَ مُوَافِقٌ",segs:["إِذَنْ أَفْهَمُ مِنْ هَذَا","أَنَّكَ مُوَافِقٌ"],full_uz:"Demak, bundan rozi ekaningni tushunyapman.",note:"أَفْهَمُ مِنْ هَذَا أَنَّ — «bundan ... ekanini tushunaman»."},
{num:264,time:"00:21:19,839 --> 00:21:26,500",arabic:"هَلْ هُنَاكَ أَحَدٌ يَرْفُضُ حَفِيدَةَ عُثْمَانَ بْنِ عَفَّانَ يَا أُمَّ مُحَمَّدٍ؟",segs:["هَلْ هُنَاكَ أَحَدٌ يَرْفُضُ حَفِيدَةَ عُثْمَانَ بْنِ عَفَّانَ","يَا أُمَّ مُحَمَّدٍ؟"],full_uz:"Ey Ummu Muhammad, Usmon ibn Affonning nabirasini rad etadigan odam bo‘ladimi?",note:null},
{num:265,time:"00:21:26,500 --> 00:21:29,879",arabic:"حَسَنًا يَا وَلَدِي، عَلَى بَرَكَةِ اللَّهِ إِذَنْ",segs:["حَسَنًا يَا وَلَدِي","عَلَى بَرَكَةِ اللَّهِ إِذَنْ"],full_uz:"Xo‘p, bolam, unda Allohning barakasi bilan.",note:"عَلَى بَرَكَةِ اللَّهِ — «Allohning barakasi bilan, Allohga tavakkal qilib»."},
{num:266,time:"00:21:29,879 --> 00:21:36,779",arabic:"غَدًا سَأُكَلِّمُ أُمَّهَا إِنْ شَاءَ اللَّهُ وَنَرَى مَا يَكُونُ جَوَابُهَا",segs:["غَدًا سَأُكَلِّمُ أُمَّهَا إِنْ شَاءَ اللَّهُ","وَنَرَى مَا يَكُونُ جَوَابُهَا"],full_uz:"Ertaga, inshaalloh, onasi bilan gaplashaman va javobi nima bo‘lishini ko‘ramiz.",note:null},
{num:267,time:"00:21:36,779 --> 00:21:41,159",arabic:"كَمَا تُحِبِّينَ، أَرَضِيتِ الْآنَ؟",segs:["كَمَا تُحِبِّينَ","أَرَضِيتِ الْآنَ؟"],full_uz:"Xuddi xohlaganingizdek. Endi ko‘nglingiz to‘ldimi?",note:"أَرَضِيتِ؟ — «rozi bo‘ldingizmi?, ko‘nglingiz to‘ldimi?»."},
{num:268,time:"00:21:41,159 --> 00:21:42,740",arabic:"وَمَتَى لَمْ أَكُنْ كَذَلِكَ",segs:null,full_uz:"Qachon unday bo‘lmaganman?",note:"Bu yerda ritorik savol bo‘lib, «Men har doim shundayman-ku» mazmunida."},
{num:269,time:"00:21:42,740 --> 00:21:48,699",arabic:"إِنِّي أَدْعُو لَكَ صَبَاحَ مَسَاءَ عَلَى بِرِّكَ وَطَاعَتِكَ لِي يَا وَلَدِي",segs:["إِنِّي أَدْعُو لَكَ صَبَاحَ مَسَاءَ","عَلَى بِرِّكَ وَطَاعَتِكَ لِي","يَا وَلَدِي"],full_uz:"Men sening menga qilayotgan yaxshiliging va itoating tufayli har tongu kech sening haqqingga duo qilaman, bolam.",note:"بِرُّهُ — «yaxshiligi, ezguligi»; طَاعَتُهُ لِي — «menga itoati»."},
{num:270,time:"00:21:48,700 --> 00:22:08,220",arabic:"يَا أُمَّ خَالِدٍ",segs:null,full_uz:"Ey Ummu Xolid.",note:null},
{num:271,time:"00:22:08,220 --> 00:22:12,000",arabic:"جِئْتُكِ فِي حَاجَةٍ قَضَاؤُهَا عَلَى يَدَيْكِ",segs:["جِئْتُكِ فِي حَاجَةٍ","قَضَاؤُهَا عَلَى يَدَيْكِ"],full_uz:"Men sizning oldingizga ado etilishi sizning qo‘lingizda bo‘lgan bir iltimos bilan keldim.",note:"قَضَاءُ الْحَاجَةِ عَلَى يَدَيْهِ — «hojatni uning qo‘li bilan ado etish»."},
{num:272,time:"00:22:12,000 --> 00:22:14,880",arabic:"وَأَرْجُو أَنْ لَا أَخْرُجَ مِنْ بَيْتِكِ خَائِبَةً",segs:["وَأَرْجُو أَنْ لَا أَخْرُجَ مِنْ بَيْتِكِ","خَائِبَةً"],full_uz:"Uyingizdan umidsiz qaytmasligimga umid qilaman.",note:"خَائِبٌ — «umidi puchga chiqqan, noumid»."},
{num:273,time:"00:22:14,880 --> 00:22:17,680",arabic:"لَا خَيَّبَ اللَّهُ لَكِ رَجَاءً",segs:null,full_uz:"Alloh umidingizni puchga chiqarmasin.",note:"لَا خَيَّبَ اللَّهُ رَجَاءً — «Alloh umidni puchga chiqarmasin»."},
{num:274,time:"00:22:17,680 --> 00:22:18,640",arabic:"تَفَضَّلِي",segs:null,full_uz:"Marhamat.",note:null},
{num:275,time:"00:22:18,640 --> 00:22:22,940",arabic:"الْحَقُّ مُذْ رَأَيْتُ شَهْنَازَ نَالَتْ إِعْجَابِي",segs:["الْحَقُّ مُذْ رَأَيْتُ شَهْنَازَ","نَالَتْ إِعْجَابِي"],full_uz:"To‘g‘risi, Shahnozni ko‘rganimdan beri u menga juda ma’qul kelgan.",note:"نَالَ إِعْجَابِي — «menga yoqdi, ma’qul keldi»."},
{num:276,time:"00:22:22,940 --> 00:22:25,799",arabic:"وَتَمَنَّيْتُ أَنْ تَكُونَ لِي كَنَّةً",segs:["وَتَمَنَّيْتُ","أَنْ تَكُونَ لِي كَنَّةً"],full_uz:"Uni kelinim bo‘lishini istadim.",note:"كَنَّةٌ — «kelin», ya’ni o‘g‘ilning xotini."},
{num:277,time:"00:22:25,799 --> 00:22:29,039",arabic:"وَقُلْتُ فِي نَفْسِي عَسَى اللَّهُ أَنْ يَجْعَلَهَا لِوَلَدِي مَرْوَانَ",segs:["وَقُلْتُ فِي نَفْسِي","عَسَى اللَّهُ أَنْ يَجْعَلَهَا لِوَلَدِي مَرْوَانَ"],full_uz:"Ichimda: «Balki Alloh uni o‘g‘lim Marvonga nasib qilar», deb o‘yladim.",note:"عَسَى اللَّهُ أَنْ — «Alloh nasib qilsa, balki»."},
{num:278,time:"00:22:29,039 --> 00:22:33,299",arabic:"وَقَدْ طَلَبَ مِنِّي مَرْوَانُ الْيَوْمَ أَنْ أَخْطُبَهَا لَهُ مِنْكِ",segs:["وَقَدْ طَلَبَ مِنِّي مَرْوَانُ الْيَوْمَ","أَنْ أَخْطُبَهَا لَهُ مِنْكِ"],full_uz:"Bugun Marvon mendan uni sening oldingdan o‘zi uchun so‘rab kelishimni iltimos qildi.",note:"خَطَبَ الْمَرْأَةَ — «ayolga sovchi qo‘ymoq, nikoh uchun so‘ramoq»."},
{num:279,time:"00:22:33,299 --> 00:22:35,640",arabic:"وَنِعْمَ الْفَتَى مَرْوَانُ",segs:null,full_uz:"Marvon juda yaxshi yigit.",note:"نِعْمَ الْفَتَى — «qanday yaxshi yigit!»."},
{num:280,time:"00:22:35,640 --> 00:22:40,539",arabic:"وَلَكِنَّكِ كَمَا تَعْلَمِينَ أَنَّ هَذَا الْأَمْرَ لَيْسَ بِيَدِي",segs:["وَلَكِنَّكِ كَمَا تَعْلَمِينَ","أَنَّ هَذَا الْأَمْرَ لَيْسَ بِيَدِي"],full_uz:"Lekin o‘zingiz bilasiz, bu masala mening qo‘limda emas.",note:"لَيْسَ بِيَدِي — «mening ixtiyorimda emas»."},
{num:281,time:"00:22:40,539 --> 00:22:44,920",arabic:"فَشَهْنَازُ سَيِّدَةُ نَفْسِهَا وَمَالِكَةُ أَمْرِهَا",segs:["فَشَهْنَازُ سَيِّدَةُ نَفْسِهَا","وَمَالِكَةُ أَمْرِهَا"],full_uz:"Chunki Shahnoz o‘ziga o‘zi xo‘jayin va o‘z ishining egasidir.",note:"سَيِّدَةُ نَفْسِهَا — «o‘z ixtiyoriga ega, mustaqil»; مَالِكَةُ أَمْرِهَا — «o‘z taqdirini o‘zi belgilaydigan»."},
{num:282,time:"00:22:44,920 --> 00:22:50,840",arabic:"أَعْلَمُ ذَلِكَ يَا أُمَّ خَالِدٍ وَلَكِنَّكِ الْآنَ فِي مَقَامِ أُمِّهَا",segs:["أَعْلَمُ ذَلِكَ يَا أُمَّ خَالِدٍ","وَلَكِنَّكِ الْآنَ فِي مَقَامِ أُمِّهَا"],full_uz:"Buni bilaman, ey Ummu Xolid, lekin hozir siz uning onasi o‘rnidasiz.",note:"فِي مَقَامِ — «o‘rnida, mavqeida»."},
{num:283,time:"00:22:50,840 --> 00:22:54,720",arabic:"وَلَا يَصِحُّ لِي أَنْ أُكَلِّمَهَا فِي الْأَمْرِ وَهِيَ فِي بَيْتِكِ",segs:["وَلَا يَصِحُّ لِي أَنْ أُكَلِّمَهَا فِي الْأَمْرِ","وَهِيَ فِي بَيْتِكِ"],full_uz:"U sizning uyingizda ekan, bu masalani u bilan gaplashishim to‘g‘ri bo‘lmaydi.",note:"لَا يَصِحُّ لِي — «men uchun to‘g‘ri/munosib emas»."},
{num:284,time:"00:22:54,720 --> 00:23:01,900",arabic:"أُرِيدُ مِنْكِ إِنْ بَارَكْتِ ذَلِكَ أَنْ تُكَلِّمِيهَا وَتُزَكِّيَ لَهَا وَلَدَكِ مَرْوَانَ",segs:["أُرِيدُ مِنْكِ إِنْ بَارَكْتِ ذَلِكَ","أَنْ تُكَلِّمِيهَا وَتُزَكِّيَ لَهَا وَلَدَكِ مَرْوَانَ"],full_uz:"Agar bunga ma’qul ko‘rsangiz, undan bu haqda gapirib, o‘g‘lingiz Marvonni unga tavsiya qilishingizni istayman.",note:"زَكَّى لَهُ — «biror kishini maqtab, yaxshi tavsiya qilmoq»."},
{num:285,time:"00:23:01,900 --> 00:23:04,200",arabic:"وَسَأَكُونُ لَكِ مِنَ الشَّاكِرِينَ",segs:null,full_uz:"Sizdan minnatdor bo‘laman.",note:"مِنَ الشَّاكِرِينَ — «minnatdor bo‘ladiganlardan bo‘laman»."},
{num:286,time:"00:23:04,200 --> 00:23:11,180",arabic:"تَعْلَمِينَ أَنَّ مَرْوَانَ مِثْلُ وَلَدِي خَالِدٍ وَأَعِدُكِ بِأَنَّنِي سَأُحَاوِلُ",segs:["تَعْلَمِينَ أَنَّ مَرْوَانَ مِثْلُ وَلَدِي خَالِدٍ","وَأَعِدُكِ بِأَنَّنِي سَأُحَاوِلُ"],full_uz:"Marvon mening o‘g‘lim Xolid kabi ekanini bilasiz. Sizga va’da beraman, harakat qilaman.",note:"مِثْلُ وَلَدِي — «o‘z farzandimdek»."},
{num:287,time:"00:23:11,180 --> 00:23:16,240",arabic:"وَلَكِنَّكِ كَمَا تَعْلَمِينَ إِنَّ هَذَا الْأَمْرَ بِيَدِ شَهْنَازَ",segs:["وَلَكِنَّكِ كَمَا تَعْلَمِينَ","إِنَّ هَذَا الْأَمْرَ بِيَدِ شَهْنَازَ"],full_uz:"Lekin o‘zingiz bilasiz, bu masala Shahnozning ixtiyorida.",note:"بِيَدِ — «ixtiyorida, qo‘lida»."},
{num:288,time:"00:23:16,240 --> 00:23:19,480",arabic:"إِنْ وَافَقَتْ أَسْعَدَنِي ذَلِكَ",segs:["إِنْ وَافَقَتْ","أَسْعَدَنِي ذَلِكَ"],full_uz:"Agar rozi bo‘lsa, bundan xursand bo‘laman.",note:"وَافَقَتْ — «rozi bo‘ldi»."},
{num:289,time:"00:23:19,480 --> 00:23:22,759",arabic:"وَإِنْ لَمْ تُوَافِقْ فَلَا أَسْتَطِيعُ إِجْبَارَهَا",segs:["وَإِنْ لَمْ تُوَافِقْ","فَلَا أَسْتَطِيعُ إِجْبَارَهَا"],full_uz:"Agar rozi bo‘lmasa, uni majburlay olmayman.",note:"إِجْبَارٌ — «majburlash»."},
{num:290,time:"00:23:22,759 --> 00:23:24,880",arabic:"جَزَاكَ اللَّهُ خَيْرًا يَا أَخِي",segs:["جَزَاكَ اللَّهُ خَيْرًا","يَا أَخِي"],full_uz:"Alloh sizni yaxshilik bilan mukofotlasin, aka.",note:null},
{num:291,time:"00:23:24,880 --> 00:23:26,680",arabic:"وَأَنَا عَلَى يَقِينٍ",segs:null,full_uz:"Men bunga aminman.",note:"عَلَى يَقِينٍ — «ishonch bilan, qat’iy amin bo‘lib»."},
{num:292,time:"00:23:26,680 --> 00:23:29,140",arabic:"إِنْ زَكَّيْتِ مَرْوَانَ لَدَيْهَا",segs:null,full_uz:"Agar uning oldida Marvonni tavsiya qilsangiz,",note:"زَكَّى لَدَيْهِ — «uning oldida yaxshi tavsiflab/tavsiya qilmoq»."},
{num:293,time:"00:23:29,140 --> 00:23:32,980",arabic:"فَإِنَّ الْخَيْرَ إِنْ شَاءَ اللَّهُ سَيَكُونُ عَلَى يَدَيْكِ",segs:["فَإِنَّ الْخَيْرَ إِنْ شَاءَ اللَّهُ","سَيَكُونُ عَلَى يَدَيْكِ"],full_uz:"Inshaalloh, yaxshilik sizning qo‘lingiz bilan bo‘ladi.",note:"عَلَى يَدَيْكِ — «sizning vositangiz bilan»."},
{num:294,time:"00:23:32,980 --> 00:23:35,019",arabic:"إِنْ شَاءَ اللَّهُ يَا أُمَّ مَرْوَانَ",segs:["إِنْ شَاءَ اللَّهُ","يَا أُمَّ مَرْوَانَ"],full_uz:"Inshaalloh, ey Ummu Marvon.",note:null},
{num:295,time:"00:23:35,019 --> 00:23:35,880",arabic:"إِنْ شَاءَ اللَّهُ",segs:null,full_uz:"Inshaalloh.",note:null},
{num:296,time:"00:23:41,180 --> 00:23:50,519",arabic:"اِسْمَعِي يَا فَوْزُ",segs:["اِسْمَعِي","يَا فَوْزُ"],full_uz:"Eshit, ey Fawz.",note:null},
{num:297,time:"00:23:50,519 --> 00:23:53,779",arabic:"إِنَّ مَا تَفْعَلِينَهُ مُزْعِجٌ لَكِ وَلِي",segs:["إِنَّ مَا تَفْعَلِينَهُ مُزْعِجٌ لَكِ وَلِي"],full_uz:"Qilayotgan ishing ham seni, ham meni qiynayapti.",note:"مُزْعِجٌ — «bezovta qiluvchi, qiynovchi»."},
{num:298,time:"00:23:53,779 --> 00:23:55,240",arabic:"فَلَا تُصِرِّي عَلَيَّ",segs:null,full_uz:"Menga qattiq turib olma.",note:"أَصَرَّ عَلَى — «biror narsada qattiq turib olmoq, o‘jarlik qilmoq»."},
{num:299,time:"00:23:55,240 --> 00:23:58,019",arabic:"وَلَنْ نَبْقَى إِلَى آخِرِ الْعُمْرِ هَكَذَا",segs:null,full_uz:"Umrimizning oxirigacha bunday qolmaymiz.",note:null},
{num:300,time:"00:23:58,019 --> 00:24:00,120",arabic:"اِحْدَثِي عَنْ نَفْسِكِ",segs:null,full_uz:"O‘zing haqida gapir.",note:null},
{num:301,time:"00:24:00,120 --> 00:24:02,400",arabic:"فَأَنَا لَا أَمَلُّ وَلَا نَمَلُّ",segs:["فَأَنَا لَا أَمَلُّ","وَلَا نَمَلُّ"],full_uz:"Men charchamayman, zerikmayman ham.",note:"مَلَّ — «zerikmoq, charchamoq»."},
{num:302,time:"00:24:02,400 --> 00:24:04,580",arabic:"أَيَّتُهَا الْبَائِسَةُ",segs:null,full_uz:"Ey bechora.",note:"الْبَائِسَةُ — «baxtsiz, bechora ayol»."},
{num:303,time:"00:24:04,580 --> 00:24:05,759",arabic:"أَذْهَبَ اللَّهُ عَقْلَكِ",segs:null,full_uz:"Alloh aqlingni olib qo‘ysin.",note:"أَذْهَبَ اللَّهُ عَقْلَهُ — qattiq koyish yoki haqorat mazmunidagi ibora."},
{num:304,time:"00:24:05,759 --> 00:24:09,100",arabic:"إِنَّكِ تُصِرِّينَ عَلَى إِرْهَاقِ نَفْسِكِ دُونَ طَائِلٍ",segs:["إِنَّكِ تُصِرِّينَ عَلَى إِرْهَاقِ نَفْسِكِ","دُونَ طَائِلٍ"],full_uz:"Sen hech qanday foydasiz o‘zingni qiynashda turib olyapsan.",note:"دُونَ طَائِلٍ — «foydasiz, natijasiz»; أَرْهَقَ نَفْسَهُ — «o‘zini qiynamoq»."},
{num:305,time:"00:24:09,099 --> 00:24:14,199",arabic:"مَا رَأْيُكِ أَنْ نَجِدَ حَلًّا وَسَطًا؟",segs:["مَا رَأْيُكِ","أَنْ نَجِدَ حَلًّا وَسَطًا؟"],full_uz:"O‘rtacha bir yechim topsak, nima deysan?",note:"حَلٌّ وَسَطٌ — «o‘rtacha, murosali yechim»."},
{num:306,time:"00:24:14,199 --> 00:24:18,319",arabic:"أَتَنَازَلُ أَنَا قَلِيلًا وَتَتَنَازَلِينَ أَنْتِ قَلِيلًا",segs:["أَتَنَازَلُ أَنَا قَلِيلًا","وَتَتَنَازَلِينَ أَنْتِ قَلِيلًا"],full_uz:"Men biroz yon beraman, sen ham biroz yon berasan.",note:"تَنَازَلَ عَنْ — «o‘z talabidan voz kechmoq, yon bermoq»."},
{num:307,time:"00:24:18,319 --> 00:24:22,219",arabic:"أَعِدُكِ أَنَا أَلَّا أَبِيعَكِ إِلَّا لِمَنْ تُوَافِقِينَ عَلَيْهِ",segs:["أَعِدُكِ أَلَّا أَبِيعَكِ إِلَّا","لِمَنْ تُوَافِقِينَ عَلَيْهِ"],full_uz:"Senga va’da beraman: seni faqat o‘zing rozi bo‘lgan kishiga sotaman.",note:"أَلَّا أَبِيعَكِ إِلَّا — «seni faqat ...ga sotaman»."},
{num:308,time:"00:24:22,219 --> 00:24:23,379",arabic:"مَا رَأْيُكِ؟",segs:null,full_uz:"Nima deysan?",note:null},
{num:309,time:"00:24:23,379 --> 00:24:25,119",arabic:"لَا وَلَنْ أُوَافِقَ",segs:null,full_uz:"Yo‘q, hech qachon rozi bo‘lmayman.",note:null},
{num:310,time:"00:24:25,119 --> 00:24:27,699",arabic:"لَسْتُ بِجَارِيَةٍ فِي سُوقِ الْعَبِيدِ",segs:null,full_uz:"Men qul bozoridagi cho‘ri emasman.",note:"جَارِيَةٌ — bu yerda «cho‘ri, qul ayol» ma’nosida."},
{num:311,time:"00:24:27,699 --> 00:24:29,419",arabic:"أَنَا حُرَّةٌ مَا بَقِيتُ",segs:null,full_uz:"Tirik ekanman, men ozodman.",note:"حُرَّةٌ — «ozod ayol»."},
{num:312,time:"00:24:29,419 --> 00:24:33,919",arabic:"وَلَوْ مِتُّ جُوعًا فَلَنْ أَقْبَلَ أَنْ أُبَاعَ أَوْ أُشْتَرَى",segs:["وَلَوْ مِتُّ جُوعًا","فَلَنْ أَقْبَلَ أَنْ أُبَاعَ أَوْ أُشْتَرَى"],full_uz:"Ochlikdan o‘lsam ham, sotilishimga yoki sotib olinishimga rozi bo‘lmayman.",note:"أُبَاعَ أَوْ أُشْتَرَى — «sotilmoq yoki sotib olinmoq»."},
{num:313,time:"00:24:33,919 --> 00:24:36,219",arabic:"ضَعِي هَذَا الْكَلَامَ نُصْبَ عَيْنَيْكِ",segs:["ضَعِي هَذَا الْكَلَامَ نُصْبَ عَيْنَيْكِ"],full_uz:"Bu gapni ko‘z o‘ngingda tut.",note:"ضَعْ نُصْبَ عَيْنَيْهِ — «doimo yodida tutmoq, e’tibordan chetda qoldirmaslik»."},
{num:314,time:"00:24:36,219 --> 00:24:38,259",arabic:"وَلَكِنِّي أَرَاكِ لَا تَفْهَمِينَ",segs:["وَلَكِنِّي أَرَاكِ","لَا تَفْهَمِينَ"],full_uz:"Lekin seni tushunmayotganingni ko‘ryapman.",note:null},
{num:315,time:"00:24:38,259 --> 00:24:41,619",arabic:"أَنْتِ جَنَيْتِ عَلَى نَفْسِكِ",segs:null,full_uz:"Bu baloni o‘zing boshiga orttirding.",note:"جَنَى عَلَى نَفْسِهِ — «o‘ziga zarar yetkazmoq, o‘z boshiga balo orttirmoq»."},
{num:316,time:"00:24:41,619 --> 00:24:45,559",arabic:"وَهَذِهِ الْمَرَّةَ لَنْ أَكْتَفِيَ بِمَنْعِ الطَّعَامِ وَالشَّرَابِ عَنْكِ",segs:["وَهَذِهِ الْمَرَّةَ","لَنْ أَكْتَفِيَ بِمَنْعِ الطَّعَامِ وَالشَّرَابِ عَنْكِ"],full_uz:"Bu safar esa seni ovqat va ichimlikdan mahrum qilish bilangina kifoyalanmayman.",note:"اِكْتَفَى بِـ — «... bilan kifoyalanmoq»."},
{num:317,time:"00:24:45,559 --> 00:24:49,140",arabic:"حَمْدَ اللَّهِ",segs:null,full_uz:"Hamdulloh.",note:null},
{num:318,time:"00:24:49,140 --> 00:24:50,619",arabic:"يَا حَمْدَ اللَّهِ",segs:null,full_uz:"Ey Hamdulloh.",note:null},
{num:319,time:"00:24:50,619 --> 00:24:52,900",arabic:"تَعَالَ إِلَيْنَا هُنَا عَلَى الْفَوْرِ",segs:["تَعَالَ إِلَيْنَا هُنَا","عَلَى الْفَوْرِ"],full_uz:"Darhol bu yerga oldimizga kel.",note:"عَلَى الْفَوْرِ — «darhol, shu zahoti»."},
{num:320,time:"00:24:52,900 --> 00:24:54,619",arabic:"لَا أَدْرِي مَا أَقُولُ لَكَ",segs:null,full_uz:"Senga nima deyishni bilmayman.",note:null},
{num:321,time:"00:24:54,619 --> 00:24:57,980",arabic:"فَأَنَا فِي حَيْرَةٍ مِنْ أَمْرِي",segs:null,full_uz:"Men o‘z ishim borasida hayron-u sarosimadaman.",note:"فِي حَيْرَةٍ مِنْ أَمْرِهِ — «nima qilishni bilmay, ikkilanib qolgan»."},
{num:322,time:"00:24:57,980 --> 00:25:02,539",arabic:"وَلَكِنَّكِ وَقَعْتِ مَوْقِعًا فِي قَلْبِ أُمِّي مَرْوَانَ",segs:["وَلَكِنَّكِ وَقَعْتِ مَوْقِعًا فِي قَلْبِ أُمِّي مَرْوَانَ"],full_uz:"Lekin sen Marvonning onasining qalbidan joy olding.",note:"وَقَعَ مَوْقِعًا فِي قَلْبِهِ — «qalbidan joy olmoq, ko‘ngliga o‘rnashmoq»."},
{num:323,time:"00:25:02,539 --> 00:25:05,539",arabic:"وَتُرِيدُكِ كَنَّةً لَهَا",segs:["وَتُرِيدُكِ كَنَّةً لَهَا"],full_uz:"U seni o‘ziga kelin qilmoqchi.",note:"كَنَّةٌ — «kelin», ya’ni o‘g‘lining xotini."},
{num:324,time:"00:25:05,539 --> 00:25:07,980",arabic:"مَاذَا؟",segs:null,full_uz:"Nima?",note:null},
{num:325,time:"00:25:07,980 --> 00:25:09,980",arabic:"تُرِيدُكِ كَكَنَّةٍ لَهَا؟",segs:null,full_uz:"Seni o‘ziga kelin qilmoqchimi?",note:null},
{num:326,time:"00:25:11,980 --> 00:25:14,980",arabic:"وَمَنْ قَالَ لَهَا إِنَّنِي أُرِيدُ الزَّوَاجَ؟",segs:["وَمَنْ قَالَ لَهَا","إِنَّنِي أُرِيدُ الزَّوَاجَ؟"],full_uz:"Unga men turmush qurishni xohlashimni kim aytibdi?",note:null},
{num:327,time:"00:25:14,980 --> 00:25:17,980",arabic:"لَمْ يَقُلْ لَهَا أَحَدٌ شَيْئًا",segs:null,full_uz:"Unga hech kim hech narsa aytmagan.",note:null},
{num:328,time:"00:25:17,980 --> 00:25:21,980",arabic:"لَقَدْ أُعْجِبَتْ بِكِ وَتُرِيدُكِ زَوْجَةً لِابْنِهَا",segs:["لَقَدْ أُعْجِبَتْ بِكِ","وَتُرِيدُكِ زَوْجَةً لِابْنِهَا"],full_uz:"U sening ko‘ngliga yoqqansan va seni o‘g‘liga xotin qilmoqchi.",note:"أُعْجِبَ بِـ — «ma’qul kelmoq, yoqmoq»."},
{num:329,time:"00:25:21,980 --> 00:25:25,980",arabic:"لَا، لَا أُرِيدُ الزَّوَاجَ",segs:["لَا، لَا أُرِيدُ الزَّوَاجَ"],full_uz:"Yo‘q, turmush qurishni istamayman.",note:null},
{num:330,time:"00:25:25,980 --> 00:25:26,980",arabic:"وَلِمَاذَا؟",segs:null,full_uz:"Nega?",note:null},
{num:331,time:"00:25:27,980 --> 00:25:31,980",arabic:"إِنْ كُنْتِ هُنَا أَوْ عِنْدَ أَهْلِكِ فَقَدَرُكِ إِلَى بَيْتِ زَوْجِكِ",segs:["إِنْ كُنْتِ هُنَا أَوْ عِنْدَ أَهْلِكِ","فَقَدَرُكِ إِلَى بَيْتِ زَوْجِكِ"],full_uz:"Bu yerda bo‘lsang ham yoki oilangnikida bo‘lsang ham, taqdiring eringning uyiga borishdir.",note:"قَدَرُكِ — «taqdiring, nasibang»."},
{num:332,time:"00:25:31,980 --> 00:25:35,980",arabic:"بَلْ قَدَرِي أَنْ أَعُودَ أَوَّلًا إِلَى أَهْلِي",segs:["بَلْ قَدَرِي","أَنْ أَعُودَ أَوَّلًا إِلَى أَهْلِي"],full_uz:"Yo‘q, mening taqdirim avvalo oilamnikiga qaytishdir.",note:"أَوَّلًا — «avvalo, birinchi navbatda»."},
{num:333,time:"00:25:37,980 --> 00:25:44,980",arabic:"يَا شَهْنَازُ، أَنَا لَنْ أَجْبِرَكِ عَلَى فِعْلِ مَا تَكْرَهِينَ، وَلَكِنْ فَكِّرِي بِالْأَمْرِ جَيِّدًا",segs:["يَا شَهْنَازُ","أَنَا لَنْ أَجْبِرَكِ عَلَى فِعْلِ مَا تَكْرَهِينَ","وَلَكِنْ فَكِّرِي بِالْأَمْرِ جَيِّدًا"],full_uz:"Ey Shahnoz, men seni o‘zing yomon ko‘rgan ishni qilishga majburlamayman, lekin bu masalani yaxshilab o‘ylab ko‘r.",note:"أَجْبَرَهُ عَلَى — «uni biror ishga majburlamoq»."},
{num:334,time:"00:25:59,980 --> 00:26:03,980",arabic:"مَهْمَا فَعَلْتِ، فَلَنْ أَبْرَحَ هَذَا الْمَكَانَ إِلَّا لِبَيْتِ أَهْلِي أَوْ إِلَى قَبْرِي",segs:["مَهْمَا فَعَلْتِ","فَلَنْ أَبْرَحَ هَذَا الْمَكَانَ","إِلَّا لِبَيْتِ أَهْلِي أَوْ إِلَى قَبْرِي"],full_uz:"Nima qilsang ham, men bu yerdan faqat oilamnikiga yoki qabrimga ketish uchun chiqaman.",note:"مَهْمَا فَعَلْتِ — «nima qilsang ham, qanday ish qilsang ham»; لَنْ أَبْرَحَ — «ketmayman, tark etmayman»."},
{num:335,time:"00:26:03,980 --> 00:26:05,980",arabic:"بَلْ إِلَى قَبْرِكِ أَيَّتُهَا الشَّقِيَّةُ",segs:["بَلْ إِلَى قَبْرِكِ","أَيَّتُهَا الشَّقِيَّةُ"],full_uz:"Balki to‘g‘ri qabringga ketarsan, ey badbaxt.",note:"الشَّقِيَّةُ — «baxtsiz, badbaxt, bechora»."},
{num:336,time:"00:26:07,980 --> 00:26:12,860",arabic:"لَا وَفَّقَنِيَ اللَّهُ",segs:null,full_uz:"Alloh meni muvaffaq qilmasin.",note:"وَفَّقَ اللَّهُ — «Alloh muvaffaq qilsin»; لَا وَفَّقَنِيَ اللَّهُ — «Alloh meni muvaffaq qilmasin» mazmunidagi ibora."},
{num:337,time:"00:26:12,860 --> 00:26:14,779",arabic:"لَا وَفَّقَنِيَ اللَّهُ",segs:null,full_uz:"Alloh meni muvaffaq qilmasin.",note:null},
{num:338,time:"00:26:14,779 --> 00:26:15,660",arabic:"خُذِي يَدِي",segs:null,full_uz:"Qo‘limdan ushla.",note:null},
{num:339,time:"00:26:15,660 --> 00:26:25,559",arabic:"أَنَا حُرَّةٌ",segs:null,full_uz:"Men ozodman.",note:"حُرَّةٌ — «ozod, hur ayol»."},
{num:340,time:"00:26:25,559 --> 00:26:26,940",arabic:"حُرَّةٌ",segs:null,full_uz:"Ozodman.",note:null},
{num:341,time:"00:26:26,940 --> 00:26:28,380",arabic:"حُرَّةٌ",segs:null,full_uz:"Ozodman.",note:null},
{num:342,time:"00:26:37,980 --> 00:26:53,440",arabic:"وَلَهْفُ قَلْبِي عَلَيْكِ يَا شَهْنَازُ",segs:["وَلَهْفُ قَلْبِي عَلَيْكِ","يَا شَهْنَازُ"],full_uz:"Ey Shahnoz, sen uchun yuragim achiydi.",note:"وَلَهْفُ قَلْبِي — «voy, yuragim achiydi, yuragim eziladi» ma’nosidagi iztirob ifodasi."},
{num:343,time:"00:26:53,440 --> 00:26:57,759",arabic:"أُقْسِمُ أَنَّنِي سَأَكُونُ عَوْنًا لَكِ لَا عَلَيْكِ",segs:["أُقْسِمُ أَنَّنِي سَأَكُونُ عَوْنًا لَكِ","لَا عَلَيْكِ"],full_uz:"Qasam ichaman, men senga qarshi emas, sening yordamching bo‘laman.",note:"عَوْنًا لَهُ — «unga yordamchi»; لَا عَلَيْهِ — «unga qarshi emas»."},
{num:344,time:"00:26:57,759 --> 00:27:01,120",arabic:"وَإِنْ لَمْ تَقْبَلِي بِمَرْوَانَ زَوْجًا",segs:null,full_uz:"Agar Marvonni er sifatida qabul qilmasang ham,",note:"قَبِلَ بِـ — «...ga rozi bo‘lmoq, qabul qilmoq»."},
{num:345,time:"00:27:01,120 --> 00:27:04,519",arabic:"فَلَنْ يُجْبِرَكِ أَحَدٌ عَلَى ذَلِكَ",segs:null,full_uz:"Hech kim seni bunga majburlamaydi.",note:null},
{num:346,time:"00:27:07,980 --> 00:27:13,819",arabic:"أَيُعْقَلُ أَنْ أَتَزَوَّجَ وَأَنَا بِمَنْأًى عَنْ أَهْلِي",segs:["أَيُعْقَلُ أَنْ أَتَزَوَّجَ","وَأَنَا بِمَنْأًى عَنْ أَهْلِي"],full_uz:"Oilamdan uzoqda bo‘lsam, turmush qurishimni tasavvur qilib bo‘ladimi?",note:"أَيُعْقَلُ — «aqldan sig‘adimi?, mantiqan mumkinmi?»; بِمَنْأًى عَنْ — «...dan uzoqda»."},
{num:347,time:"00:27:13,819 --> 00:27:18,240",arabic:"كَيْفَ يَكُونُ ذَلِكَ",segs:null,full_uz:"Bu qanday bo‘lishi mumkin?",note:null},
{num:348,time:"00:27:18,240 --> 00:27:24,519",arabic:"وَلَكِنْ مَا ذَنْبُ خَالَتِي أُمِّ خَالِدٍ وَابْنِهَا أَنْ تَتَحَمَّلَنِي كُلَّ هَذَا الْعُمْرِ",segs:["وَلَكِنْ مَا ذَنْبُ خَالَتِي أُمِّ خَالِدٍ وَابْنِهَا","أَنْ تَتَحَمَّلَنِي كُلَّ هَذَا الْعُمْرِ"],full_uz:"Lekin xolam Ummu Xolid va uning o‘g‘lining meni shuncha yil bo‘ynida ko‘tarib yurishida nima aybi bor?",note:"تَحَمَّلَهُ — «uni ko‘tarib yurmoq, zimmasiga olib yurmoq»."},
{num:349,time:"00:27:24,519 --> 00:27:29,259",arabic:"رُبَّمَا كُنْتُ عِبْئًا ثَقِيلًا عَلَيْهِمْ",segs:["رُبَّمَا كُنْتُ عِبْئًا ثَقِيلًا عَلَيْهِمْ"],full_uz:"Balki men ularga og‘ir yuk bo‘lgandirman.",note:"عِبْءٌ ثَقِيلٌ — «og‘ir yuk, og‘ir mas’uliyat»."},
{num:350,time:"00:27:31,579 --> 00:27:33,579",arabic:"لَقَدْ حِرْتُ فِي أَمْرِي",segs:null,full_uz:"Nima qilishni bilmay qoldim.",note:"حَارَ فِي أَمْرِهِ — «ishi borasida hayron-u sarosimaga tushmoq»."},
{num:351,time:"00:27:33,579 --> 00:27:36,700",arabic:"مَاذَا أَفْعَلُ يَا رَبِّ",segs:["مَاذَا أَفْعَلُ","يَا رَبِّ"],full_uz:"Nima qilay, ey Robbim?",note:null},
{num:352,time:"00:27:36,700 --> 00:27:57,340",arabic:"لَا حَوْلَ وَلَا قُوَّةَ إِلَّا بِاللَّهِ",segs:null,full_uz:"Allohdan o‘zga hech qanday kuch va quvvat yo‘q.",note:null},
{num:353,time:"00:28:06,700 --> 00:28:10,500",arabic:"هَذَا هُوَ الْفَضْلُ بْنُ سَهْلٍ يَا مَوْلَايَ",segs:["هَذَا هُوَ الْفَضْلُ بْنُ سَهْلٍ","يَا مَوْلَايَ"],full_uz:"Bu Fadl ibn Sahl, hazratim.",note:null},
{num:354,time:"00:28:10,500 --> 00:28:14,960",arabic:"اِقْتَرِبْ يَا فَضْلُ اِقْتَرِبْ وَحَيِّ أَمِيرَ الْمُؤْمِنِينَ",segs:["اِقْتَرِبْ يَا فَضْلُ","اِقْتَرِبْ","وَحَيِّ أَمِيرَ الْمُؤْمِنِينَ"],full_uz:"Yaqin kel, ey Fadl, yaqin kel va mo‘minlar amiriga salom ber.",note:"حَيَّا — «salomlashmoq, salom bermoq»."},
{num:355,time:"00:28:25,799 --> 00:28:29,539",arabic:"كُنْتُ قَدْ كَلَّمْتُكَ عَنْ نَبَاهَتِهِ وَذَكَائِهِ يَا مَوْلَايَ",segs:["كُنْتُ قَدْ كَلَّمْتُكَ عَنْ نَبَاهَتِهِ وَذَكَائِهِ","يَا مَوْلَايَ"],full_uz:"Men sizga uning ziyrakligi va aqlliligi haqida aytgan edim, hazratim.",note:"نَبَاهَةٌ — «ziyraklik, fahm-farosat»."},
{num:356,time:"00:28:29,539 --> 00:28:37,920",arabic:"فَهَذَا هُوَ الشَّابُّ الَّذِي أَوْكَلْتَ إِلَيْهِ تَرْجَمَةَ كِتَابٍ مِنَ الْفَارِسِيَّةِ إِلَى الْعَرَبِيَّةِ؟",segs:["فَهَذَا هُوَ الشَّابُّ","الَّذِي أَوْكَلْتَ إِلَيْهِ تَرْجَمَةَ كِتَابٍ مِنَ الْفَارِسِيَّةِ إِلَى الْعَرَبِيَّةِ؟"],full_uz:"Demak, fors tilidan arab tiliga kitob tarjima qilishni topshirganingiz shu yigitmi?",note:"أَوْكَلَ إِلَيْهِ — «unga topshirmoq, zimmasiga yuklamoq»."},
{num:357,time:"00:28:39,480 --> 00:28:40,819",arabic:"هُوَ بِعَيْنِهِ يَا مَوْلَايَ",segs:["هُوَ بِعَيْنِهِ","يَا مَوْلَايَ"],full_uz:"Aynan o‘sha, hazratim.",note:"بِعَيْنِهِ — «aynan o‘zi, xuddi o‘sha»."},
{num:358,time:"00:28:40,819 --> 00:28:43,920",arabic:"إِنَّهُ الْفَضْلُ بْنُ سَهْلٍ السَّرْخَسِيُّ",segs:null,full_uz:"U Fadl ibn Sahl as-Saraxsiy.",note:null},
{num:359,time:"00:28:43,920 --> 00:28:48,159",arabic:"لَابُدَّ أَيُّهَا الشَّابُّ أَنْ تَكُونَ عَلَى قَدْرٍ عَالٍ مِنَ الذَّكَاءِ",segs:["لَابُدَّ أَيُّهَا الشَّابُّ","أَنْ تَكُونَ عَلَى قَدْرٍ عَالٍ مِنَ الذَّكَاءِ"],full_uz:"Ey yigit, demak, sen nihoyatda aqlli bo‘lishing kerak.",note:"عَلَى قَدْرٍ عَالٍ مِنَ — «yuqori darajada ...ga ega»."},
{num:360,time:"00:28:48,159 --> 00:28:51,079",arabic:"حَتَّى يَقُولَ فِيكَ يَحْيَى كَلَامًا",segs:["حَتَّى يَقُولَ فِيكَ يَحْيَى كَلَامًا"],full_uz:"Yahyo sen haqingda shunday gaplarni aytganiga qaraganda,",note:"قَالَ فِيهِ — «u haqda gapirmoq»."},
{num:361,time:"00:28:51,079 --> 00:28:55,299",arabic:"يَتَمَنَّى أَمِيرُ الْمُؤْمِنِينَ أَنْ يُقَالَ فِيهِ فِي غَيْرِ حَضْرَتِهِ",segs:["يَتَمَنَّى أَمِيرُ الْمُؤْمِنِينَ","أَنْ يُقَالَ فِيهِ فِي غَيْرِ حَضْرَتِهِ"],full_uz:"Mo‘minlar amiri ham o‘zi yo‘q joyda u haqda shunday gaplar aytilishini istaydi.",note:"فِي غَيْرِ حَضْرَتِهِ — «uning huzurida bo‘lmagan paytda, yo‘qligida»."},
{num:362,time:"00:28:55,299 --> 00:28:57,460",arabic:"مَا السِّرُّ فِي ذَلِكَ أَيُّهَا الشَّابُّ؟",segs:["مَا السِّرُّ فِي ذَلِكَ","أَيُّهَا الشَّابُّ؟"],full_uz:"Buning siri nimada, ey yigit?",note:"السِّرُّ فِي ذَلِكَ — «buning siri, sababi»."},
{num:363,time:"00:29:15,039 --> 00:29:17,740",arabic:"أَهْلًا بُنَيَّتِي",segs:["أَهْلًا","بُنَيَّتِي"],full_uz:"Xush kelibsan, qizim.",note:null},
{num:364,time:"00:29:17,740 --> 00:29:19,779",arabic:"حَسِبْتُكِ تَأَخَّرْتِ فِي النَّوْمِ",segs:["حَسِبْتُكِ تَأَخَّرْتِ فِي النَّوْمِ"],full_uz:"Uyquda kechikib qolding deb o‘ylagandim.",note:null},
{num:365,time:"00:29:19,779 --> 00:29:27,799",arabic:"فَلَمْ أَشَأْ أَنْ أُزْعِجَكِ",segs:["فَلَمْ أَشَأْ","أَنْ أُزْعِجَكِ"],full_uz:"Shuning uchun seni bezovta qilishni istamadim.",note:"شَاءَ أَنْ — «... qilishni istamoq»."},
{num:366,time:"00:29:27,799 --> 00:29:28,779",arabic:"أُجِيبُكِ إِلَى مَا طَلَبْتِ يَا خَالَةُ",segs:["أُجِيبُكِ إِلَى مَا طَلَبْتِ","يَا خَالَةُ"],full_uz:"Siz so‘ragan narsaga roziman, xola.",note:"أَجَابَهُ إِلَى — «uning talabiga rozi bo‘lmoq, talabini bajarmoq»."},
{num:367,time:"00:29:28,779 --> 00:29:39,779",arabic:"مَاذَا؟",segs:null,full_uz:"Nima?",note:null},
{num:368,time:"00:29:39,779 --> 00:29:42,660",arabic:"قَدْ وَافَقْتُ عَلَى الزَّوَاجِ",segs:["قَدْ وَافَقْتُ عَلَى الزَّوَاجِ"],full_uz:"Men turmush qurishga rozilik berdim.",note:"وَافَقَ عَلَى — «rozi bo‘lmoq, ma’qullamoq»."},
{num:369,time:"00:29:42,660 --> 00:29:47,099",arabic:"مِمَّنْ أَرَادَنِي لَهُ زَوْجَةً يَا أُمَّ خَالِدٍ",segs:["مِمَّنْ أَرَادَنِي لَهُ زَوْجَةً","يَا أُمَّ خَالِدٍ"],full_uz:"Meni o‘zi uchun xotin qilishni istagan kishiga, ey Ummu Xolid.",note:"أَرَادَنِي لَهُ زَوْجَةً — «meni o‘zi uchun xotin qilishni istagan»."},
{num:370,time:"00:29:47,099 --> 00:29:53,159",arabic:"اِجْلِسِي يَا ابْنَتِي",segs:["اِجْلِسِي يَا ابْنَتِي"],full_uz:"O‘tir, qizim.",note:null},
{num:371,time:"00:29:53,159 --> 00:29:54,059",arabic:"اِجْلِسِي",segs:null,full_uz:"O‘tir.",note:null},
{num:372,time:"00:30:09,059 --> 00:30:11,339",arabic:"مَا بِكَ أَيُّهَا الشَّابُّ؟",segs:["مَا بِكَ","أَيُّهَا الشَّابُّ؟"],full_uz:"Senga nima bo‘ldi, ey yigit?",note:"مَا بِكَ؟ — «senga nima bo‘ldi?, nimang bor?»."},
{num:373,time:"00:30:11,339 --> 00:30:13,859",arabic:"هَلْ يَنْطِقُ لِسَانُكَ",segs:null,full_uz:"Til­ing gapiryaptimi?",note:null},
{num:374,time:"00:30:13,859 --> 00:30:16,779",arabic:"سَتَبْقَى وَاقِفًا وَاجِمًا",segs:null,full_uz:"Shunday qotib, jim turaverasanmi?",note:"وَاجِمٌ — «hayrat yoki qo‘rquvdan qotib, jim qolgan»."},
{num:375,time:"00:30:16,779 --> 00:30:18,779",arabic:"مَنْ أَبْكَى مِنْ هَكَذَا؟",segs:null,full_uz:"Bunday vaziyatda kim gapirmay qoladi?",note:null},
{num:376,time:"00:30:18,779 --> 00:30:20,779",arabic:"مَا بِكَ؟",segs:null,full_uz:"Senga nima bo‘ldi?",note:"مَا بِكَ؟ — «senga nima bo‘ldi?, nimang bor?»."},
{num:377,time:"00:30:24,779 --> 00:30:26,779",arabic:"يَا أَمِيرَ الْمُؤْمِنِينَ",segs:null,full_uz:"Ey mo‘minlar amiri.",note:null},
{num:378,time:"00:30:26,779 --> 00:30:28,779",arabic:"حَفِظَكَ اللَّهُ وَأَطَالَ فِي عُمْرِكَ",segs:["حَفِظَكَ اللَّهُ","وَأَطَالَ فِي عُمْرِكَ"],full_uz:"Alloh sizni asrasin va umringizni uzoq qilsin.",note:null},
{num:379,time:"00:30:30,779 --> 00:30:32,779",arabic:"إِنَّمَا قَيَّدَ لِسَانِي هَيْبَتُكَ",segs:["إِنَّمَا قَيَّدَ لِسَانِي","هَيْبَتُكَ"],full_uz:"Tilimni bog‘lab qo‘ygan narsa faqat sizning haybatingizdir.",note:"قَيَّدَ اللِّسَانَ — «tilini bog‘lamoq, gapira olmay qoldirmoq»; هَيْبَةٌ — «haybat, ulug‘vorlikdan tug‘ilgan qo‘rquv»."},
{num:380,time:"00:30:32,779 --> 00:30:36,779",arabic:"وَإِنَّ أَعْدَلَ الشَّوَاهِدِ عَلَى فَرَاهَةِ الْمَمْلُوكِ",segs:["وَإِنَّ أَعْدَلَ الشَّوَاهِدِ","عَلَى فَرَاهَةِ الْمَمْلُوكِ"],full_uz:"Qulning aqlliligi va fahm-farosatining eng yaqqol belgisi...",note:"فَرَاهَةٌ — «zakovat, fahm-farosat, yaxshi idrok» ma’nosida."},
{num:381,time:"00:30:36,779 --> 00:30:38,779",arabic:"أَنْ تَمْلِكَ قَلْبَهُ",segs:null,full_uz:"uning qalbini egallaydigan narsa...",note:"مَلَكَ الْقَلْبَ — «qalbni egallamoq»."},
{num:382,time:"00:30:38,779 --> 00:30:40,779",arabic:"هَيْبَةُ سَيِّدِهِ",segs:null,full_uz:"xo‘jayinining haybatidir.",note:"سَيِّدٌ — «xo‘jayin, boshliq, ulug‘ kishi»."},
{num:383,time:"00:30:40,779 --> 00:30:45,019",arabic:"أَحْسَنْتَ",segs:null,full_uz:"Barakalla.",note:null},
{num:384,time:"00:30:45,019 --> 00:30:48,079",arabic:"إِنَّهُ وَاللَّهِ كَلَامٌ جَمِيلٌ",segs:["إِنَّهُ وَاللَّهِ","كَلَامٌ جَمِيلٌ"],full_uz:"Allohga qasam, bu juda chiroyli gap.",note:"وَاللَّهِ — «Allohga qasam»."},
{num:385,time:"00:30:48,079 --> 00:30:52,339",arabic:"إِنْ كُنْتَ قَدْ سَكَتَّ لِتَصُوغَ هَذَا الْكَلَامَ",segs:["إِنْ كُنْتَ قَدْ سَكَتَّ","لِتَصُوغَ هَذَا الْكَلَامَ"],full_uz:"Agar bu gaplarni tuzish uchun jim turgan bo‘lsang,",note:"صَاغَ الْكَلَامَ — «gapni chiroyli tuzmoq, ifodalamoq»."},
{num:386,time:"00:30:52,339 --> 00:30:55,039",arabic:"فَهُوَ جَمِيلٌ",segs:null,full_uz:"unda u chiroyli ekan.",note:null},
{num:387,time:"00:30:55,039 --> 00:31:00,859",arabic:"وَإِنْ كَانَتْ بَدَاهَتُكَ قَدْ أَسْعَفَتْكَ",segs:["وَإِنْ كَانَتْ بَدَاهَتُكَ","قَدْ أَسْعَفَتْكَ"],full_uz:"Agar buni hozirjavobliging bilan shu zahoti topgan bo‘lsang,",note:"بَدَاهَةٌ — «hozirjavoblik, tez fahmlash»; أَسْعَفَهُ — «unga yordam bermoq, qiyin vaziyatda qo‘l kelmoq»."},
{num:388,time:"00:31:00,859 --> 00:31:03,720",arabic:"فَذَلِكَ أَحْسَنُ وَأَحْسَنُ",segs:null,full_uz:"undan ham yaxshiroq, juda ham yaxshi.",note:null},
{num:389,time:"00:31:10,779 --> 00:31:12,779",arabic:"شَهْنَازُ يَا ابْنَتِي",segs:["شَهْنَازُ","يَا ابْنَتِي"],full_uz:"Shahnoz, qizim.",note:null},
{num:390,time:"00:31:13,779 --> 00:31:17,779",arabic:"قَرَارُ الزَّوَاجِ لَيْسَ سَهْلًا حَتَّى تَقْبَلِيهِ بِهَذِهِ السُّرْعَةِ",segs:["قَرَارُ الزَّوَاجِ لَيْسَ سَهْلًا","حَتَّى تَقْبَلِيهِ بِهَذِهِ السُّرْعَةِ"],full_uz:"Turmush qurish qarori oson emas, uni bunchalik tez qabul qilishing shart emas.",note:"بِهَذِهِ السُّرْعَةِ — «bunchalik tez, shoshilinch ravishda»."},
{num:391,time:"00:31:18,779 --> 00:31:20,779",arabic:"إِنَّهُ مَصِيرُكِ",segs:null,full_uz:"Bu sening taqdiring.",note:"مَصِيرٌ — «taqdir, oxir-oqibat boriladigan holat»."},
{num:392,time:"00:31:21,779 --> 00:31:25,779",arabic:"لَا تَقْبَلِيهِ دُونَ قَنَاعَةٍ لِأَنِّي طَلَبْتُ مِنْكِ ذَلِكَ",segs:["لَا تَقْبَلِيهِ دُونَ قَنَاعَةٍ","لِأَنِّي طَلَبْتُ مِنْكِ ذَلِكَ"],full_uz:"Men shuni so‘raganim uchungina bunga ko‘nib ketma, avval ko‘ngling to‘lsin.",note:"قَنَاعَةٌ — «ichki qanoat, ishonch, ko‘ngil to‘lishi»."},
{num:393,time:"00:31:33,779 --> 00:31:37,779",arabic:"مَا نَصَحْتُكِ بِمَرْوَانَ إِلَّا لِأَنَّهُ فَتًى أَمِينٌ",segs:["مَا نَصَحْتُكِ بِمَرْوَانَ إِلَّا","لِأَنَّهُ فَتًى أَمِينٌ"],full_uz:"Men senga Marvonni faqat u ishonchli yigit bo‘lgani uchun tavsiya qildim.",note:"نَصَحَ لَهُ بِـ — «unga ...ni tavsiya qilmoq»."},
{num:394,time:"00:31:37,779 --> 00:31:39,779",arabic:"يَسْتَحِقُّ أَنْ يَكُونَ زَوْجًا لَكِ",segs:null,full_uz:"U senga er bo‘lishga loyiq.",note:"اِسْتَحَقَّ — «loyiq bo‘lmoq, haqli bo‘lmoq»."},
{num:395,time:"00:31:39,779 --> 00:31:46,399",arabic:"إِنَّمَا بُثِّي وَحُزْنِي",segs:null,full_uz:"Mening butun dardim va g‘amim...",note:"بَثٌّ — «ichdagi dard, iztirob» ma’nosida."},
{num:396,time:"00:31:46,399 --> 00:31:52,940",arabic:"لِفَقْدِ أَهْلِي فِي وَقْتٍ أَكُونُ فِيهِ بِأَشَدِّ الْحَاجَةِ لَهُمْ مِنْ أَيِّ وَقْتٍ مَضَى",segs:["لِفَقْدِ أَهْلِي","فِي وَقْتٍ أَكُونُ فِيهِ بِأَشَدِّ الْحَاجَةِ لَهُمْ","مِنْ أَيِّ وَقْتٍ مَضَى"],full_uz:"Oilamdan ayrilganimdadir, ayniqsa hozir ularga har qachongidan ham ko‘proq muhtoj bo‘lgan paytimda.",note:"فَقْدُ الْأَهْلِ — «oila yaqinlaridan ayrilish»."},
{num:397,time:"00:31:52,940 --> 00:31:54,399",arabic:"وَنَحْنُ أَهْلُكِ",segs:null,full_uz:"Biz esa sening oilangmiz.",note:null},
{num:398,time:"00:31:54,399 --> 00:31:57,379",arabic:"أَنَا أُمُّكِ يَا شَهْنَازُ",segs:["أَنَا أُمُّكِ","يَا شَهْنَازُ"],full_uz:"Men sening onangman, ey Shahnoz.",note:null},
{num:399,time:"00:31:57,379 --> 00:32:01,779",arabic:"فَهَلْ تَرْضَى أُمُّكِ أُمُّ خَالِدٍ بِغَيْرِ الْخَيْرِ لَكِ؟",segs:["فَهَلْ تَرْضَى أُمُّكِ أُمُّ خَالِدٍ","بِغَيْرِ الْخَيْرِ لَكِ؟"],full_uz:"Axir onang Ummu Xolid sen uchun yaxshilikdan boshqa narsani istarmidi?",note:"تَرْضَى لَهُ بِـ — «uning uchun ...ni ma’qullamoq, istamoq»."},
{num:400,time:"00:32:01,779 --> 00:32:07,460",arabic:"بُنَيَّتِي",segs:null,full_uz:"Qizim.",note:null},
{num:401,time:"00:32:07,460 --> 00:32:27,019",arabic:"شَهْنَازُ وَافَقَتْ",segs:null,full_uz:"Shahnoz rozi bo‘libdi.",note:null},
{num:402,time:"00:32:27,019 --> 00:32:30,220",arabic:"وَافَقَتْ عَلَى الزَّوَاجِ مِنِّي",segs:null,full_uz:"U menga turmushga chiqishga rozi bo‘ldi.",note:"وَافَقَ عَلَى — «rozi bo‘lmoq»."},
{num:403,time:"00:32:30,220 --> 00:32:31,480",arabic:"وَغَدًا إِنْ شَاءَ اللَّهُ",segs:["وَغَدًا","إِنْ شَاءَ اللَّهُ"],full_uz:"Ertaga, inshaalloh.",note:null},
{num:404,time:"00:32:31,480 --> 00:32:36,440",arabic:"سَنَذْهَبُ إِلَى السُّوقِ لِنَشْتَرِيَ مَا يَلْزَمُ اسْتِعْدَادًا لِلْعُرْسِ",segs:["سَنَذْهَبُ إِلَى السُّوقِ","لِنَشْتَرِيَ مَا يَلْزَمُ","اسْتِعْدَادًا لِلْعُرْسِ"],full_uz:"Ertaga bozorga borib, to‘yga kerak bo‘ladigan narsalarni xarid qilamiz.",note:"اسْتِعْدَادًا لِلْعُرْسِ — «to‘yga tayyorgarlik uchun»."},
{num:405,time:"00:32:36,440 --> 00:32:41,000",arabic:"بَشَّرَكَ اللَّهُ بِالْخَيْرِ يَا أُمَّاهُ",segs:["بَشَّرَكَ اللَّهُ بِالْخَيْرِ","يَا أُمَّاهُ"],full_uz:"Alloh sizga xushxabarlar bersin, onajon.",note:"بَشَّرَهُ بِالْخَيْرِ — «unga yaxshilik xushxabarini bermoq»."},
{num:406,time:"00:32:41,000 --> 00:32:41,920",arabic:"الْحَمْدُ لِلَّهِ",segs:null,full_uz:"Alhamdulillah.",note:null},
{num:407,time:"00:32:41,920 --> 00:32:44,380",arabic:"مَا بِكَ أَيُّهَا الْفَتَى",segs:["مَا بِكَ","أَيُّهَا الْفَتَى"],full_uz:"Senga nima bo‘ldi, ey yigit?",note:null},
{num:408,time:"00:32:44,380 --> 00:32:47,900",arabic:"أَطَارَ عَقْلَكَ مَنْ يَرَى فَرْحَتَكَ وَسُرُورَكَ",segs:["أَطَارَ عَقْلَكَ","مَنْ يَرَى فَرْحَتَكَ وَسُرُورَكَ"],full_uz:"Seni ko‘rgan odam quvonchingdan aqling uchib ketgan deb o‘ylaydi.",note:"أَطَارَ عَقْلَهُ — «aqlini uchirib yubormoq», ya’ni haddan tashqari hayajonga tushmoq."},
{num:409,time:"00:32:47,900 --> 00:32:51,500",arabic:"فَسَيَقُولُ إِنَّكَ تَعْرِفُهَا مُنْذُ أَمَدٍ بَعِيدٍ",segs:["فَسَيَقُولُ","إِنَّكَ تَعْرِفُهَا مُنْذُ أَمَدٍ بَعِيدٍ"],full_uz:"Shuning uchun odamlar uni anchadan beri tanirsan, deb o‘ylashi mumkin.",note:"مُنْذُ أَمَدٍ بَعِيدٍ — «anchadan beri»."},
{num:410,time:"00:32:51,500 --> 00:32:52,759",arabic:"عَجَبًا لَكَ",segs:null,full_uz:"Senga qoyil.",note:"عَجَبًا لَكَ — hayrat yoki ajablanishni bildiradi."},
{num:411,time:"00:32:52,759 --> 00:32:55,880",arabic:"الْحُبُّ عَلَى نَفْسِ سُلْطَانٌ يَا أُمَّهُ",segs:["الْحُبُّ عَلَى نَفْسِ سُلْطَانٌ","يَا أُمَّهُ"],full_uz:"Muhabbat inson qalbiga hukmronlik qiladi, onajon.",note:"سُلْطَانٌ عَلَى النَّفْسِ — «nafs/ko‘ngil ustidan hukmronlik»."},
{num:412,time:"00:32:55,880 --> 00:33:00,460",arabic:"وَمَا تَسْتَوْلِي عَلَى الْمَرْءِ غَيْبَ عَقْلِهِ وَأَمَاتَ فِي قَلْبِهِ كُلَّ إِحْسَاسٍ إِلَّا بِهَا",segs:["وَمَا تَسْتَوْلِي عَلَى الْمَرْءِ","غَيْبَ عَقْلِهِ","وَأَمَاتَ فِي قَلْبِهِ كُلَّ إِحْسَاسٍ إِلَّا بِهَا"],full_uz:"Insonni o‘ziga shu qadar rom etadiki, aqlini yo‘qotib, qalbidagi boshqa barcha hislarni so‘ndiradi.",note:"اِسْتَوْلَى عَلَيْهِ — «ustidan to‘liq hukmron bo‘lmoq»."},
{num:413,time:"00:33:00,460 --> 00:33:04,220",arabic:"وَشَهْنَازُ هِيَ الَّتِي غَيَّبَتْ بِجَمَالِهَا عَقْلَكَ",segs:["وَشَهْنَازُ هِيَ الَّتِي","غَيَّبَتْ بِجَمَالِهَا عَقْلَكَ"],full_uz:"Sening aqlingni go‘zalligi bilan yo‘qotishga sabab bo‘lgan esa Shahnoz.",note:"غَيَّبَ عَقْلَهُ — «aqlini olib qo‘ymoq, aqlini karaxt qilmoq»."},
{num:414,time:"00:33:04,220 --> 00:33:06,759",arabic:"وَخَامَرَتْ بِبَهَائِهَا رُوحَكَ",segs:null,full_uz:"Va uning husni ruhingni ham chulg‘ab oldi.",note:"خَامَرَ الشَّيْءُ النَّفْسَ — «biror narsa ruhni/qalbni chulg‘ab olmoq»."},
{num:415,time:"00:33:06,759 --> 00:33:09,420",arabic:"أَجَلْ يَا أُمَّهُ إِنَّهَا فَوْقَ ذَلِكَ",segs:["أَجَلْ يَا أُمَّهُ","إِنَّهَا فَوْقَ ذَلِكَ"],full_uz:"Ha, onajon, u bundan ham ortiq.",note:null},
{num:416,time:"00:33:09,420 --> 00:33:11,360",arabic:"أَلَا تَسْتَحِقُّ؟",segs:null,full_uz:"U bunga loyiq emasmi?",note:null},
{num:417,time:"00:33:11,360 --> 00:33:13,400",arabic:"بَلَى بَلَى يَا مَرْوَانُ",segs:["بَلَى بَلَى","يَا مَرْوَانُ"],full_uz:"Albatta, albatta, ey Marvon.",note:"بَلَى — inkor savoliga ijobiy javob: «albatta, ha»."},
{num:418,time:"00:33:13,400 --> 00:33:15,740",arabic:"مَا عَلِمْتُ عَلَيْهَا مِنْ سُوءٍ",segs:null,full_uz:"Unda biror yomonlik ko‘rganim yo‘q.",note:"مَا عَلِمْتُ عَلَيْهَا مِنْ سُوءٍ — «unda hech qanday yomonlik bilmayman»."},
{num:419,time:"00:33:15,740 --> 00:33:18,740",arabic:"فَقَدْ حَازَتْ كُلَّ مَنَاقِبِ الْأَصَالَةِ وَالطُّهْرِ",segs:["فَقَدْ حَازَتْ كُلَّ مَنَاقِبِ الْأَصَالَةِ وَالطُّهْرِ"],full_uz:"U nasl-nasabi ulug‘lik va poklikning barcha fazilatlarini o‘zida jamlagan.",note:"مَنَاقِبُ — «fazilatlar, yaxshi xislatlar»; الْأَصَالَةُ — «aslzodalik, naslning ulug‘ligi»; الطُّهْرُ — «poklik»."},
{num:420,time:"00:33:18,740 --> 00:33:20,380",arabic:"فَنِعْمَ الْفَتَاةُ هِيَ يَا بُنَيَّ",segs:["فَنِعْمَ الْفَتَاةُ هِيَ","يَا بُنَيَّ"],full_uz:"U juda yaxshi qiz, bolam.",note:"نِعْمَ الْفَتَاةُ — «qanday yaxshi qiz!»."},
{num:421,time:"00:33:20,380 --> 00:33:22,600",arabic:"أَسْعَدَكَ اللَّهُ بِهَا أَسْعَدَكَ اللَّهُ",segs:["أَسْعَدَكَ اللَّهُ بِهَا","أَسْعَدَكَ اللَّهُ"],full_uz:"Alloh u bilan seni baxtli qilsin, Alloh seni baxtli qilsin.",note:"أَسْعَدَهُ اللَّهُ — «Alloh uni baxtli qilsin»."},
{num:422,time:"00:33:22,600 --> 00:33:25,500",arabic:"وَكُنْ لَهَا كَمَا تُرِيدُ أَنْ تَكُونَ لَكَ",segs:["وَكُنْ لَهَا","كَمَا تُرِيدُ أَنْ تَكُونَ لَكَ"],full_uz:"Sen undan qanday munosabat kutayotgan bo‘lsang, unga ham shunday bo‘l.",note:"كُنْ لَهَا — «unga yaxshi er bo‘l, unga munosib munosabatda bo‘l»."},
{num:423,time:"00:33:25,500 --> 00:33:27,720",arabic:"سَأَبْذُلُ مَا فِي وُسْعِي",segs:null,full_uz:"Qo‘limdan kelgan barcha ishni qilaman.",note:"بَذَلَ مَا فِي وُسْعِهِ — «qo‘lidan kelganini qilmoq»."},
{num:424,time:"00:33:27,720 --> 00:33:29,559",arabic:"كَيْ أُعَوِّضَهَا عَنْ فَقْدِ أَهْلِهَا",segs:["كَيْ أُعَوِّضَهَا","عَنْ فَقْدِ أَهْلِهَا"],full_uz:"Uni oilasidan ayrilganining o‘rnini qoplash uchun.",note:"عَوَّضَهُ عَنْ — «yo‘qotgan narsasining o‘rnini qoplamoq»."},
{num:425,time:"00:33:29,559 --> 00:33:31,899",arabic:"أَجَلْ يَا مَرْوَانُ أَجَلْ يَا بُنَيَّ",segs:["أَجَلْ يَا مَرْوَانُ","أَجَلْ يَا بُنَيَّ"],full_uz:"Ha, Marvon, ha, bolam.",note:null},
{num:426,time:"00:33:31,899 --> 00:33:34,799",arabic:"فَفَقْدُ الْبِنْتِ لِأَهْلِهَا كَسَرَ قَلْبَهَا",segs:["فَفَقْدُ الْبِنْتِ لِأَهْلِهَا","كَسَرَ قَلْبَهَا"],full_uz:"Qizning oilasidan ayrilishi uning qalbini sindirdi.",note:"كَسَرَ قَلْبَهُ — «qalbini sindirmoq, qattiq ranjitmoq»."},
{num:427,time:"00:33:34,799 --> 00:33:38,720",arabic:"لَعَلَّ اللَّهَ أَرَادَ بِكُمَا خَيْرًا إِذْ جَمَعَكُمَا",segs:["لَعَلَّ اللَّهَ أَرَادَ بِكُمَا خَيْرًا","إِذْ جَمَعَكُمَا"],full_uz:"Balki Alloh siz ikkalangizni birlashtirib, sizlar uchun yaxshilikni iroda qilgandir.",note:"أَرَادَ بِهِ خَيْرًا — «unga yaxshilikni iroda qilmoq»."},
{num:428,time:"00:33:38,720 --> 00:33:41,119",arabic:"فَكُنْ عِوَضَهَا لِأَهْلِهَا يَا بُنَيَّ",segs:["فَكُنْ عِوَضَهَا لِأَهْلِهَا","يَا بُنَيَّ"],full_uz:"Shunday ekan, sen uning oilasi o‘rnini bosadigan inson bo‘l, bolam.",note:"عِوَضٌ — «o‘rnini bosuvchi, yo‘qotilgan narsaning o‘rnini to‘ldiruvchi»."},
{num:429,time:"00:33:41,119 --> 00:33:45,460",arabic:"وَعْدًا عَلَيَّ يَا أُمَّ مَرْوَانَ وَعْدًا عَلَيَّ",segs:["وَعْدًا عَلَيَّ يَا أُمَّ مَرْوَانَ","وَعْدًا عَلَيَّ"],full_uz:"Va’da beraman, ey Ummu Marvon, va’da beraman.",note:"وَعْدًا عَلَيَّ — «bu mening zim-mamdagi va’da»."},
{num:430,time:"00:33:55,460 --> 00:33:59,440",arabic:"مَا بِكَ يَا صُهَيْبُ أَرَاكَ عَلَى غَيْرِ عَادَتِكَ",segs:["مَا بِكَ يَا صُهَيْبُ","أَرَاكَ عَلَى غَيْرِ عَادَتِكَ"],full_uz:"Senga nima bo‘ldi, ey Suhayb? Seni odatdagidan boshqacha ko‘ryapman.",note:"عَلَى غَيْرِ عَادَتِهِ — «odatdagidek emas, g‘ayrioddiy holatda»."},
{num:431,time:"00:33:59,440 --> 00:34:04,820",arabic:"كَيْفَ أَكُونُ عَلَى عَادَتِي وَابْنُ حَنْبَلٍ يَقِفُ عَثْرَةً فِي طَرِيقِي",segs:["كَيْفَ أَكُونُ عَلَى عَادَتِي","وَابْنُ حَنْبَلٍ يَقِفُ عَثْرَةً فِي طَرِيقِي"],full_uz:"Qanday qilib odatdagidek bo‘lay, Ibn Hanbal yo‘limda to‘siq bo‘lib turgan bo‘lsa?",note:"عَثْرَةٌ فِي الطَّرِيقِ — «yo‘ldagi to‘siq, g‘ov»."},
{num:432,time:"00:34:04,820 --> 00:34:10,599",arabic:"إِنَّهُ يَجْثُمُ عَلَى صَدْرِي يَحْطِمُ ضُلُوعِي",segs:["إِنَّهُ يَجْثُمُ عَلَى صَدْرِي","يَحْطِمُ ضُلُوعِي"],full_uz:"U ko‘ksimga og‘ir yukdek bosilib, qovurg‘alarimni sindirayotgandek.",note:"يَجْثُمُ عَلَى صَدْرِهِ — «ko‘ksiga og‘ir bosim bilan tushmoq»."},
{num:433,time:"00:34:10,599 --> 00:34:15,059",arabic:"وَإِنْ أَعْجَزَنِي تَكْسِيرُ رَأْسِهِ فِي الْعِلْمِ وَالتَّفَوُّقِ",segs:["وَإِنْ أَعْجَزَنِي تَكْسِيرُ رَأْسِهِ فِي الْعِلْمِ وَالتَّفَوُّقِ"],full_uz:"Ilm va ustunlikda uni mag‘lub etish qo‘limdan kelmasa ham,",note:"أَعْجَزَهُ — «uni ojiz qoldirmoq, qo‘lidan kelmaslik»."},
{num:434,time:"00:34:15,059 --> 00:34:18,500",arabic:"فَلَنْ يُعْجِزَنِي حَقِيقَةً",segs:null,full_uz:"aslida meni boshqa yo‘l bilan ojiz qoldirmaydi.",note:"حَقِيقَةً — «aslida, haqiqatda»."},
{num:435,time:"00:34:18,500 --> 00:34:21,480",arabic:"مَاذَا تَقْصِدُ يَا سَعِيدُ؟",segs:["مَاذَا تَقْصِدُ","يَا سَعِيدُ؟"],full_uz:"Nimani nazarda tutyapsan, ey Sa’id?",note:"مَاذَا تَقْصِدُ؟ — «nimani nazarda tutyapsan?»."},
{num:436,time:"00:34:21,480 --> 00:34:25,139",arabic:"سَأُلَقِّنُ ابْنَ حَنْبَلٍ دَرْسًا لَنْ يَسْتَطِيعَ بَعْدَهُ التَّطَلُّعَ إِلَيَّ",segs:["سَأُلَقِّنُ ابْنَ حَنْبَلٍ دَرْسًا","لَنْ يَسْتَطِيعَ بَعْدَهُ التَّطَلُّعَ إِلَيَّ"],full_uz:"Ibn Hanbalga shunday bir saboq beramanki, undan keyin u menga mag‘rurona qaray olmaydi.",note:"لَقَّنَهُ دَرْسًا — «unga saboq bermoq»; التَّطَلُّعُ إِلَيْهِ — «unga yuqoridan qaramoq, mag‘rurona nazar tashlamoq»."},
{num:437,time:"00:34:25,139 --> 00:34:28,280",arabic:"إِلَّا كَسِيرَ النَّظَرِ وَالرَّأْسِ",segs:null,full_uz:"Faqat nigohi va boshi egilgan holda.",note:"كَسِيرُ النَّظَرِ — «ko‘zi singan, umidsiz nigohli»; كَسِيرُ الرَّأْسِ — «bosh egilgan, mag‘lub»."},
{num:438,time:"00:34:28,280 --> 00:34:41,460",arabic:"لَنْ تُقْدِمَ عَلَى عَمَلٍ أَخْرَقَكَ هَذَا",segs:["لَنْ تُقْدِمَ عَلَى عَمَلٍ","أَخْرَقَكَ هَذَا"],full_uz:"Bunday ahmoqona ishga qo‘l urmay qo‘ya qol.",note:"أَقْدَمَ عَلَى — «biror ishga qo‘l urmoq, kirishmoq»; أَخْرَقُ — «ahmoqona, nodonlarcha»."},
{num:439,time:"00:34:41,460 --> 00:34:44,580",arabic:"بَلْ أَنَا أَخْرَقُ إِنْ لَمْ أَفْعَلْ ذَلِكَ",segs:["بَلْ أَنَا أَخْرَقُ","إِنْ لَمْ أَفْعَلْ ذَلِكَ"],full_uz:"Aksincha, agar buni qilmasam, ahmoq men bo‘laman.",note:null},
{num:440,time:"00:34:44,580 --> 00:34:46,760",arabic:"أَنْتُمَا مَعِي أَمْ لَا؟",segs:["أَنْتُمَا مَعِي","أَمْ لَا؟"],full_uz:"Ikkovingiz men bilanmisiz yoki yo‘qmi?",note:"مَعِي — «men tomonda, men bilan»."},
{num:441,time:"00:34:46,760 --> 00:34:48,100",arabic:"مَعَكَ فِي مَاذَا؟",segs:null,full_uz:"Nimaga sen bilan?",note:null},
{num:442,time:"00:34:48,100 --> 00:34:50,220",arabic:"تَتَجَنَّى عَلَى فَتًى لَمْ يَقْتَرِبْ مِنْكَ",segs:["تَتَجَنَّى عَلَى فَتًى","لَمْ يَقْتَرِبْ مِنْكَ"],full_uz:"Senga hech qanday yomonlik qilmagan bir yigitga nohaq hujum qilyapsan.",note:"تَجَنَّى عَلَى — «nohaq zulm qilmoq, birovga asossiz tajovuz qilmoq»."},
{num:443,time:"00:34:50,220 --> 00:34:53,480",arabic:"وَتُرِيدُ مِنَّا أَنْ نُسَاعِدَكَ فِي جِنَايَتِكَ وَحَمَاقَتِكَ",segs:["وَتُرِيدُ مِنَّا أَنْ نُسَاعِدَكَ","فِي جِنَايَتِكَ وَحَمَاقَتِكَ"],full_uz:"Yana bizdan jinoyating va ahmoqligingda senga yordam berishimizni xohlaysan.",note:"جِنَايَةٌ — «jinoyat, og‘ir yomonlik»; حَمَاقَةٌ — «ahmoqlik»."},
{num:444,time:"00:34:53,480 --> 00:34:56,680",arabic:"بِئْسَ الصَّدِيقُ أَنْتَ يَا بَدْرُ",segs:["بِئْسَ الصَّدِيقُ أَنْتَ","يَا بَدْرُ"],full_uz:"Qanday yomon do‘stsan, ey Badr.",note:"بِئْسَ الصَّدِيقُ — «qanday yomon do‘st!»."},
{num:445,time:"00:34:56,679 --> 00:34:59,819",arabic:"أَلَسْنَا أَصْدِقَاءَ فِي السَّرَّاءِ وَالضَّرَّاءِ؟",segs:["أَلَسْنَا أَصْدِقَاءَ","فِي السَّرَّاءِ وَالضَّرَّاءِ؟"],full_uz:"Biz yaxshi-yomon kunlarda do‘st emasmizmi?",note:"السَّرَّاءُ وَالضَّرَّاءُ — «yaxshi va yomon holatlar, farog‘at va qiyinchilik»."},
{num:446,time:"00:34:59,819 --> 00:35:04,579",arabic:"بَلَى أَنَا صَدِيقُ صُهَيْبٍ الْعَاقِلِ الْمُنْصِفِ الَّذِي لَا أَتَخَلَّى عَنْهُ وَقْتَ ضِيقِهِ",segs:["بَلَى أَنَا صَدِيقُ صُهَيْبٍ الْعَاقِلِ الْمُنْصِفِ","الَّذِي لَا أَتَخَلَّى عَنْهُ وَقْتَ ضِيقِهِ"],full_uz:"Albatta. Men aql-idrokli va adolatli Suhaybning do‘stiman, qiyin paytida undan yuz o‘girmayman.",note:"أَلَا أَتَخَلَّى عَنْهُ — «undan voz kechmaslik, tashlab qo‘ymaslik»; وَقْتَ ضِيقِهِ — «qiyin paytida»."},
{num:447,time:"00:35:04,579 --> 00:35:11,519",arabic:"وَلَكِنَّنِي لَسْتُ صَدِيقَ صُهَيْبٍ الطَّائِشِ الَّذِي تَحْمِلُهُ الْغَيْرَةُ عَلَى السَّفَاهَةِ",segs:["وَلَكِنَّنِي لَسْتُ صَدِيقَ صُهَيْبٍ الطَّائِشِ","الَّذِي تَحْمِلُهُ الْغَيْرَةُ عَلَى السَّفَاهَةِ"],full_uz:"Lekin men rashki uni nodonlikka yetaklaydigan o‘ylamay ish tutuvchi Suhaybning do‘sti emasman.",note:"تَحْمِلُهُ الْغَيْرَةُ عَلَى — «rashk uni biror ishga undamoq»; السَّفَاهَةُ — «nodonlik, ahmoqona xatti-harakat»."},
{num:448,time:"00:35:11,519 --> 00:35:15,019",arabic:"وَلَنْ أَنْصُرَكَ فِي ظُلْمِكَ أَبَدًا",segs:["وَلَنْ أَنْصُرَكَ فِي ظُلْمِكَ","أَبَدًا"],full_uz:"Zulmingda senga hech qachon yordam bermayman.",note:"أَنْصَرَهُ فِي — «biror ishda unga yordam bermoq»."},
{num:449,time:"00:35:15,019 --> 00:35:16,199",arabic:"أَنْتَ تَخْذُلُنِي إِذَنْ",segs:null,full_uz:"Demak, sen meni tashlab qo‘yasan.",note:"خَذَلَهُ — «uni qo‘llamaslik, tashlab qo‘ymoq»."},
{num:450,time:"00:35:16,199 --> 00:35:19,259",arabic:"فَلَأَنْصَحَنَّكَ أَلَّا تَتَمَادَى فِي غَيِّكَ وَضَلَالِكَ",segs:["فَلَأَنْصَحَنَّكَ","أَلَّا تَتَمَادَى فِي غَيِّكَ وَضَلَالِكَ"],full_uz:"Unda senga nasihat qilaman: o‘zboshimchaliging va adashishingda haddan oshib ketma.",note:"تَمَادَى فِي — «biror ishda haddan oshib davom etmoq»; غَيٌّ — «haq yo‘ldan og‘ish, adashish»."},
{num:451,time:"00:35:19,259 --> 00:35:24,039",arabic:"لِمُجَرَّدِ أَنَّ ظُنُونَكَ قَدْ زَيَّنَتْ لَكَ أَنَّ ابْنَ حَنْبَلٍ يَسْخَرُ مِنْكَ وَيَشْمَتُ بِكَ",segs:["لِمُجَرَّدِ أَنَّ ظُنُونَكَ قَدْ زَيَّنَتْ لَكَ","أَنَّ ابْنَ حَنْبَلٍ يَسْخَرُ مِنْكَ وَيَشْمَتُ بِكَ"],full_uz:"Faqat gumonlaring Ibn Hanbal seni masxara qiladi va kulfat­ingdan xursand bo‘ladi, deb senga shunday tasavvur bergani uchungina.",note:"شَمِتَ بِهِ — «birovning kulfatidan xursand bo‘lmoq»; زَيَّنَ لَهُ — «unga bir narsani chiroyli qilib ko‘rsatmoq, ishontirmoq»."},
{num:452,time:"00:35:26,679 --> 00:35:37,679",arabic:"وَأَنْتَ مَعِي أَمْ لَا؟",segs:["وَأَنْتَ مَعِي","أَمْ لَا؟"],full_uz:"Sen men bilanmisan yoki yo‘qmi?",note:null},
{num:453,time:"00:35:56,679 --> 00:36:22,679",arabic:"مُوسِيقَى",segs:null,full_uz:null,note:null},
{num:454,time:"00:36:22,679 --> 00:36:25,980",arabic:"قَدْ فَاضَ اللَّهُ عَلَى الْإِمَامِ أَبِي مُعَاوِيَةَ عِلْمًا جَمًّا",segs:["قَدْ فَاضَ اللَّهُ عَلَى الْإِمَامِ أَبِي مُعَاوِيَةَ","عِلْمًا جَمًّا"],full_uz:"Alloh Imom Abu Muoviyaga mo‘l-ko‘l ilm ato etgan.",note:"عِلْمٌ جَمٌّ — «ko‘p, mo‘l ilm»."},
{num:455,time:"00:36:25,980 --> 00:36:31,920",arabic:"هَذَا صَحِيحٌ، فَهُوَ حَافِظُ بَغْدَادَ وَمُحَدِّثُنَا، وَقَدْ أَحْسَنَّا صُنْعًا إِذِ انْقَطَعْنَا إِلَيْهِ",segs:["هَذَا صَحِيحٌ","فَهُوَ حَافِظُ بَغْدَادَ وَمُحَدِّثُنَا","وَقَدْ أَحْسَنَّا صُنْعًا إِذِ انْقَطَعْنَا إِلَيْهِ"],full_uz:"Bu to‘g‘ri. U Bag‘dodning hofizi va bizning muhaddisimiz. Unga butunlay berilganimiz juda yaxshi ish bo‘lgan.",note:"حَافِظُ بَغْدَادَ — hadis ilmidagi «Bag‘dod hofizi» unvoni; انْقَطَعَ إِلَيْهِ — «unga to‘liq berilmoq, uning darsiga bag‘ishlanmoq»."},
{num:456,time:"00:36:31,920 --> 00:36:34,980",arabic:"كَيْفَ تَجِدُكَ فِي عِلْمِ الْحَدِيثِ؟",segs:["كَيْفَ تَجِدُكَ","فِي عِلْمِ الْحَدِيثِ؟"],full_uz:"Hadis ilmida o‘zingizni qanday his qilyapsiz?",note:"كَيْفَ تَجِدُ نَفْسَكَ — «o‘zingni qanday deb bilasan, ahvoling qanday?»."},
{num:457,time:"00:36:35,719 --> 00:36:39,039",arabic:"فِي الْحَقِيقَةِ أَجِدُ صُعُوبَةً فِي كَثْرَةِ الْأَسَانِيدِ",segs:["فِي الْحَقِيقَةِ","أَجِدُ صُعُوبَةً فِي كَثْرَةِ الْأَسَانِيدِ"],full_uz:"To‘g‘risini aytsam, ko‘p sanadlar sabab biroz qiynalyapman.",note:"الْأَسَانِيدُ — «isnodlar, hadis sanadlari»; صُعُوبَةٌ — «qiyinchilik»."},
{num:458,time:"00:36:39,039 --> 00:36:45,619",arabic:"هَذَا أَمْرٌ بَدِيهِيٌّ، لِأَنَّنَا فِي أَوَّلِ الطَّرِيقِ وَسَيَسْهُلُ الْأَمْرُ مَعَ الْأَيَّامِ إِنْ شَاءَ اللَّهُ",segs:["هَذَا أَمْرٌ بَدِيهِيٌّ","لِأَنَّنَا فِي أَوَّلِ الطَّرِيقِ","وَسَيَسْهُلُ الْأَمْرُ مَعَ الْأَيَّامِ إِنْ شَاءَ اللَّهُ"],full_uz:"Bu tabiiy hol, chunki biz hali yo‘lning boshidamiz. Inshaalloh, kunlar o‘tishi bilan ish osonlashadi.",note:"أَمْرٌ بَدِيهِيٌّ — «tabiiy, o‘z-o‘zidan tushunarli holat»."},
{num:459,time:"00:36:45,619 --> 00:36:48,039",arabic:"أَرْجُو ذَلِكَ إِنْ شَاءَ اللَّهُ",segs:null,full_uz:"Shunday bo‘lishiga umid qilaman, inshaalloh.",note:null},
{num:460,time:"00:36:48,039 --> 00:36:50,980",arabic:"خُذْ عَنِّي هَذَا",segs:null,full_uz:"Buni mendan ol.",note:"خُذْ عَنِّي — «men aytgan narsani o‘zlashtir, mendan o‘rgan»."},
{num:461,time:"00:36:50,980 --> 00:36:54,599",arabic:"السَّلَامُ عَلَيْكُمْ",segs:null,full_uz:"Assalomu alaykum.",note:null},
{num:462,time:"00:36:55,980 --> 00:36:58,059",arabic:"وَعَلَيْكُمُ السَّلَامُ",segs:null,full_uz:"Va alaykum assalom.",note:null},
{num:463,time:"00:36:58,059 --> 00:36:59,780",arabic:"أَتُرِيدُ عَامِلًا؟",segs:null,full_uz:"Ishchi kerakmi?",note:"عَامِلٌ — «ishchi, mehnatkash»."},
{num:464,time:"00:36:59,780 --> 00:37:00,480",arabic:"بِدِرْهَمَيْنِ",segs:null,full_uz:"Ikki dirhamga.",note:"بِدِرْهَمَيْنِ — «ikki dirham evaziga»."},
{num:465,time:"00:37:00,480 --> 00:37:03,619",arabic:"عَلَى بَرَكَةِ اللَّهِ",segs:null,full_uz:"Allohning barakasi bilan.",note:"عَلَى بَرَكَةِ اللَّهِ — «Allohga tavakkal qilib, Allohning barakasi bilan»."},
{num:466,time:"00:37:22,980 --> 00:37:25,820",arabic:"أَنَا طَوْعُ أَمْرِكَ يَا سَيِّدِي يَا أَبَا الْفَضْلِ",segs:["أَنَا طَوْعُ أَمْرِكَ","يَا سَيِّدِي يَا أَبَا الْفَضْلِ"],full_uz:"Men amringizga bo‘ysunaman, ey hazratim, ey Abul-Fadl.",note:"طَوْعُ أَمْرِكَ — «amringizga to‘liq bo‘ysunuvchi, ixtiyoringizda»."},
{num:467,time:"00:37:25,820 --> 00:37:29,840",arabic:"لَا تَسْتَخِفَّ بِمَا أُوكِلَ إِلَيْكَ يَا ابْنَ سَهْلٍ",segs:["لَا تَسْتَخِفَّ بِمَا أُوكِلَ إِلَيْكَ","يَا ابْنَ سَهْلٍ"],full_uz:"Senga topshirilgan ishni arzimas deb bilma, ey Ibn Sahl.",note:"اِسْتَخَفَّ بِـ — «mensimaslik, arzimas deb bilmoq»; أُوكِلَ إِلَيْهِ — «unga topshirildi»."},
{num:468,time:"00:37:29,840 --> 00:37:33,400",arabic:"إِنَّهُ بِكْرُ أَمِيرِ الْمُؤْمِنِينَ وَرَيْحَانَتُهُ",segs:["إِنَّهُ بِكْرُ أَمِيرِ الْمُؤْمِنِينَ","وَرَيْحَانَتُهُ"],full_uz:"U mo‘minlar amirining to‘ng‘ich o‘g‘li va ko‘zining quvonchi.",note:"رَيْحَانَةٌ — so‘zma-so‘z «rayhon»; ko‘chma ma’noda «juda suyukli, ko‘z quvonchi»."},
{num:469,time:"00:37:33,400 --> 00:37:35,519",arabic:"وَأَيُّ خَطَإٍ صَغِيرٍ",segs:null,full_uz:"Har qanday kichik xato ham...",note:null},
{num:470,time:"00:37:35,519 --> 00:37:38,640",arabic:"مَهْمَا كَانَ صَغِيرًا",segs:null,full_uz:"Qanchalik kichik bo‘lmasin,",note:"مَهْمَا كَانَ — «qanchalik ... bo‘lmasin»."},
{num:471,time:"00:37:38,640 --> 00:37:41,080",arabic:"كَفِيلٌ أَنْ يَزُجَّ بِكَ فِي غَيَاهِبِ السُّجُونِ",segs:["كَفِيلٌ أَنْ يَزُجَّ بِكَ","فِي غَيَاهِبِ السُّجُونِ"],full_uz:"seni qamoqlarning qorong‘u qa’riga tashlash uchun yetarli bo‘lishi mumkin.",note:"زَجَّ بِهِ فِي — «biror joyga uloqtirmoq, tashlamoq»; غَيَاهِبُ السُّجُونِ — «zindonlarning qorong‘u qa’rlari»."},
{num:472,time:"00:37:41,080 --> 00:37:42,780",arabic:"وَلَنْ تَرَى الشَّمْسَ بَعْدَ",segs:null,full_uz:"Shundan keyin quyoshni boshqa ko‘rmaysan.",note:null},
{num:473,time:"00:37:42,780 --> 00:37:45,320",arabic:"اطْمَئِنَّ يَا مَوْلَايَ اطْمَئِنَّ",segs:["اطْمَئِنَّ يَا مَوْلَايَ","اطْمَئِنَّ"],full_uz:"Xotirjam bo‘ling, hazratim, xotirjam bo‘ling.",note:"اطْمَأَنَّ — «xotirjam bo‘lmoq, ko‘ngli tinchimoq»."},
{num:474,time:"00:37:45,320 --> 00:37:48,820",arabic:"سَأَحْرِصُ عَلَى ابْنِ أَمِيرِ الْمُؤْمِنِينَ حِرْصِي عَلَى نَفْسِي",segs:["سَأَحْرِصُ عَلَى ابْنِ أَمِيرِ الْمُؤْمِنِينَ","حِرْصِي عَلَى نَفْسِي"],full_uz:"Mo‘minlar amirining o‘g‘liga o‘zimga qay darajada e’tibor bersam, shunday ehtiyotkorlik bilan qarayman.",note:"حَرِيصٌ عَلَى — «qattiq e’tiborli, ehtiyotkor bo‘lmoq»."},
{num:475,time:"00:37:48,820 --> 00:37:51,800",arabic:"بَلْ أَشَدَّ مِنْ حِرْصِي عَلَى نَفْسِي إِنْ لَزِمَ ذَلِكَ",segs:["بَلْ أَشَدَّ مِنْ حِرْصِي عَلَى نَفْسِي","إِنْ لَزِمَ ذَلِكَ"],full_uz:"Hatto zarur bo‘lsa, o‘zimga bo‘lgan ehtiyotimdan ham ko‘proq.",note:"إِنْ لَزِمَ ذَلِكَ — «zarurat tug‘ilsa, kerak bo‘lsa»."},
{num:476,time:"00:37:51,800 --> 00:37:54,320",arabic:"سَتُثْبِتُ الْأَيَّامُ كَفَاءَتَكَ",segs:["سَتُثْبِتُ الْأَيَّامُ","كَفَاءَتَكَ"],full_uz:"Kunlar sening qobiliyatingni isbotlaydi.",note:"كَفَاءَةٌ — «malaka, qobiliyat, layoqat»."},
{num:477,time:"00:37:54,320 --> 00:37:59,960",arabic:"يَسُرُّنِي أَنَّ أَمِيرَ الْمُؤْمِنِينَ أَوْكَلَ إِلَيْكَ وِلَايَةَ خُرَاسَانَ يَا مَوْلَايَ",segs:["يَسُرُّنِي أَنَّ أَمِيرَ الْمُؤْمِنِينَ أَوْكَلَ إِلَيْكَ","وِلَايَةَ خُرَاسَانَ يَا مَوْلَايَ"],full_uz:"Mo‘minlar amiri Xuroson viloyatini sizga topshirganidan xursandman, hazratim.",note:"وِلَايَةٌ — «viloyat hokimligi, boshqaruv lavozimi»; أَوْكَلَ إِلَيْكَ — «senga topshirmoq»."},
{num:478,time:"00:37:59,960 --> 00:38:02,960",arabic:"بُورِكْتَ يَا ابْنَ سَهْلٍ بُورِكْتَ",segs:["بُورِكْتَ يَا ابْنَ سَهْلٍ","بُورِكْتَ"],full_uz:"Barakali bo‘l, ey Ibn Sahl, barakali bo‘l.",note:"بُورِكَ — «barakaga erishsin, muborak bo‘lsin»."},
{num:479,time:"00:38:02,960 --> 00:38:03,559",arabic:"بِفَضْلٍ",segs:null,full_uz:"Marhamat.",note:null},
{num:480,time:"00:38:03,559 --> 00:38:14,960",arabic:"وَمَا الَّذِي يَجْعَلُ بَالَكَ الْيَوْمَ؟",segs:["وَمَا الَّذِي يَجْعَلُ بَالَكَ الْيَوْمَ؟"],full_uz:"Bugun xayolingni nima band qilmoqda?",note:"يَجْعَلُ بَالَهُ — «xayolini band qilmoq»."},
{num:481,time:"00:38:17,940 --> 00:38:20,720",arabic:"الْحَقُّ يَا سَيِّدِي",segs:["الْحَقُّ يَا سَيِّدِي"],full_uz:"To‘g‘risini aytsam, hazratim,",note:null},
{num:482,time:"00:38:20,719 --> 00:38:24,799",arabic:"يُضَايِقُنِي مَسْكَنِي وَأُمِّي فِي كُوخِي مِنَ الْقَصَبِ",segs:["يُضَايِقُنِي مَسْكَنِي","وَأُمِّي فِي كُوخِي مِنَ الْقَصَبِ"],full_uz:"Qamishdan qurilgan kulbamizdagi uy-joyim meni bezovta qilmoqda.",note:"يُضَايِقُنِي — «meni qiynamoq, bezovta qilmoq»; كُوخٌ — «kulba»."},
{num:483,time:"00:38:24,799 --> 00:38:28,599",arabic:"لَا يَكَادُ يَسْتُرُنَا وَلَا يَرُدُّ عَنَّا حَرَّ الصَّيْفِ وَلَا قَرَّ الشِّتَاءِ",segs:["لَا يَكَادُ يَسْتُرُنَا","وَلَا يَرُدُّ عَنَّا حَرَّ الصَّيْفِ وَلَا قَرَّ الشِّتَاءِ"],full_uz:"U deyarli bizni pana qilmaydi, yozning issig‘i va qishning sovug‘idan ham himoya qilmaydi.",note:"لَا يَكَادُ — «deyarli ...maydi»; قَرُّ الشِّتَاءِ — «qishning qattiq sovug‘i»."},
{num:484,time:"00:38:28,599 --> 00:38:31,799",arabic:"ثُمَّ؟",segs:null,full_uz:"Keyin-chi?",note:null},
{num:485,time:"00:38:32,899 --> 00:38:33,959",arabic:"ثُمَّ",segs:null,full_uz:"Keyin...",note:null},
{num:486,time:"00:38:33,959 --> 00:38:38,019",arabic:"قُلْتُ لِنَفْسِي",segs:null,full_uz:"Ichimda o‘zimga dedim.",note:"قَالَ لِنَفْسِهِ — «ichida o‘ylamoq, o‘ziga-o‘zi demoq»."},
{num:487,time:"00:38:38,019 --> 00:38:42,839",arabic:"لَوْ أَقْرَضْتَنِي بَعْضَ الدَّرَاهِمِ مِنْ أُجْرَتِي لَاسْتَطَعْتُ أَنْ أَكْتَرِيَ دَارًا مُتَوَاضِعَةً تَسْتُرُنَا",segs:["لَوْ أَقْرَضْتَنِي بَعْضَ الدَّرَاهِمِ مِنْ أُجْرَتِي","لَاسْتَطَعْتُ أَنْ أَكْتَرِيَ دَارًا مُتَوَاضِعَةً تَسْتُرُنَا"],full_uz:"Agar maoshimdan bir necha dirhamni menga qarz bersangiz, bizni pana qiladigan oddiyroq uy ijaraga olishim mumkin edi.",note:"أَقْرَضَهُ — «unga qarz bermoq»; اكْتَرَى دَارًا — «uy ijaraga olmoq»."},
{num:488,time:"00:38:42,839 --> 00:38:48,119",arabic:"لَا أَرُدُّ لَكَ طَلَبًا وَلَكِنْ بِشَرْطٍ أَنْ يَكُونَ كِرَاءُ الْبَيْتِ عَلَى حِسَابِي",segs:["لَا أَرُدُّ لَكَ طَلَبًا","وَلَكِنْ بِشَرْطٍ","أَنْ يَكُونَ كِرَاءُ الْبَيْتِ عَلَى حِسَابِي"],full_uz:"Sening iltimosingni rad etmayman, lekin bir shart bilan: uy ijara pulini men to‘layman.",note:"عَلَى حِسَابِي — «mening hisobimdan, mening hisobimga»."},
{num:489,time:"00:38:48,119 --> 00:38:53,019",arabic:"أَخْشَى يَا سَيِّدِي أَنَّنِي لَنْ أَقْبَلَ هَذَا",segs:["أَخْشَى يَا سَيِّدِي","أَنَّنِي لَنْ أَقْبَلَ هَذَا"],full_uz:"Qo‘rqaman, hazratim, men bunga rozi bo‘lolmayman.",note:null},
{num:490,time:"00:38:53,019 --> 00:38:56,420",arabic:"فَأَنْتَ مَنْ عَلَّمَنِي عِزَّةَ النَّفْسِ بَعْدَ انْكِسَارٍ",segs:["فَأَنْتَ مَنْ عَلَّمَنِي","عِزَّةَ النَّفْسِ بَعْدَ انْكِسَارٍ"],full_uz:"Axir singan ruhimdan keyin o‘z qadr-qimmatimni bilishni menga siz o‘rgatgansiz.",note:"عِزَّةُ النَّفْسِ — «o‘z qadr-qimmati, or-nomusi»; انْكِسَارٌ — «sinish, ruhiy tushkunlik»."},
{num:491,time:"00:38:56,420 --> 00:39:02,139",arabic:"وَالْكَسْبُ وَلَوْ قَلِيلًا مِنْ عَمَلِ الْيَدِ خَيْرٌ مِنْ تَلَقِّي الصَّدَقَاتِ وَتَرَقُّبِ الْعَطِيَّاتِ",segs:["وَالْكَسْبُ وَلَوْ قَلِيلًا مِنْ عَمَلِ الْيَدِ","خَيْرٌ مِنْ تَلَقِّي الصَّدَقَاتِ وَتَرَقُّبِ الْعَطِيَّاتِ"],full_uz:"Qo‘l mehnati bilan, oz bo‘lsa ham, daromad topish sadaqa olish va ehson kutishdan yaxshiroq.",note:"عَمَلُ الْيَدِ — «qo‘l mehnati»; تَلَقِّي الصَّدَقَاتِ — «sadaqalarni qabul qilib olish»; الْعَطِيَّاتُ — «hadya va ehsonlar»."},
{num:492,time:"00:39:02,139 --> 00:39:04,000",arabic:"كَمَا تَشَاءُ",segs:null,full_uz:"O‘zing bilasan.",note:"كَمَا تَشَاءُ — «qanday istasang, o‘zing bilasan»."},
{num:493,time:"00:39:04,000 --> 00:39:11,619",arabic:"اذْهَبْ وَابْحَثْ عَنْ دَارٍ تُنَاسِبُكَ وَتَعَالَ خُذْ مِنَ الدَّرَاهِمِ مَا يَكْفِيكَ عَلَى سَبِيلِ الْقَرْضِ",segs:["اذْهَبْ وَابْحَثْ عَنْ دَارٍ تُنَاسِبُكَ","وَتَعَالَ خُذْ مِنَ الدَّرَاهِمِ مَا يَكْفِيكَ","عَلَى سَبِيلِ الْقَرْضِ"],full_uz:"Borib o‘zingga mos uy izla va kelib, yetadigan miqdorda dirhamni qarz tariqasida ol.",note:"عَلَى سَبِيلِ الْقَرْضِ — «qarz tariqasida»; مَا يَكْفِيكَ — «senga yetadigan miqdor»."},
{num:494,time:"00:39:11,619 --> 00:39:17,900",arabic:"شُكْرًا لَكَ يَا سَيِّدِي سَأَكْتُبُ دَيْنِي إِلَى أَجَلِهِ وَأَعِدُكَ بِالسَّدَادِ قَبْلَ قَضَاءِ الْأَجَلِ الْمُسَمَّى بَيْنَنَا",segs:["شُكْرًا لَكَ يَا سَيِّدِي","سَأَكْتُبُ دَيْنِي إِلَى أَجَلِهِ","وَأَعِدُكَ بِالسَّدَادِ قَبْلَ قَضَاءِ الْأَجَلِ الْمُسَمَّى بَيْنَنَا"],full_uz:"Rahmat, hazratim. Qarzimi belgilangan muddatigacha qaytaraman va kelishilgan muddat tugashidan oldin to‘lashga va’da beraman.",note:"أَجَلٌ مُسَمًّى — «belgilangan muddat»; سَدَادُ الدَّيْنِ — «qarzni to‘lash»."},
{num:495,time:"00:39:17,900 --> 00:39:18,700",arabic:"إِنْ شَاءَ اللَّهُ",segs:null,full_uz:"Inshaalloh.",note:null},
{num:496,time:"00:39:18,700 --> 00:39:26,539",arabic:"السَّلَامُ عَلَيْكُمْ يَا أُمَّ أَحْمَدَ",segs:["السَّلَامُ عَلَيْكُمْ","يَا أُمَّ أَحْمَدَ"],full_uz:"Assalomu alaykum, ey Ummu Ahmad.",note:null},
{num:497,time:"00:39:26,539 --> 00:39:28,579",arabic:"وَعَلَيْكُمُ السَّلَامُ وَرَحْمَةُ اللَّهِ",segs:null,full_uz:"Va alaykum assalom va Allohning rahmati bo‘lsin.",note:null},
{num:498,time:"00:39:28,579 --> 00:39:31,579",arabic:"تَأَخَّرْتَ عَنِّي يَا وَلَدِي",segs:["تَأَخَّرْتَ عَنِّي","يَا وَلَدِي"],full_uz:"Kech qolding, bolam.",note:"تَأَخَّرَ عَنْ — «kechikmoq»."},
{num:499,time:"00:39:31,579 --> 00:39:33,180",arabic:"أَكُنْتَ عِنْدَ عَمِّكَ؟",segs:null,full_uz:"Amakingnikida edingmi?",note:null},
{num:500,time:"00:39:33,180 --> 00:39:34,400",arabic:"لَا لَمْ أَكُنْ عِنْدَ عَمِّي",segs:null,full_uz:"Yo‘q, amamnikida emas edim.",note:null},
{num:501,time:"00:39:34,400 --> 00:39:36,139",arabic:"إِذَنْ؟",segs:null,full_uz:"Unda-chi?",note:null},
{num:502,time:"00:39:36,139 --> 00:39:36,900",arabic:"مَا هَذَا؟",segs:null,full_uz:"Bu nima?",note:null},
{num:503,time:"00:39:38,019 --> 00:39:38,760",arabic:"نُقُودٌ؟",segs:null,full_uz:"Pulmi?",note:"نُقُودٌ — «pul, naqd pul»."},
{num:504,time:"00:39:38,760 --> 00:39:41,880",arabic:"أُقْسِمُ لَكِ إِنَّهُ بَعْدَ خُرُوجِي مِنْ حَلْقَةِ شَيْخِي",segs:["أُقْسِمُ لَكِ","إِنَّهُ بَعْدَ خُرُوجِي مِنْ حَلْقَةِ شَيْخِي"],full_uz:"Sizga qasam ichamanki, ustozimning dars halqasidan chiqqanimdan keyin...",note:null},
{num:505,time:"00:39:41,880 --> 00:39:42,900",arabic:"أَيْنَ ذَهَبْتَ؟",segs:null,full_uz:"Qayerga bording?",note:null},
{num:506,time:"00:39:42,900 --> 00:39:48,400",arabic:"وَجَدْتُ تَاجِرًا يُنَزِّلُ بَعْضَ حَوَائِجِهِ إِبَّانَ عَوْدَتِهِ مِنْ عِنْدِ الشَّيْخِ هُشَيْمٍ",segs:["وَجَدْتُ تَاجِرًا يُنَزِّلُ بَعْضَ حَوَائِجِهِ","إِبَّانَ عَوْدَتِهِ مِنْ عِنْدِ الشَّيْخِ هُشَيْمٍ"],full_uz:"Shayx Hushaym huzuridan qaytayotganida ba’zi yuklarini tushirayotgan bir savdogarni uchratdim.",note:"إِبَّانَ — «... paytida, vaqtida»; حَوَائِجُ — «ehtiyojlar, buyumlar, yuklar»."},
{num:507,time:"00:39:48,400 --> 00:39:51,220",arabic:"فَسَاعَدْتُهُ فِي عَمَلِهِ وَأَخَذْتُ أُجْرَةَ ذَلِكَ دِرْهَمَيْنِ",segs:["فَسَاعَدْتُهُ فِي عَمَلِهِ","وَأَخَذْتُ أُجْرَةَ ذَلِكَ دِرْهَمَيْنِ"],full_uz:"Uning ishiga yordam berdim va buning uchun ikki dirham haq oldim.",note:"أُجْرَةٌ — «mehnat haqi»."},
{num:508,time:"00:39:51,220 --> 00:39:54,619",arabic:"لَا أُرِيدُ أَنْ يَشْغَلَكَ شَيْءٌ عَنْ دُرُوسِكَ يَا وَلَدِي",segs:["لَا أُرِيدُ أَنْ يَشْغَلَكَ شَيْءٌ","عَنْ دُرُوسِكَ يَا وَلَدِي"],full_uz:"Biror narsa seni darslaringdan chalg‘itishini istamayman, bolam.",note:"شَغَلَهُ عَنْ — «uni biror narsadan chalg‘itmoq»."},
{num:509,time:"00:39:54,619 --> 00:39:58,660",arabic:"فَمَا يَأْتِينَا مِنْ كِرَاءِ الدُّكَّانِ وَالسَّجَّادِ الَّذِي أَبِيعُهُ",segs:["فَمَا يَأْتِينَا مِنْ كِرَاءِ الدُّكَّانِ","وَالسَّجَّادِ الَّذِي أَبِيعُهُ"],full_uz:"Do‘kon ijarasidan va men sotadigan gilamlardan keladigan daromad...",note:null},
{num:510,time:"00:39:58,660 --> 00:40:00,119",arabic:"يَسُدَّانِ حَاجَتَنَا",segs:null,full_uz:"ehtiyojimizni qoplaydi.",note:"سَدَّ الْحَاجَةَ — «ehtiyojni qoplamoq, kifoya qilmoq»."},
{num:511,time:"00:40:00,119 --> 00:40:03,139",arabic:"الْيَدُ الْعَامِلَةُ خَيْرٌ مِنَ الْيَدِ الْخَامِلَةِ يَا أُمَّ أَحْمَدَ",segs:["الْيَدُ الْعَامِلَةُ خَيْرٌ مِنَ الْيَدِ الْخَامِلَةِ","يَا أُمَّ أَحْمَدَ"],full_uz:"Ishlaydigan qo‘l ishsiz qo‘ldan yaxshiroq, ey Ummu Ahmad.",note:"الْيَدُ الْعَامِلَةُ — «ishlaydigan qo‘l»; الْيَدُ الْخَامِلَةُ — «ishsiz, harakatsiz qo‘l»."},
{num:512,time:"00:40:03,139 --> 00:40:05,519",arabic:"صَدَقْتَ يَا بُنَيَّ",segs:["صَدَقْتَ","يَا بُنَيَّ"],full_uz:"To‘g‘ri aytding, bolam.",note:null},
{num:513,time:"00:40:05,519 --> 00:40:07,680",arabic:"أَنَا الْيَوْمَ صَائِمٌ وَالْحَمْدُ لِلَّهِ",segs:["أَنَا الْيَوْمَ صَائِمٌ","وَالْحَمْدُ لِلَّهِ"],full_uz:"Men bugun ro‘zadorman, alhamdulillah.",note:null},
{num:514,time:"00:40:07,680 --> 00:40:11,180",arabic:"الْحَمْدُ لِلَّهِ صَائِمٌ وَتَعْمَلُ فِي حَمْلِ الْأَغْرَاضِ",segs:["الْحَمْدُ لِلَّهِ صَائِمٌ","وَتَعْمَلُ فِي حَمْلِ الْأَغْرَاضِ"],full_uz:"Alhamdulillah, ro‘zador bo‘lib, yuk tashib ishlayapsan.",note:"حَمْلُ الْأَغْرَاضِ — «buyumlar/yuklarni ko‘tarib tashish»."},
{num:515,time:"00:40:11,179 --> 00:40:13,339",arabic:"مَاذَا أَفْعَلُ بِكَ يَا ابْنَ حَنْبَلٍ",segs:["مَاذَا أَفْعَلُ بِكَ","يَا ابْنَ حَنْبَلٍ"],full_uz:"Senga nima qilay, ey Ibn Hanbal?",note:null},
{num:516,time:"00:40:13,339 --> 00:40:17,839",arabic:"آهْ مِنْكَ يَا وَلَدِي",segs:["آهْ مِنْكَ","يَا وَلَدِي"],full_uz:"Voy sen-ey, bolam!",note:"آهْ مِنْكَ — hayrat, mehr yoki biroz koyish aralash hissiy ifoda."},
{num:517,time:"00:40:41,179 --> 00:40:49,500",arabic:"فَافْعَلِي بِي مَا تَشَائِينَ",segs:["فَافْعَلِي بِي","مَا تَشَائِينَ"],full_uz:"Unda menga xohlaganingni qil.",note:null},
{num:518,time:"00:40:49,500 --> 00:40:54,179",arabic:"فَلْنَتَمَتَّعْ بِحُرِّيَّتِي مِنِّي",segs:["فَلْنَتَمَتَّعْ بِحُرِّيَّتِي","مِنِّي"],full_uz:"Unda ozodligimdan bahramand bo‘laylik.",note:"تَمَتَّعَ بِـ — «bahramand bo‘lmoq, rohatlanmoq»."},
{num:519,time:"00:40:54,179 --> 00:40:58,359",arabic:"أَنَا حُرَّةٌ",segs:null,full_uz:"Men ozodman.",note:null},
]; if (typeof module !== 'undefined' && module.exports) { module.exports = lessons; }